// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title ERC1967Utils
/// @notice Storage slot helpers for ERC-1967 proxy patterns
/// @dev Defines standard storage slots for implementation, admin, and beacon addresses
library ERC1967Utils {
    /// @dev bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1)
    bytes32 internal constant IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    /// @dev bytes32(uint256(keccak256("eip1967.proxy.beacon")) - 1)
    bytes32 internal constant BEACON_SLOT =
        0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;

    /// @dev bytes32(uint256(keccak256("eip1967.proxy.admin")) - 1)
    bytes32 internal constant ADMIN_SLOT =
        0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

    error InvalidImplementation();
    error InvalidBeacon();

    event Upgraded(address indexed implementation);
    event BeaconUpgraded(address indexed beacon);
    event AdminChanged(address previousAdmin, address newAdmin);

    /// @notice Returns the current implementation address
    function getImplementation() internal view returns (address impl) {
        assembly {
            impl := sload(IMPLEMENTATION_SLOT)
        }
    }

    /// @notice Sets the implementation address
    function setImplementation(address newImplementation) internal {
        if (newImplementation.code.length == 0) revert InvalidImplementation();
        assembly {
            sstore(IMPLEMENTATION_SLOT, newImplementation)
        }
        emit Upgraded(newImplementation);
    }

    /// @notice Returns the current beacon address
    function getBeacon() internal view returns (address beacon) {
        assembly {
            beacon := sload(BEACON_SLOT)
        }
    }

    /// @notice Sets the beacon address
    function setBeacon(address newBeacon) internal {
        if (newBeacon.code.length == 0) revert InvalidBeacon();
        assembly {
            sstore(BEACON_SLOT, newBeacon)
        }
        emit BeaconUpgraded(newBeacon);
    }

    /// @notice Returns the current admin address
    function getAdmin() internal view returns (address admin) {
        assembly {
            admin := sload(ADMIN_SLOT)
        }
    }

    /// @notice Sets the admin address
    function setAdmin(address newAdmin) internal {
        address previous = getAdmin();
        assembly {
            sstore(ADMIN_SLOT, newAdmin)
        }
        emit AdminChanged(previous, newAdmin);
    }
}

contracts/base/ERC20Base.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title ERC20Base
/// @notice Minimal ERC20 implementation with EIP-2612 permit support
/// @dev Includes transfer, approve, transferFrom, permit, DOMAIN_SEPARATOR
abstract contract ERC20Base {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;

    // EIP-2612
    bytes32 private immutable _cachedDomainSeparator;
    uint256 private immutable _cachedChainId;
    bytes32 private immutable _nameHash;

    struct Checkpoint { uint256 blockNumber; uint256 value; }
    mapping(address => Checkpoint[]) private _balanceCheckpoints;
    Checkpoint[] private _supplyCheckpoints;
    error FutureLookup();
    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");

    error InsufficientBalance();
    error InsufficientAllowance();
    error InvalidPermit();
    error PermitExpired();
    error ZeroAddress();

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;

        _nameHash = keccak256(bytes(_name));
        _cachedChainId = block.chainid;
        _cachedDomainSeparator = _domainSeparator();
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _cachedChainId ? _cachedDomainSeparator : _domainSeparator();
    }

    function _domainSeparator() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            _nameHash, keccak256("1"), block.chainid, address(this)
        ));
    }

    /// @notice Historical direct balances; delegation is not supported.
    function getPastBalance(address account, uint256 blockNumber) public view returns (uint256) {
        return _lookup(_balanceCheckpoints[account], blockNumber);
    }

    function getPastVotes(address account, uint256 blockNumber) external view returns (uint256) {
        return getPastBalance(account, blockNumber);
    }

    function getPastTotalSupply(uint256 blockNumber) external view returns (uint256) {
        return _lookup(_supplyCheckpoints, blockNumber);
    }

    function _lookup(Checkpoint[] storage checkpoints, uint256 blockNumber) private view returns (uint256) {
        if (blockNumber >= block.number) revert FutureLookup();
        uint256 low;
        uint256 high = checkpoints.length;
        while (low < high) {
            uint256 mid = low + (high - low) / 2;
            if (checkpoints[mid].blockNumber > blockNumber) high = mid;
            else low = mid + 1;
        }
        return low == 0 ? 0 : checkpoints[low - 1].value;
    }

    function _checkpoint(Checkpoint[] storage checkpoints, uint256 value) private {
        uint256 length = checkpoints.length;
        if (length > 0 && checkpoints[length - 1].blockNumber == block.number) {
            checkpoints[length - 1].value = value;
        } else {
            checkpoints.push(Checkpoint(block.number, value));
        }
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 currentAllowance = allowance[from][msg.sender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < amount) revert InsufficientAllowance();
            unchecked {
                allowance[from][msg.sender] = currentAllowance - amount;
            }
        }
        _transfer(from, to, amount);
        return true;
    }

    /// @notice EIP-2612 permit: approve via signature
    function permit(
        address owner_,
        address spender,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        if (block.timestamp > deadline) revert PermitExpired();

        bytes32 structHash = keccak256(
            abi.encode(PERMIT_TYPEHASH, owner_, spender, value, nonces[owner_]++, deadline)
        );
        bytes32 digest = keccak256(
            abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), structHash)
        );

        address recovered = ecrecover(digest, v, r, s);
        if (recovered == address(0) || recovered != owner_) revert InvalidPermit();

        _approve(owner_, spender, value);
    }

    function _transfer(address from, address to, uint256 amount) internal virtual {
        if (from == address(0)) revert ZeroAddress();
        if (to == address(0)) revert ZeroAddress();
        if (balanceOf[from] < amount) revert InsufficientBalance();

        unchecked {
            balanceOf[from] -= amount;
        }
        balanceOf[to] += amount;
        _checkpoint(_balanceCheckpoints[from], balanceOf[from]);
        if (from != to) _checkpoint(_balanceCheckpoints[to], balanceOf[to]);
        emit Transfer(from, to, amount);
    }

    function _approve(address owner_, address spender, uint256 amount) internal {
        allowance[owner_][spender] = amount;
        emit Approval(owner_, spender, amount);
    }

    function _mint(address to, uint256 amount) internal {
        if (to == address(0)) revert ZeroAddress();
        totalSupply += amount;
        balanceOf[to] += amount;
        _checkpoint(_balanceCheckpoints[to], balanceOf[to]);
        _checkpoint(_supplyCheckpoints, totalSupply);
        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) internal {
        if (balanceOf[from] < amount) revert InsufficientBalance();
        unchecked {
            balanceOf[from] -= amount;
        }
        totalSupply -= amount;
        _checkpoint(_balanceCheckpoints[from], balanceOf[from]);
        _checkpoint(_supplyCheckpoints, totalSupply);
        emit Transfer(from, address(0), amount);
    }
}

contracts/base/ERC721Base.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title ERC721Base
/// @notice Minimal ERC721 implementation with ERC165 introspection
/// @dev Supports transfer, safeTransfer, approve, setApprovalForAll, supportsInterface
abstract contract ERC721Base {
    string public name;
    string public symbol;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    error TokenNotFound();
    error NotTokenOwner();
    error NotApproved();
    error ZeroAddress();
    error AlreadyMinted();
    error NonERC721Receiver();

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner, address indexed operator, bool approved);

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    /// @notice ERC165: Returns true for ERC721 and ERC165 interface IDs
    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {
        return
            interfaceId == 0x80ac58cd || // ERC721
            interfaceId == 0x01ffc9a7;   // ERC165
    }

    function balanceOf(address owner_) public view returns (uint256) {
        if (owner_ == address(0)) revert ZeroAddress();
        return _balances[owner_];
    }

    function ownerOf(uint256 tokenId) public view returns (address owner_) {
        owner_ = _owners[tokenId];
        if (owner_ == address(0)) revert TokenNotFound();
    }

    function approve(address to, uint256 tokenId) external {
        address owner_ = ownerOf(tokenId);
        if (msg.sender != owner_ && !isApprovedForAll(owner_, msg.sender)) {
            revert NotApproved();
        }
        _tokenApprovals[tokenId] = to;
        emit Approval(owner_, to, tokenId);
    }

    function getApproved(uint256 tokenId) public view returns (address) {
        if (_owners[tokenId] == address(0)) revert TokenNotFound();
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) external {
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address owner_, address operator) public view returns (bool) {
        return _operatorApprovals[owner_][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public virtual {
        if (!_isApprovedOrOwner(msg.sender, tokenId)) revert NotApproved();
        _transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                if (retval != IERC721Receiver.onERC721Received.selector) {
                    revert NonERC721Receiver();
                }
            } catch (bytes memory reason) {
                if (reason.length == 0) revert NonERC721Receiver();
                assembly { revert(add(reason, 32), mload(reason)) }
            }
        }
    }

    function _mint(address to, uint256 tokenId) internal virtual {
        if (to == address(0)) revert ZeroAddress();
        if (_owners[tokenId] != address(0)) revert AlreadyMinted();

        _balances[to]++;
        _owners[tokenId] = to;
        emit Transfer(address(0), to, tokenId);
    }

    function _burn(uint256 tokenId) internal virtual {
        address owner_ = ownerOf(tokenId);
        delete _tokenApprovals[tokenId];
        _balances[owner_]--;
        delete _owners[tokenId];
        emit Transfer(owner_, address(0), tokenId);
    }

    function _transfer(address from, address to, uint256 tokenId) internal virtual {
        if (ownerOf(tokenId) != from) revert NotTokenOwner();
        if (to == address(0)) revert ZeroAddress();

        delete _tokenApprovals[tokenId];
        _balances[from]--;
        _balances[to]++;
        _owners[tokenId] = to;
        emit Transfer(from, to, tokenId);
    }

    function _isApprovedOrOwner(address spender, uint256 tokenId) internal view returns (bool) {
        address owner_ = ownerOf(tokenId);
        return (spender == owner_ || _tokenApprovals[tokenId] == spender || _operatorApprovals[owner_][spender]);
    }

    function _exists(uint256 tokenId) internal view returns (bool) {
        return _owners[tokenId] != address(0);
    }
}

interface IERC721Receiver {
    function onERC721Received(
        address operator,
        address from,
        uint256 tokenId,
        bytes calldata data
    ) external returns (bytes4);
}

contracts/base/ERC721Enumerable.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "./ERC721Base.sol";

/// @title ERC721Enumerable
/// @notice Enumeration extension for ERC721: totalSupply, tokenByIndex, tokenOfOwnerByIndex
abstract contract ERC721Enumerable is ERC721Base {
    uint256[] private _allTokens;
    mapping(uint256 => uint256) private _allTokensIndex;
    mapping(address => uint256[]) private _ownedTokens;
    mapping(uint256 => uint256) private _ownedTokensIndex;

    error IndexOutOfBounds();

    /// @notice ERC165: add ERC721Enumerable interface support
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return
            interfaceId == 0x780e9d63 || // ERC721Enumerable
            super.supportsInterface(interfaceId);
    }

    /// @notice Returns the total number of tokens
    function totalSupply() public view returns (uint256) {
        return _allTokens.length;
    }

    /// @notice Returns the token ID at a given index across all tokens
    function tokenByIndex(uint256 index) external view returns (uint256) {
        if (index >= _allTokens.length) revert IndexOutOfBounds();
        return _allTokens[index];
    }

    /// @notice Returns the token ID at a given index for an owner
    function tokenOfOwnerByIndex(address owner_, uint256 index) external view returns (uint256) {
        if (index >= _ownedTokens[owner_].length) revert IndexOutOfBounds();
        return _ownedTokens[owner_][index];
    }

    function _mint(address to, uint256 tokenId) internal virtual override {
        super._mint(to, tokenId);
        _addTokenToAllEnumeration(tokenId);
        _addTokenToOwnerEnumeration(to, tokenId);
    }

    function _burn(uint256 tokenId) internal virtual override {
        address owner_ = ownerOf(tokenId);
        _removeTokenFromOwnerEnumeration(owner_, tokenId);
        _removeTokenFromAllEnumeration(tokenId);
        super._burn(tokenId);
    }

    function _transfer(address from, address to, uint256 tokenId) internal virtual override {
        if (from != to) {
            _removeTokenFromOwnerEnumeration(from, tokenId);
            _addTokenToOwnerEnumeration(to, tokenId);
        }
        super._transfer(from, to, tokenId);
    }

    function _addTokenToAllEnumeration(uint256 tokenId) private {
        _allTokensIndex[tokenId] = _allTokens.length;
        _allTokens.push(tokenId);
    }

    function _addTokenToOwnerEnumeration(address to, uint256 tokenId) private {
        _ownedTokensIndex[tokenId] = _ownedTokens[to].length;
        _ownedTokens[to].push(tokenId);
    }

    function _removeTokenFromAllEnumeration(uint256 tokenId) private {
        uint256 lastIndex = _allTokens.length - 1;
        uint256 tokenIndex = _allTokensIndex[tokenId];

        uint256 lastTokenId = _allTokens[lastIndex];
        _allTokens[tokenIndex] = lastTokenId;
        _allTokensIndex[lastTokenId] = tokenIndex;

        _allTokens.pop();
        delete _allTokensIndex[tokenId];
    }

    function _removeTokenFromOwnerEnumeration(address from, uint256 tokenId) private {
        uint256 lastIndex = _ownedTokens[from].length - 1;
        uint256 tokenIndex = _ownedTokensIndex[tokenId];

        if (tokenIndex != lastIndex) {
            uint256 lastTokenId = _ownedTokens[from][lastIndex];
            _ownedTokens[from][tokenIndex] = lastTokenId;
            _ownedTokensIndex[lastTokenId] = tokenIndex;
        }

        _ownedTokens[from].pop();
        delete _ownedTokensIndex[tokenId];
    }
}

contracts/base/Initializable.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title Initializable
/// @notice Initialization guard for proxied contracts. Replaces constructors.
/// @dev Supports versioned reinitializers and disableInitializers for implementations.
abstract contract Initializable {
    /// @dev Storage slot for initialization state (avoids storage collision in proxies)
    /// keccak256("sidiora.initializable.storage") - 1
    bytes32 private constant _INITIALIZABLE_STORAGE =
        0x4377386e2795aba8c0ce23a1e6e67bac790e4b4166f14b7e9365049ab946f8c0;

    struct InitializableStorage {
        uint64 initialized;
        bool initializing;
    }

    error AlreadyInitialized();
    error NotInitializing();

    event Initialized(uint64 version);

    modifier initializer() {
        InitializableStorage storage $ = _getInitializableStorage();
        bool isTopLevel = !$.initializing;

        uint64 initialized = $.initialized;
        if (initialized >= 1 && isTopLevel) revert AlreadyInitialized();
        if (initialized != 0 && !isTopLevel) revert AlreadyInitialized();

        if (isTopLevel) {
            $.initializing = true;
        }
        $.initialized = 1;
        _;
        if (isTopLevel) {
            $.initializing = false;
            emit Initialized(1);
        }
    }

    modifier reinitializer(uint64 version) {
        InitializableStorage storage $ = _getInitializableStorage();
        if ($.initializing || $.initialized >= version) revert AlreadyInitialized();
        $.initialized = version;
        $.initializing = true;
        _;
        $.initializing = false;
        emit Initialized(version);
    }

    modifier onlyInitializing() {
        if (!_isInitializing()) revert NotInitializing();
        _;
    }

    /// @notice Locks the contract, preventing any future initialization
    /// @dev Call in the constructor of implementation contracts
    function _disableInitializers() internal virtual {
        InitializableStorage storage $ = _getInitializableStorage();
        if ($.initializing) revert AlreadyInitialized();
        if ($.initialized != type(uint64).max) {
            $.initialized = type(uint64).max;
            emit Initialized(type(uint64).max);
        }
    }

    function _getInitializedVersion() internal view returns (uint64) {
        return _getInitializableStorage().initialized;
    }

    function _isInitializing() internal view returns (bool) {
        return _getInitializableStorage().initializing;
    }

    function _getInitializableStorage() private pure returns (InitializableStorage storage $) {
        assembly {
            $.slot := _INITIALIZABLE_STORAGE
        }
    }
}

