// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title Pausable
/// @notice Emergency pause mechanism with whenNotPaused/whenPaused modifiers
abstract contract Pausable {
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Canonical incident-controller status; does not expose recovery authority.
    function emergencyPaused() external view returns (bool) { return _paused(); }

    /// @dev keccak256("sidiora.pausable.storage") - 1
    bytes32 private constant _PAUSABLE_SLOT =
        0x62e78cea01bee320cd4e420270b5ea74000d11b0c9f74754ebdbfc544b05a258;

    error Paused();
    error NotPaused();

    event PauseToggled(bool paused);

    modifier whenNotPaused() {
        if (_paused()) revert Paused();
        _;
    }

    modifier whenPaused() {
        if (!_paused()) revert NotPaused();
        _;
    }

    function _paused() internal view returns (bool paused_) {
        bytes32 slot = _PAUSABLE_SLOT;
        assembly {
            paused_ := sload(slot)
        }
    }

    function _pause() internal whenNotPaused {
        bytes32 slot = _PAUSABLE_SLOT;
        assembly {
            sstore(slot, 1)
        }
        emit PauseToggled(true);
    }

    function _unpause() internal whenPaused {
        bytes32 slot = _PAUSABLE_SLOT;
        assembly {
            sstore(slot, 0)
        }
        emit PauseToggled(false);
    }
}

contracts/base/Proxy.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title Proxy
/// @notice Base delegatecall proxy. Subclasses must implement _implementation().
/// @dev All calls are forwarded to the implementation via delegatecall.
abstract contract Proxy {
    /// @notice Returns the current implementation address
    function _implementation() internal view virtual returns (address);

    /// @notice Delegates the current call to the implementation
    function _delegate(address implementation) internal virtual {
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), implementation, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    /// @notice Fallback function delegates all calls to the implementation
    fallback() external payable virtual {
        _delegate(_implementation());
    }

    /// @notice Receive function delegates to the implementation
    receive() external payable virtual {
        _delegate(_implementation());
    }
}

