// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/ERC20Base.sol";

interface ITokenTransferPool { function opticalAddress() external view returns (address); }
interface ITokenTransferOptical {
    function getFlags() external view returns (uint8);
    function beforeTokenTransfer(address pool, address from, address to, uint256 amount) external;
}

/// @title SidioraERC20
/// @notice Minimal immutable ERC20 token deployed via CREATE2 by the Factory
/// @dev Total supply minted once in constructor to recipient. No mint/burn after creation.
contract SidioraERC20 is ERC20Base {
    address public immutable deploymentFactory;
    address public pool;
    error InvalidPoolBinding();

    /// @notice One-time binding by deployer before circulating supply is released.
    function bindPool(address pool_) external {
        if (msg.sender != deploymentFactory || pool != address(0) || pool_.code.length == 0) revert InvalidPoolBinding();
        pool = pool_;
    }

    function _transfer(address from, address to, uint256 amount) internal override {
        if (pool != address(0)) {
            address optical = ITokenTransferPool(pool).opticalAddress();
            if (optical != address(0) && (ITokenTransferOptical(optical).getFlags() & 16) != 0) {
                ITokenTransferOptical(optical).beforeTokenTransfer(pool, from, to, amount);
            }
        }
        super._transfer(from, to, amount);
    }

    /// @param _name Token name
    /// @param _symbol Token symbol
    /// @param _totalSupply Total supply to mint (6 decimals)
    /// @param _recipient Address to receive the entire supply (the pool)
    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _totalSupply,
        address _recipient
    ) ERC20Base(_name, _symbol, 6) {
        deploymentFactory = msg.sender;
        if (_recipient == address(0)) revert ZeroAddress();
        _mint(_recipient, _totalSupply);
    }
}

contracts/core/SidioraFactory.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/ISidioraFactory.sol";
import "../interfaces/IProtocolConfig.sol";
import "../interfaces/IPoolRegistry.sol";
import "../interfaces/ISidioraNFT.sol";
import "../interfaces/IEventEmitter.sol";
import "../interfaces/IFeeAccumulator.sol";
import "../interfaces/ISidioraPool.sol";
import "../libraries/TransferHelper.sol";
import "../interfaces/ITreasury.sol";
import "./SidioraERC20.sol";
import "../libraries/PoolAddress.sol";

/// @title SidioraFactory
/// @notice Market creation orchestrator. One transaction creates token + pool + NFT.
/// @dev UUPS proxy. CREATE2 deploys SidioraERC20, BeaconProxy deploys SidioraPool.
contract SidioraFactory is ISidioraFactory, Initializable, UUPSUpgradeable, AccessControl {
    bytes32 public constant ROUTER_ROLE = keccak256("ROUTER_ROLE");

    address public override poolBeacon;
    address public override nftContract;
    address public override poolRegistry;
    address public override eventEmitter;
    address public override protocolConfig;
    address public override treasury;
    address public feeAccumulator;
    address public usdlAddress;

    mapping(address => uint256) private _nonces;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _poolBeacon,
        address _nftContract,
        address _poolRegistry,
        address _eventEmitter,
        address _protocolConfig,
        address _treasury,
        address _feeAccumulator,
        address _usdlAddress,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        if (_poolBeacon == address(0)) revert ZeroAddress();
        if (_usdlAddress.code.length == 0 || _poolBeacon.code.length == 0 ||
            _nftContract.code.length == 0 || _poolRegistry.code.length == 0 ||
            _protocolConfig.code.length == 0 || _treasury.code.length == 0 ||
            _feeAccumulator.code.length == 0) revert ZeroAddress();

        poolBeacon = _poolBeacon;
        nftContract = _nftContract;
        poolRegistry = _poolRegistry;
        eventEmitter = _eventEmitter;
        protocolConfig = _protocolConfig;
        treasury = _treasury;
        feeAccumulator = _feeAccumulator;
        usdlAddress = _usdlAddress;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    /// @inheritdoc ISidioraFactory
    function createMarket(
        string calldata name,
        string calldata symbol,
        uint8 feeStrategy,
        address optical
    ) external override returns (address tokenAddr, address poolAddr, uint256 nftId) {
        // Charge creation fee from caller
        uint256 creationFee = IProtocolConfig(protocolConfig).creationFee();
        if (creationFee > 0) {
            TransferHelper.safeTransferFrom(usdlAddress, msg.sender, treasury, creationFee);
            ITreasury(treasury).recordDeposit(usdlAddress, creationFee);
        }
        return _createMarket(msg.sender, name, symbol, feeStrategy, optical);
    }

    /// @inheritdoc ISidioraFactory
    function createMarketFor(
        address creator,
        string calldata name,
        string calldata symbol,
        uint8 feeStrategy,
        address optical
    ) external override onlyRole(ROUTER_ROLE) returns (address tokenAddr, address poolAddr, uint256 nftId) {
        if (creator == address(0)) revert ZeroAddress();
        return _createMarket(creator, name, symbol, feeStrategy, optical);
    }

    /// @inheritdoc ISidioraFactory
    function getNonce(address creator) external view override returns (uint256) {
        return _nonces[creator];
    }

    function _createMarket(
        address creator,
        string calldata name,
        string calldata symbol,
        uint8 feeStrategy,
        address optical
    ) internal returns (address tokenAddr, address poolAddr, uint256 nftId) {
        IProtocolConfig config = IProtocolConfig(protocolConfig);
        uint256 virtualUsdl = config.virtualUsdlDefault();
        uint256 virtualToken = config.virtualTokenDefault();

        if (virtualUsdl == 0 || virtualToken == 0 || virtualUsdl > type(uint128).max ||
            virtualToken > type(uint128).max || feeStrategy > 3 ||
            (optical != address(0) && optical.code.length == 0)) revert ZeroAddress();

        // CREATE2 deploy SidioraERC20
        uint256 nonce = _nonces[creator]++;
        bytes32 salt = keccak256(abi.encodePacked(creator, name, symbol, nonce));

        tokenAddr = address(
            new SidioraERC20{salt: salt}(name, symbol, virtualToken, address(this))
        );

        // Deploy BeaconProxy for SidioraPool
        bytes memory poolInitData = abi.encodeCall(
            ISidioraPool.initialize,
            (
                tokenAddr,
                usdlAddress,
                optical,
                feeAccumulator,
                eventEmitter,
                protocolConfig,
                creator, // creator is guardian initially
                virtualUsdl,
                virtualToken
            )
        );

        bytes32 poolSalt = keccak256(abi.encodePacked(tokenAddr));
        poolAddr = _deployBeaconProxy(poolSalt, poolInitData);

        // Authorize pool on FeeAccumulator to record fees
        IFeeAccumulator(feeAccumulator).authorizePool(poolAddr);

        // Mint fee rights, then publish authoritative registry attachment before
        // the token's transfer-policy callback observes initial liquidity.
        nftId = ISidioraNFT(nftContract).mint(creator, poolAddr, feeStrategy);
        IPoolRegistry(poolRegistry).register(poolAddr, tokenAddr, creator, optical, nftId);
        SidioraERC20(tokenAddr).bindPool(poolAddr);
        TransferHelper.safeTransfer(tokenAddr, poolAddr, virtualToken);

        // Emit MarketCreated via EventEmitter
        if (eventEmitter != address(0)) {
            bytes32 poolId = bytes32(uint256(uint160(poolAddr)));
            IEventEmitter(eventEmitter).emitTokenDeployed(tokenAddr, poolAddr, creator, salt, name, symbol, 6, virtualToken);
            IEventEmitter(eventEmitter).emitMarketCreated(poolId, tokenAddr, creator, poolAddr, optical);
        }

        emit MarketCreated(tokenAddr, poolAddr, creator, nftId, optical);
    }

    /// @notice Predict the actual pool deployment from exact initialization calldata.
    function predictPoolAddress(address token, address creator, address optical) external view returns (address) {
        bytes memory initData = abi.encodeCall(ISidioraPool.initialize, (
            token, usdlAddress, optical, feeAccumulator, eventEmitter, protocolConfig, creator,
            IProtocolConfig(protocolConfig).virtualUsdlDefault(), IProtocolConfig(protocolConfig).virtualTokenDefault()
        ));
        return PoolAddress.computeAddress(address(this), poolBeacon, token, type(BeaconProxyDeployer).creationCode, initData);
    }

    function _deployBeaconProxy(bytes32 salt, bytes memory initData) internal returns (address proxy) {
        bytes memory creationCode = abi.encodePacked(
            type(BeaconProxyDeployer).creationCode,
            abi.encode(poolBeacon, initData)
        );
        assembly {
            proxy := create2(0, add(creationCode, 0x20), mload(creationCode), salt)
            if iszero(proxy) { revert(0, 0) }
        }
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

/// @title BeaconProxyDeployer
/// @dev Minimal beacon proxy for CREATE2 deployment by factory.
///      Reads implementation from beacon, delegates all calls.
contract BeaconProxyDeployer {
    error BeaconCallFailed();

    constructor(address beacon, bytes memory data) {
        // Store beacon in ERC1967 slot
        bytes32 slot = 0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;
        assembly { sstore(slot, beacon) }

        // Initialize via delegatecall
        address impl = _getImpl(beacon);
        if (data.length > 0) {
            (bool ok, ) = impl.delegatecall(data);
            require(ok, "init failed");
        }
    }

    fallback() external payable {
        address impl = _getImpl(_beacon());
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    receive() external payable {
        address impl = _getImpl(_beacon());
        assembly {
            let result := delegatecall(gas(), impl, 0, 0, 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    function _beacon() internal view returns (address b) {
        bytes32 slot = 0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;
        assembly { b := sload(slot) }
    }

    function _getImpl(address beacon) internal view returns (address impl) {
        (bool ok, bytes memory data) = beacon.staticcall(abi.encodeWithSignature("implementation()"));
        if (!ok || data.length < 32) revert BeaconCallFailed();
        impl = abi.decode(data, (address));
        if (impl.code.length == 0) revert BeaconCallFailed();
    }
}

contracts/core/SidioraNFT.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/ERC721Enumerable.sol";
import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/ISidioraNFT.sol";
import "../interfaces/IEventEmitter.sol";

/// @title SidioraNFT
/// @notice ERC721 representing fee rights for a pool. One NFT per pool.
/// @dev UUPS proxy singleton. Factory mints via MINTER_ROLE.
contract SidioraNFT is ISidioraNFT, ERC721Enumerable, Initializable, UUPSUpgradeable, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant STRATEGY_SETTER_ROLE = keccak256("STRATEGY_SETTER_ROLE");

    uint256 public override nextTokenId;

    mapping(uint256 => uint8) private _feeStrategy;
    mapping(uint256 => address) private _poolAddress;

    address public eventEmitter;
    // Appended storage: one fee-right NFT per pool.
    mapping(address => uint256) public poolTokenId;
    error DuplicatePool();
    error UnsupportedSnapshotToken();
    error PoolIndexMigrationRequired();
    uint256 public poolIndexMigrationCursor;
    bool public poolIndexReady;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() ERC721Base("", "") {
        _disableInitializers();
    }

    function initialize(
        string calldata _name,
        string calldata _symbol,
        address _eventEmitter,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        name = _name;
        symbol = _symbol;
        eventEmitter = _eventEmitter;
        nextTokenId = 1; // Start from 1
        poolIndexReady = true;
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    /// @inheritdoc ISidioraNFT
    function mint(
        address to,
        address pool,
        uint8 strategy
    ) external override onlyRole(MINTER_ROLE) returns (uint256 tokenId) {
        if (to == address(0)) revert ZeroAddress();
        if (pool == address(0)) revert ZeroAddress();
        if (strategy > 3) revert InvalidStrategy();
        if (strategy == 2) _requireAirdropSupported(pool);

        if (!poolIndexReady) revert PoolIndexMigrationRequired();
        if (poolTokenId[pool] != 0) revert DuplicatePool();
        tokenId = nextTokenId++;
        poolTokenId[pool] = tokenId;

        _feeStrategy[tokenId] = strategy;
        _poolAddress[tokenId] = pool;
        _mint(to, tokenId);
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, address(0), tokenId, "") returns (bytes4 result) {
                if (result != IERC721Receiver.onERC721Received.selector) revert NonERC721Receiver();
            } catch (bytes memory reason) {
                if (reason.length == 0) revert NonERC721Receiver();
                assembly { revert(add(reason, 32), mload(reason)) }
            }
        }

        emit PoolNFTMinted(tokenId, to, pool);
        if (eventEmitter != address(0)) IEventEmitter(eventEmitter).emitNftMint(tokenId, to, pool, strategy);
    }

    /// @notice Populate the appended uniqueness index after an upgrade, in bounded batches.
    /// @dev Duplicate legacy rights fail closed and require an explicit reconciliation decision.
    function migratePoolIndex(uint256 maxItems) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (poolIndexReady) return;
        if (maxItems == 0 || maxItems > 1000) revert PoolIndexMigrationRequired();
        uint256 cursor = poolIndexMigrationCursor;
        if (cursor == 0) cursor = 1;
        uint256 remaining = nextTokenId - cursor;
        uint256 end = cursor + (maxItems < remaining ? maxItems : remaining);
        for (; cursor < end; ++cursor) {
            address pool = _poolAddress[cursor];
            if (poolTokenId[pool] != 0 && poolTokenId[pool] != cursor) revert DuplicatePool();
            poolTokenId[pool] = cursor;
        }
        poolIndexMigrationCursor = cursor;
        if (cursor == nextTokenId) poolIndexReady = true;
    }

    /// @inheritdoc ISidioraNFT
    function getFeeStrategy(uint256 tokenId) external view override returns (uint8) {
        if (!_exists(tokenId)) revert TokenNotFound();
        return _feeStrategy[tokenId];
    }

    /// @inheritdoc ISidioraNFT
    function setFeeStrategy(uint256 tokenId, uint8 newStrategy) external override {
        if (!_exists(tokenId)) revert TokenNotFound();
        if (newStrategy > 3) revert InvalidStrategy();

        // Only token owner, approved, or STRATEGY_SETTER_ROLE can change
        if (!_isApprovedOrOwner(msg.sender, tokenId) && !hasRole(STRATEGY_SETTER_ROLE, msg.sender)) {
            revert NotApproved();
        }

        if (newStrategy == 2) _requireAirdropSupported(_poolAddress[tokenId]);
        uint8 oldStrategy = _feeStrategy[tokenId];
        _feeStrategy[tokenId] = newStrategy;

        emit FeeStrategyChanged(tokenId, oldStrategy, newStrategy);
        if (eventEmitter != address(0)) IEventEmitter(eventEmitter).emitFeeStrategyChanged(
            bytes32(uint256(uint160(_poolAddress[tokenId]))), tokenId, oldStrategy, newStrategy);
    }

    /// @inheritdoc ISidioraNFT
    function getPoolAddress(uint256 tokenId) external view override returns (address) {
        if (!_exists(tokenId)) revert TokenNotFound();
        return _poolAddress[tokenId];
    }

    function _requireAirdropSupported(address pool) internal view {
        (bool ok, bytes memory data) = pool.staticcall(abi.encodeWithSignature("feeAccumulator()"));
        if (!ok || data.length != 32) revert UnsupportedSnapshotToken();
        address accumulator = abi.decode(data, (address));
        if (accumulator.code.length == 0) revert UnsupportedSnapshotToken();
        (ok, data) = accumulator.staticcall(abi.encodeWithSignature("supportsAirdrop(address)", pool));
        if (!ok || data.length != 32 || !abi.decode(data, (bool))) revert UnsupportedSnapshotToken();
    }

    function _transfer(address from, address to, uint256 tokenId) internal override {
        super._transfer(from, to, tokenId);
        if (eventEmitter != address(0)) IEventEmitter(eventEmitter).emitNftTransfer(address(this), from, to, tokenId);
    }

    /// @notice ERC165 override
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return ERC721Enumerable.supportsInterface(interfaceId);
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/core/SidioraPool.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/ReentrancyGuard.sol";
import "../base/Pausable.sol";
import "../interfaces/ISidioraPool.sol";
import "../interfaces/IProtocolConfig.sol";
import "../interfaces/IFeeAccumulator.sol";
import "../interfaces/IEventEmitter.sol";
import "../libraries/ReserveLib.sol";
import "../libraries/FeeLib.sol";
import "../libraries/BitFlag.sol";
import "../libraries/TransferHelper.sol";
import "../libraries/SidioraMath.sol";
import "../interfaces/ISidioraFactory.sol";
import "../interfaces/IPoolRegistry.sol";
import "../base/ERC1967Utils.sol";

/// @title IOpticalMinimal
/// @dev Minimal interface for optical hooks used by pool
interface IOpticalMinimal {
    function beforeSwap(address pool, address sender, bool isBuy, uint256 amountIn)
        external returns (bool proceed, int256 amountDelta);
    function afterSwap(address pool, address sender, bool isBuy, uint256 amountIn, uint256 amountOut)
        external returns (bytes4);
    function getFlags() external view returns (uint8);
}

/// @title SidioraPool
/// @notice Core AMM engine. Constant product with virtual reserves and dynamic fees.
/// @dev Beacon proxy instances. Deliberately focused on AMM math + state transitions only.
///
///      FEE MODEL: Fees are always paid in the INPUT token.
///        BUY  (USDL → Token): fee in USDL → sent to FeeAccumulator for strategy distribution
///        SELL (Token → USDL): fee in Token → stays in pool, deepens token-side liquidity
///
///      VIRTUAL RESERVE FLOOR: virtualUsdlReserve (10,000 USDL) is pricing-only.
///        realUsdlBalance can never go below 0. The pool cannot pay out virtual USDL.
///        On sells, amountOut is bounded by realUsdlBalance (defense-in-depth).
contract SidioraPool is ISidioraPool, Initializable, ReentrancyGuard, Pausable {
    error VirtualFloorBreached();
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidBalance();
    error InvalidHookResponse();
    event GuardianTransferStarted(address indexed guardian, address indexed pendingGuardian);
    event GuardianTransferred(address indexed previousGuardian, address indexed guardian);
    event InputAdjustment(uint256 paidInput, uint256 pricedInput);
    event FactoryMigrated(address indexed factory);


    address public override tokenAddress;
    address public usdlAddress;
    address public override opticalAddress;
    address public feeAccumulator;
    address public eventEmitter;
    address public protocolConfig;
    address public guardian;

    uint256 public virtualUsdlReserve;
    uint256 public realUsdlBalance;
    uint256 public tokenReserve;
    uint256 public override creationTimestamp;
    uint256 public override cumulativeVolume;

    uint256[8] public priceSnapshots;
    uint256 public snapshotIndex;
    uint256 public snapshotCount;

    uint256 public accumulatedUsdlFees;
    uint256 public accumulatedTokenFees;

    // Appended upgrade storage: existing fields retain their slots.
    address public factory;
    address public pendingGuardian;
    uint256 public lastSnapshotTimestamp;
    uint256 public cumulativeBuyUsdlVolume;
    uint256 public cumulativeSellUsdlVolume;
    uint256 public constant SNAPSHOT_INTERVAL = 60;
    uint256 public constant SNAPSHOT_MIN_VOLUME_BPS = 1;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _tokenAddress,
        address _usdlAddress,
        address _opticalAddress,
        address _feeAccumulator,
        address _eventEmitter,
        address _protocolConfig,
        address _guardian,
        uint256 _virtualUsdlReserve,
        uint256 _tokenReserve
    ) external override initializer {
        if (_tokenAddress == address(0)) revert ZeroAddress();
        if (_usdlAddress == address(0)) revert ZeroAddress();

        if (_tokenAddress.code.length == 0 || _usdlAddress.code.length == 0 ||
            _feeAccumulator.code.length == 0 || _protocolConfig.code.length == 0 || _guardian == address(0) ||
            _virtualUsdlReserve == 0 || _tokenReserve == 0 ||
            _virtualUsdlReserve > type(uint128).max || _tokenReserve > type(uint128).max ||
            (_opticalAddress != address(0) && _opticalAddress.code.length == 0)) revert InvalidConfiguration();
        factory = msg.sender;
        tokenAddress = _tokenAddress;
        usdlAddress = _usdlAddress;
        opticalAddress = _opticalAddress;
        feeAccumulator = _feeAccumulator;
        eventEmitter = _eventEmitter;
        protocolConfig = _protocolConfig;
        guardian = _guardian;

        virtualUsdlReserve = _virtualUsdlReserve;
        tokenReserve = _tokenReserve;
        realUsdlBalance = 0;
        creationTimestamp = block.timestamp;

        _initReentrancyGuard();
    }

    /// @notice One-time router provenance migration for pools initialized before factory storage existed.
    /// @dev Only the protocol-config administrator can authorize migration. The candidate must
    ///      match configured dependencies and the registry must bind this pool to this token.
    function migrateFactory(address factory_) external {
        (bool ok, bytes memory data) = protocolConfig.staticcall(abi.encodeWithSignature(
            "hasRole(bytes32,address)", bytes32(0), msg.sender));
        if (!ok || data.length != 32 || !abi.decode(data, (bool))) revert Unauthorized();
        if (factory != address(0) || factory_.code.length == 0) revert InvalidConfiguration();
        ISidioraFactory candidate = ISidioraFactory(factory_);
        if (candidate.protocolConfig() != protocolConfig || candidate.eventEmitter() != eventEmitter ||
            candidate.poolBeacon() != ERC1967Utils.getBeacon()) revert InvalidConfiguration();
        (ok, data) = factory_.staticcall(abi.encodeWithSignature("feeAccumulator()"));
        if (!ok || data.length != 32 || abi.decode(data, (address)) != feeAccumulator) revert InvalidConfiguration();
        (ok, data) = factory_.staticcall(abi.encodeWithSignature("usdlAddress()"));
        if (!ok || data.length != 32 || abi.decode(data, (address)) != usdlAddress) revert InvalidConfiguration();
        IPoolRegistry registry = IPoolRegistry(candidate.poolRegistry());
        if (!registry.isRegisteredPool(address(this)) || registry.getPoolByToken(tokenAddress) != address(this)) revert InvalidConfiguration();
        factory = factory_;
        emit FactoryMigrated(factory_);
    }

    // ============ SWAP ============

    function swap(
        uint256 amountIn,
        uint256 minAmountOut,
        bool isBuy,
        address recipient,
        uint256 deadline
    ) external override nonReentrant whenNotPaused returns (uint256 amountOut) {
        return _swap(amountIn, minAmountOut, isBuy, msg.sender, recipient, deadline);
    }

    /// @notice Authenticated routers preserve trader identity independently of the output recipient.
    function swapFor(uint256 amountIn, uint256 minAmountOut, bool isBuy, address trader, address recipient, uint256 deadline)
        external override nonReentrant whenNotPaused returns (uint256)
    {
        (bool ok, bytes memory data) = factory.staticcall(abi.encodeWithSignature(
            "hasRole(bytes32,address)", keccak256("ROUTER_ROLE"), msg.sender));
        if (!ok || data.length != 32 || !abi.decode(data, (bool))) revert Unauthorized();
        if (trader == address(0)) revert ZeroAddress();
        return _swap(amountIn, minAmountOut, isBuy, trader, recipient, deadline);
    }

    function _swap(uint256 amountIn, uint256 minAmountOut, bool isBuy, address trader, address recipient, uint256 deadline)
        internal returns (uint256 amountOut)
    {
        if (block.timestamp > deadline) revert DeadlineExpired();
        if (amountIn == 0) revert InsufficientInput();
        if (recipient == address(0)) revert ZeroAddress();

        uint256 paidInput = amountIn;
        uint256 accounted = isBuy ? realUsdlBalance : tokenReserve;
        uint256 balance = _getBalance(isBuy ? usdlAddress : tokenAddress);
        if (balance < accounted || balance - accounted < paidInput) revert InsufficientInput();
        uint8 flags = opticalAddress == address(0) ? 0 : IOpticalMinimal(opticalAddress).getFlags();

        // Calculate dynamic fee
        uint256 feeBps = _calculateFee();

        // Optical: beforeSwap
        if (opticalAddress != address(0)) {
            if (BitFlag.hasFlag(flags, BitFlag.BEFORE_SWAP)) {
                (bool proceed, int256 amountDelta) =
                    IOpticalMinimal(opticalAddress).beforeSwap(address(this), trader, isBuy, amountIn);
                if (!proceed) revert InsufficientInput();
                if (amountDelta > 0) {
                    revert InsufficientInput(); // Hook cannot invent prepaid input.
                } else if (amountDelta < 0) {
                    uint256 reduction = SidioraMath.abs(amountDelta);
                    if (reduction >= amountIn) revert InsufficientInput();
                    amountIn -= reduction;
                }
            }
        }

        // Calculate fee in the INPUT token
        uint256 feeAmount = SidioraMath.mulDiv(amountIn, feeBps, 10000);
        uint256 amountInAfterFee = amountIn - feeAmount;

        uint256 effectiveUsdl = virtualUsdlReserve + realUsdlBalance;

        if (isBuy) {
            // ── BUY: USDL → Token ──
            // Fee is in USDL. Only amountInAfterFee enters reserves.
            // feeAmount USDL is sent to FeeAccumulator for strategy distribution.
            amountOut = ReserveLib.getAmountOut(effectiveUsdl, tokenReserve, amountInAfterFee);
            if (amountOut > tokenReserve) revert InsufficientLiquidity();

            realUsdlBalance += paidInput - feeAmount;
            tokenReserve -= amountOut;

            // Transfer tokens to buyer
            TransferHelper.safeTransfer(tokenAddress, recipient, amountOut);

            // Send USDL fee to FeeAccumulator
            if (feeAmount > 0 && feeAccumulator != address(0)) {
                accumulatedUsdlFees += feeAmount;
                TransferHelper.safeTransfer(usdlAddress, feeAccumulator, feeAmount);
                IFeeAccumulator(feeAccumulator).recordFee(address(this), feeAmount);
            }
        } else {
            // ── SELL: Token → USDL ──
            // Fee is in Token. Fee tokens stay in pool (deepen token-side liquidity).
            // Only amountInAfterFee enters AMM math for pricing.
            amountOut = ReserveLib.getAmountOut(tokenReserve, effectiveUsdl, amountInAfterFee);

            // VIRTUAL FLOOR: Cannot pay out virtual USDL. Only real USDL is withdrawable.
            if (amountOut > realUsdlBalance) revert VirtualFloorBreached();

            // Full amountIn added to tokenReserve (fee tokens deepen liquidity)
            tokenReserve += paidInput;
            realUsdlBalance -= amountOut;

            // Transfer USDL to seller
            TransferHelper.safeTransfer(usdlAddress, recipient, amountOut);

            // Track token fees (they stay in pool, no external transfer)
            if (feeAmount > 0) {
                accumulatedTokenFees += feeAmount;
            }
        }

        if (amountOut == 0) revert InsufficientInput();
        if (amountOut < minAmountOut) revert SlippageExceeded();

        // Update volume and price snapshots
        uint256 usdlVolume = isBuy ? paidInput : amountOut;
        cumulativeVolume += usdlVolume;
        if (isBuy) cumulativeBuyUsdlVolume += usdlVolume;
        else cumulativeSellUsdlVolume += usdlVolume;
        uint256 currentPrice = _currentPrice();
        _updatePriceSnapshot(currentPrice, usdlVolume);
        if (paidInput != amountIn) emit InputAdjustment(paidInput, amountIn);

        // Optical: afterSwap
        if (opticalAddress != address(0)) {
            if (BitFlag.hasFlag(flags, BitFlag.AFTER_SWAP)) {
                if (IOpticalMinimal(opticalAddress).afterSwap(address(this), trader, isBuy, amountIn, amountOut)
                    != IOpticalMinimal.afterSwap.selector) revert InvalidHookResponse();
            }
        }

        // External hooks and transfer callbacks must not remove booked backing.
        if (_getBalance(usdlAddress) < realUsdlBalance || _getBalance(tokenAddress) < tokenReserve) revert InvalidBalance();

        // Emit event
        if (eventEmitter != address(0)) {
            bytes32 poolId = bytes32(uint256(uint160(address(this))));
            IEventEmitter(eventEmitter).emitSwap(poolId, trader, isBuy, paidInput, amountOut, feeAmount, currentPrice);
        }
    }

    // ============ SYNC RESERVES ============

    function syncReserves() external override nonReentrant returns (uint256 usdlBal, uint256 tokenBal) {
        usdlBal = _getBalance(usdlAddress);
        tokenBal = _getBalance(tokenAddress);

        realUsdlBalance = usdlBal;
        tokenReserve = tokenBal;

        if (eventEmitter != address(0)) {
            bytes32 poolId = bytes32(uint256(uint160(address(this))));
            IEventEmitter(eventEmitter).emitPoolStateUpdated(
                poolId, virtualUsdlReserve, realUsdlBalance, tokenReserve, _currentPrice()
            );
        }
    }

    // ============ PAUSE ============

    function pause() external {
        if (msg.sender != guardian) revert Unauthorized();
        _pause();
    }

    function unpause() external {
        if (msg.sender != guardian) revert Unauthorized();
        _unpause();
    }

    /// @notice Guardian authority is independent of fee NFT ownership and transfers by consent.
    function transferGuardian(address nextGuardian) external {
        if (msg.sender != guardian) revert Unauthorized();
        if (nextGuardian == address(0)) revert ZeroAddress();
        pendingGuardian = nextGuardian;
        emit GuardianTransferStarted(guardian, nextGuardian);
    }

    function acceptGuardian() external {
        if (msg.sender != pendingGuardian) revert Unauthorized();
        address previous = guardian;
        guardian = msg.sender;
        pendingGuardian = address(0);
        emit GuardianTransferred(previous, msg.sender);
    }

    function paused() external view returns (bool) {
        return _paused();
    }

    // ============ VIEWS ============

    function getReserves() external view override returns (
        uint256 virtualUsdl,
        uint256 realUsdl,
        uint256 tokenRes
    ) {
        virtualUsdl = virtualUsdlReserve;
        realUsdl = realUsdlBalance;
        tokenRes = tokenReserve;
    }

    function getEffectiveReserves() external view override returns (
        uint256 effectiveUsdl,
        uint256 tokenRes
    ) {
        effectiveUsdl = virtualUsdlReserve + realUsdlBalance;
        tokenRes = tokenReserve;
    }

    function getPrice() external view override returns (uint256) {
        return _currentPrice();
    }

    function getPoolInfo() external view override returns (PoolInfo memory) {
        return PoolInfo({
            tokenAddress: tokenAddress,
            opticalAddress: opticalAddress,
            virtualUsdlReserve: virtualUsdlReserve,
            realUsdlBalance: realUsdlBalance,
            tokenReserve: tokenReserve,
            creationTimestamp: creationTimestamp,
            cumulativeVolume: cumulativeVolume
        });
    }

    function getPriceSnapshots() external view override returns (uint256[8] memory) {
        return _orderedSnapshots();
    }

    function _orderedSnapshots() internal view returns (uint256[8] memory) {
        uint256[8] memory ordered;
        uint256 start = snapshotCount == 8 ? snapshotIndex : 0;
        for (uint256 i; i < snapshotCount; ++i) ordered[i] = priceSnapshots[(start + i) % 8];
        return ordered;
    }

    // ============ INTERNAL ============

    function _calculateFee() internal view returns (uint256) {
        IProtocolConfig config = IProtocolConfig(protocolConfig);
        uint256 poolAge = block.timestamp - creationTimestamp;

        // Calculate volatility from snapshots
        uint256 volatility = FeeLib.calculateVolatility(_orderedSnapshots(), snapshotCount);

        // Concentration is explicitly disabled by ProtocolConfig until an authenticated holder metric exists.
        uint256 topHolderBps = 0;

        return FeeLib.calculateDynamicFee(
            config.baseFeeBps(),
            config.minFeeBps(),
            config.maxFeeBps(),
            config.feeDecayRate(),
            config.volatilityWeight(),
            config.concentrationWeight(),
            poolAge,
            volatility,
            topHolderBps
        );
    }

    function _currentPrice() internal view returns (uint256) {
        if (tokenReserve == 0) return 0;
        uint256 effectiveUsdl = virtualUsdlReserve + realUsdlBalance;
        return ReserveLib.getPrice(effectiveUsdl, tokenReserve);
    }

    function currentFeeBps() external view override returns (uint256) { return _calculateFee(); }

    function _updatePriceSnapshot(uint256 price, uint256 usdlVolume) internal {
        if (usdlVolume < SidioraMath.mulDiv(virtualUsdlReserve + realUsdlBalance, SNAPSHOT_MIN_VOLUME_BPS, 10000)) return;
        if (snapshotCount != 0 && block.timestamp < lastSnapshotTimestamp + SNAPSHOT_INTERVAL) return;
        lastSnapshotTimestamp = block.timestamp;
        priceSnapshots[snapshotIndex] = price;
        snapshotIndex = (snapshotIndex + 1) % 8;
        if (snapshotCount < 8) {
            snapshotCount++;
        }
    }

    function _getBalance(address token) internal view returns (uint256) {
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        if (!success || data.length != 32 || token.code.length == 0) revert InvalidBalance();
        return abi.decode(data, (uint256));
    }
}

contracts/data/EventEmitter.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/IEventEmitter.sol";
import "../interfaces/IPoolRegistry.sol";

/// @notice Minimal interface for the optional optical registry auth path.
interface IOpticalRegistryMinimal {
    function isApproved(address optical) external view returns (bool);
}

/// @notice Minimal interface for the optional Meta-AG router auth path.
///         Adapter authorization is keyed by `bytes32 adapterId` rather than
///         address; v2 keeps the lookup as `isAdapterActive` for parity with
///         the existing MetaAGRouter surface, expecting the router to have
///         been registered via `setAuthorizedEmitter` directly.
interface IMetaAGRouterMinimal {
    function isAdapterActive(bytes32 adapterId) external view returns (bool);
}

/// @title EventEmitter v2
/// @notice Optional protocol event mirror. Native source logs remain authoritative across
///         Sidiora Launchpad, Meta-AG/PECOR, opticals, oracle, treasury,
///         governance, and base-layer lifecycle (roles, upgrades, pause).
/// @dev    UUPS-upgradeable. Storage layout is **append-only** vs v1.
///         Typed authorization is selector scoped; generic logs include caller provenance.
///         v1 functions and events retain their ABI — same selectors,
///         same topic0 — for backward compatibility with existing call sites
///         in `core/SidioraFactory`, `core/SidioraPool`, `protocol/ProtocolConfig`.
///
///         v2 additions (per `contracts/data/EVENT-EMITTER-V2-PLAN.md`):
///           - Generic schemaless `EventLog{,1,2}` with indexed eventNameHash.
///           - ~30 typed fast-path emitters spanning every protocol domain.
///           - `EVENT_EMITTER_ROLE` separate from `DEFAULT_ADMIN_ROLE`.
///           - `VERSION()` accessor returning `"2.0.0"`.
///           - 5-path authorization mesh:
///               1) static `_authorizedEmitters` mapping
///               2) dynamic `IPoolRegistry.isRegisteredPool`        (Launchpad pools)
///               3) dynamic `IOpticalRegistry.isApproved`           (opticals)
///               4) `sidioraFactory == msg.sender`                  (factory itself)
///               5) `_registeredTokens[msg.sender]`                 (pool tokens)
///
///         Reference: GMX V2 EventEmitter pattern, Synthetix V3 EventLog schema.
contract EventEmitter is IEventEmitter, Initializable, UUPSUpgradeable, AccessControl {

    // ════════════════════════════════════════════════════════════════════════
    //                                Constants
    // ════════════════════════════════════════════════════════════════════════

    /// @notice v1 — retained for ABI compatibility. Not used as a gate in v2.
    bytes32 public constant EMITTER_ADMIN_ROLE = keccak256("EMITTER_ADMIN_ROLE");

    /// @notice v2 — distinct from DEFAULT_ADMIN_ROLE. Holds permission to
    ///         authorize emitters and wire registries. Does NOT grant
    ///         upgrade authority (DEFAULT_ADMIN_ROLE retains that).
    bytes32 public constant override EVENT_EMITTER_ROLE = keccak256("EVENT_EMITTER_ROLE");

    /// @notice v2 implementation semantic version.
    string private constant _VERSION = "2.0.0";

    // ════════════════════════════════════════════════════════════════════════
    //                                Storage
    //
    // Layout is APPEND-ONLY relative to v1. Existing slots are immutable.
    // Slot 0 is consumed by AccessControl._roles via inheritance.
    // ════════════════════════════════════════════════════════════════════════

    // --- v1 (do not reorder, do not remove) -------------------------------
    /// @dev slot 1 (after AccessControl._roles at slot 0).
    mapping(address => bool) private _authorizedEmitters;
    /// @dev slot 2.
    address public poolRegistry;

    // --- v2 (appended) ----------------------------------------------------
    /// @dev slot 3.
    address public opticalRegistry;
    /// @dev slot 4.
    address public metaAGRouter;
    /// @dev slot 5.
    address public sidioraFactory;
    /// @dev slot 6 — local pool-token registration. SidioraFactory pushes
    ///      every `SidioraERC20` it deploys here so token Transfer mirrors
    ///      can pass the auth gate without per-token admin tx.
    mapping(address => bool) private _registeredTokens;
    /// @dev slot 7 — guards `reinitializeV2` against repeat invocation.
    bool private _v2Initialized;

    /// @dev Storage gap reserved for v3+ append-only growth (50 slots).
    mapping(bytes4 => mapping(address => bool)) private _typedEmitters;
    uint256[49] private __gap;

    // ════════════════════════════════════════════════════════════════════════
    //                              Initializers
    // ════════════════════════════════════════════════════════════════════════

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice v1 initializer — preserved for fresh-deploy compatibility.
    ///         New deploys SHOULD call this once, then `reinitializeV2`.
    function initialize(address _admin) external initializer {
        if (_admin == address(0)) revert Unauthorized();
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    /// @notice v1 → v2 storage migration. Idempotent.
    /// @param adminWithEmitterRole Address granted EVENT_EMITTER_ROLE.
    ///        Pass `address(0)` to skip role grant (admin can do it later
    ///        via `grantRole(EVENT_EMITTER_ROLE, ...)`).
    /// @dev Callable only by DEFAULT_ADMIN_ROLE. Safe to call once on the
    ///      existing deployed proxy `0x6679aF411d534de222C32ed0AF94C3BD67090672`
    ///      after the impl swap.
    function reinitializeV2(address adminWithEmitterRole)
        external
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (_v2Initialized) revert Unauthorized();
        _v2Initialized = true;

        // Set EVENT_EMITTER_ROLE admin to DEFAULT_ADMIN_ROLE (default behavior
        // already, but explicit for clarity and audit).
        _setRoleAdmin(EVENT_EMITTER_ROLE, DEFAULT_ADMIN_ROLE);

        if (adminWithEmitterRole != address(0)) {
            _grantRole(EVENT_EMITTER_ROLE, adminWithEmitterRole);
        }
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}

    // ════════════════════════════════════════════════════════════════════════
    //                          Authorization mesh
    // ════════════════════════════════════════════════════════════════════════

    modifier onlyAuthorized() {
        if (!_isAuthorized(msg.sender)) revert Unauthorized();
        _;
    }

    /// @notice Public auth-check for off-chain probes / dependent contracts.
    function isAuthorizedEmitter(address emitter)
        external
        view
        override
        returns (bool)
    {
        return _isAuthorized(emitter);
    }

    function isRegisteredToken(address token)
        external
        view
        override
        returns (bool)
    {
        return _registeredTokens[token];
    }

    function _isAuthorized(address sender) internal view returns (bool) {
        // 1. Static whitelist (the canonical fast path).
        if (_authorizedEmitters[sender]) return true;
        if (sender == poolRegistry && sender != address(0)) return true;

        // 2. Launchpad pool dynamic auth (v1 path, retained).
        address pr = poolRegistry;
        if (pr != address(0)) {
            // Defensive try/catch — never trust a misconfigured registry to
            // brick the entire emitter surface.
            try IPoolRegistry(pr).isRegisteredPool(sender) returns (bool ok) {
                if (ok) return true;
            } catch {
                // fall through
            }
        }

        // 3. Optical registry dynamic auth (v2).
        address or_ = opticalRegistry;
        if (or_ != address(0)) {
            try IOpticalRegistryMinimal(or_).isApproved(sender) returns (bool ok) {
                if (ok) return true;
            } catch {
                // fall through
            }
        }

        // 4. Factory itself can emit (v2).
        if (sender == sidioraFactory && sender != address(0)) return true;

        // 5. Pool-token registration (v2 — pool tokens emit Transfer mirrors).
        if (_registeredTokens[sender]) return true;

        return false;
    }

    /// @notice Typed permissions are independent of the generic log whitelist.
    /// @dev Assign selectors only to their canonical source contract. Optical
    /// approval never grants authority over oracle, treasury or governance logs.
    function setTypedEmitter(address emitter, bytes4 selector, bool allowed)
        external override onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (emitter == address(0)) revert Unauthorized();
        _typedEmitters[selector][emitter] = allowed;
        emit TypedEmitterPermission(emitter, selector, allowed);
    }

    function isTypedEmitter(address emitter, bytes4 selector) external view override returns (bool) {
        return _typedEmitters[selector][emitter];
    }

    function _requireTyped() private view {
        if (!_typedEmitters[msg.sig][msg.sender]) revert Unauthorized();
    }

    function _requirePool(bytes32 id) private view {
        if (_typedEmitters[msg.sig][msg.sender]) return;
        if (poolRegistry == address(0)) revert Unauthorized();
        try IPoolRegistry(poolRegistry).isRegisteredPool(msg.sender) returns (bool ok) {
            if (!ok) revert Unauthorized();
        } catch { revert Unauthorized(); }
        if (msg.sender.code.length == 0 || bytes32(uint256(uint160(msg.sender))) != id) revert Unauthorized();
    }

    function _requireFactory() private view {
        if (_typedEmitters[msg.sig][msg.sender]) return;
        if (msg.sender != sidioraFactory || msg.sender == address(0)) revert Unauthorized();
    }

    // ════════════════════════════════════════════════════════════════════════
    //                         Admin / wiring surface
    // ════════════════════════════════════════════════════════════════════════

    /// @notice v1 — wire the Launchpad pool registry. Retained.
    function setPoolRegistry(address _poolRegistry)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        poolRegistry = _poolRegistry;
    }

    /// @notice v1 — preserved for compatibility. v2 prefers EVENT_EMITTER_ROLE
    ///         (see `setAuthorizedEmitterByRole` below) but DEFAULT_ADMIN_ROLE
    ///         remains a valid caller.
    function setAuthorizedEmitter(address emitter, bool authorized)
        external
        override
    {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
            && !hasRole(EVENT_EMITTER_ROLE, msg.sender)) {
            revert MissingRole(msg.sender, EVENT_EMITTER_ROLE);
        }
        if (emitter == address(0)) revert Unauthorized();
        _authorizedEmitters[emitter] = authorized;
    }

    function setOpticalRegistry(address registry)
        external
        override
    {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
            && !hasRole(EVENT_EMITTER_ROLE, msg.sender)) {
            revert MissingRole(msg.sender, EVENT_EMITTER_ROLE);
        }
        opticalRegistry = registry;
    }

    function setMetaAGRouter(address router)
        external
        override
    {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
            && !hasRole(EVENT_EMITTER_ROLE, msg.sender)) {
            revert MissingRole(msg.sender, EVENT_EMITTER_ROLE);
        }
        metaAGRouter = router;
    }

    function setSidioraFactory(address factory)
        external
        override
    {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
            && !hasRole(EVENT_EMITTER_ROLE, msg.sender)) {
            revert MissingRole(msg.sender, EVENT_EMITTER_ROLE);
        }
        sidioraFactory = factory;
    }

    /// @notice Compatibility shim — the interface declares `setTokenRegistry`
    ///         to allow a future external token registry. v2 uses the local
    ///         `_registeredTokens` mapping, so this currently no-ops the
    ///         external pointer; future versions may delegate.
    function setTokenRegistry(address /*registry*/ )
        external
        override
    {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
            && !hasRole(EVENT_EMITTER_ROLE, msg.sender)) {
            revert MissingRole(msg.sender, EVENT_EMITTER_ROLE);
        }
        // Reserved for future delegation; v2 uses the in-contract mapping.
    }

    /// @notice Register a pool-token deployed by the SidioraFactory so it
    ///         can mirror Transfer / Approval through this emitter.
    /// @dev Callable by the wired factory itself (auto-registration on
    ///      market creation) or by EVENT_EMITTER_ROLE / DEFAULT_ADMIN_ROLE.
    function registerToken(address token, address /*pool*/ )
        external
        override
    {
        if (token == address(0)) revert Unauthorized();
        bool authorized =
            (sidioraFactory != address(0) && msg.sender == sidioraFactory)
            || hasRole(EVENT_EMITTER_ROLE, msg.sender)
            || hasRole(DEFAULT_ADMIN_ROLE, msg.sender);
        if (!authorized) revert Unauthorized();
        _registeredTokens[token] = true;
    }

    function deregisterToken(address token)
        external
        override
    {
        if (!hasRole(DEFAULT_ADMIN_ROLE, msg.sender)
            && !hasRole(EVENT_EMITTER_ROLE, msg.sender)) {
            revert MissingRole(msg.sender, EVENT_EMITTER_ROLE);
        }
        _registeredTokens[token] = false;
    }

    // ════════════════════════════════════════════════════════════════════════
    //                            Version accessor
    // ════════════════════════════════════════════════════════════════════════

    function VERSION() external pure override returns (string memory) {
        return _VERSION;
    }

    // ════════════════════════════════════════════════════════════════════════
    //                          v1 emit functions
    //
    //   Preserved verbatim for backward compatibility. SidioraFactory,
    //   SidioraPool, ProtocolConfig and downstream test mocks rely on
    //   these signatures. Do NOT change selectors, parameter order, or
    //   topic0 of the emitted events.
    // ════════════════════════════════════════════════════════════════════════

    function emitMarketCreated(
        bytes32 poolId,
        address token,
        address creator,
        address pool,
        address optical
    ) external override onlyAuthorized {
        _requireFactory();
        emit MarketCreated(poolId, token, creator, pool, optical, block.timestamp, block.number);
    }

    function emitSwap(
        bytes32 poolId,
        address sender,
        bool isBuy,
        uint256 amountIn,
        uint256 amountOut,
        uint256 fee,
        uint256 price
    ) external override onlyAuthorized {
        _requirePool(poolId);
        emit Swap(poolId, sender, isBuy, amountIn, amountOut, fee, price, block.timestamp, block.number);
    }

    function emitFeeRecorded(
        bytes32 poolId,
        uint256 feeAmount,
        uint256 protocolCut,
        uint256 poolCut
    ) external override onlyAuthorized {
        _requireTyped();
        emit FeeRecorded(poolId, feeAmount, protocolCut, poolCut, block.timestamp, block.number);
    }

    function emitFeeDistributed(
        bytes32 poolId,
        uint256 nftId,
        uint8 strategy,
        uint256 amount,
        address recipient
    ) external override onlyAuthorized {
        _requireTyped();
        emit FeeDistributed(poolId, nftId, strategy, amount, recipient, block.timestamp, block.number);
    }

    function emitFeeStrategyChanged(
        bytes32 poolId,
        uint256 nftId,
        uint8 oldStrategy,
        uint8 newStrategy
    ) external override onlyAuthorized {
        _requireTyped();
        emit FeeStrategyChanged(poolId, nftId, oldStrategy, newStrategy, block.timestamp, block.number);
    }

    function emitPoolStateUpdated(
        bytes32 poolId,
        uint256 virtualReserve,
        uint256 realReserve,
        uint256 tokenReserve,
        uint256 price
    ) external override onlyAuthorized {
        _requirePool(poolId);
        emit PoolStateUpdated(poolId, virtualReserve, realReserve, tokenReserve, price, block.timestamp, block.number);
    }

    function emitOpticalExecuted(
        bytes32 poolId,
        address optical,
        string calldata hookName,
        bytes calldata data
    ) external override onlyAuthorized {
        _requirePool(poolId);
        if (!_typedEmitters[msg.sig][msg.sender] && IPoolRegistry(poolRegistry).getPoolMetadata(msg.sender).optical != optical) revert Unauthorized();
        emit OpticalExecuted(poolId, optical, hookName, data, block.timestamp, block.number);
    }

    function emitConfigUpdated(
        bytes32 key,
        uint256 oldValue,
        uint256 newValue
    ) external override onlyAuthorized {
        _requireTyped();
        emit ConfigUpdated(key, oldValue, newValue, block.timestamp, block.number);
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Generic schemaless emit
    // ════════════════════════════════════════════════════════════════════════

    function emitEventLog(
        string calldata eventName,
        EventData calldata data
    ) external override onlyAuthorized {
        emit EventLog(
            msg.sender,
            keccak256(bytes(eventName)),
            eventName,
            data,
            block.timestamp,
            block.number
        );
    }

    function emitEventLog1(
        string calldata eventName,
        bytes32 topic1,
        EventData calldata data
    ) external override onlyAuthorized {
        emit EventLog1(
            msg.sender,
            keccak256(bytes(eventName)),
            topic1,
            eventName,
            data,
            block.timestamp,
            block.number
        );
    }

    function emitEventLog2(
        string calldata eventName,
        bytes32 topic1,
        bytes32 topic2,
        EventData calldata data
    ) external override onlyAuthorized {
        emit EventLog2(
            msg.sender,
            keccak256(bytes(eventName)),
            topic1,
            topic2,
            eventName,
            data,
            block.timestamp,
            block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Typed fast-paths: PECOR
    // ════════════════════════════════════════════════════════════════════════

    function emitPecorSwap(
        address user,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 priceIn,
        uint256 priceOut,
        uint256 volumeUSD,
        uint256 feeBps,
        uint256 feeAmount,
        uint256 impactBps,
        uint8 swapKind
    ) external override onlyAuthorized {
        _requireTyped();
        emit PecorSwap(
            user, tokenIn, tokenOut,
            amountIn, amountOut, priceIn, priceOut,
            volumeUSD, feeBps, feeAmount, impactBps, swapKind,
            block.timestamp, block.number
        );
    }

    function emitPecorOrderCreated(
        uint256 orderId,
        address user,
        uint8 orderKind,
        uint8 orderType,
        address tokenIn,
        address tokenOut,
        uint256 amount,
        uint256 targetPrice,
        uint256 stopPrice,
        uint256 limitPrice
    ) external override onlyAuthorized {
        _requireTyped();
        emit PecorOrderCreated(
            orderId, user, orderKind, orderType,
            tokenIn, tokenOut, amount,
            targetPrice, stopPrice, limitPrice,
            block.timestamp, block.number
        );
    }

    function emitPecorOrderLifecycle(
        uint256 orderId,
        address user,
        uint8 orderKind,
        uint8 phase,
        uint256 price,
        bytes calldata payload
    ) external override onlyAuthorized {
        _requireTyped();
        emit PecorOrderLifecycle(
            orderId, user, orderKind, phase, price, payload,
            block.timestamp, block.number
        );
    }

    function emitBestRouteSwap(
        address user,
        address tokenIn,
        address tokenOut,
        bytes32 routeId,
        uint256 amountIn,
        uint256 amountOut,
        address[] calldata hops,
        uint256 protocolFeeBps
    ) external override onlyAuthorized {
        _requireTyped();
        emit BestRouteSwap(
            user, tokenIn, tokenOut, routeId,
            amountIn, amountOut, hops, protocolFeeBps,
            block.timestamp, block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Typed fast-paths: Oracle
    // ════════════════════════════════════════════════════════════════════════

    function emitPriceUpdated(
        address token,
        uint256 roundId,
        address relayer,
        uint256 price,
        uint256 confidence,
        bytes32 sourceId
    ) external override onlyAuthorized {
        _requireTyped();
        emit PriceUpdated(
            token, roundId, relayer, price, confidence, sourceId,
            block.timestamp, block.number
        );
    }

    function emitCircuitBreaker(
        address token,
        bytes32 sourceId,
        uint256 reportedPrice,
        uint256 referencePrice,
        uint256 deviationBps
    ) external override onlyAuthorized {
        _requireTyped();
        emit CircuitBreakerTriggered(
            token, sourceId, reportedPrice, referencePrice, deviationBps,
            block.timestamp, block.number
        );
    }

    function emitOracleAdapterLifecycle(
        bytes32 sourceId,
        address adapter,
        uint8 phase,
        uint256 priority
    ) external override onlyAuthorized {
        _requireTyped();
        emit OracleAdapterLifecycle(
            sourceId, adapter, phase, priority,
            block.timestamp, block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Typed fast-paths: Vault
    // ════════════════════════════════════════════════════════════════════════

    function emitVaultFlow(
        uint8 flowType,
        address token,
        address party,
        uint256 amount,
        uint256 newReserve
    ) external override onlyAuthorized {
        _requireTyped();
        emit VaultFlow(
            flowType, token, party, amount, newReserve,
            block.timestamp, block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Typed fast-paths: Governance
    // ════════════════════════════════════════════════════════════════════════

    function emitGovernance(
        uint8 action,
        bytes32 id,
        address actor,
        bytes calldata payload
    ) external override onlyAuthorized {
        _requireTyped();
        emit Governance(action, id, actor, payload, block.timestamp, block.number);
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Typed fast-paths: Treasury
    // ════════════════════════════════════════════════════════════════════════

    function emitTreasuryFlow(
        uint8 direction,
        address token,
        address party,
        uint256 amount
    ) external override onlyAuthorized {
        _requireTyped();
        emit TreasuryFlow(
            direction, token, party, amount,
            block.timestamp, block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                       v2 — Typed fast-paths: Optical
    // ════════════════════════════════════════════════════════════════════════

    function emitOpticalLifecycle(
        uint8 action,
        address optical,
        address pool,
        bytes32 name,
        bytes calldata payload
    ) external override onlyAuthorized {
        if (msg.sender != optical) _requireTyped();
        emit OpticalLifecycle(
            action, optical, pool, name, payload,
            block.timestamp, block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                  v2 — Typed fast-paths: Token / NFT mirrors
    // ════════════════════════════════════════════════════════════════════════

    function emitTokenTransfer(
        address token,
        address from,
        address to,
        uint256 value
    ) external override onlyAuthorized {
        if (msg.sender != token) revert Unauthorized();
        emit TokenTransfer(token, from, to, value, block.timestamp, block.number);
    }

    function emitNftTransfer(
        address nft,
        address from,
        address to,
        uint256 tokenId
    ) external override onlyAuthorized {
        if (msg.sender != nft) revert Unauthorized();
        emit NftTransfer(nft, from, to, tokenId, block.timestamp, block.number);
    }

    function emitAssetApproval(
        address asset,
        address owner,
        address spender,
        uint256 valueOrTokenId,
        bool isNft
    ) external override onlyAuthorized {
        if (msg.sender != asset) revert Unauthorized();
        emit AssetApproval(
            asset, owner, spender, valueOrTokenId, isNft,
            block.timestamp, block.number
        );
    }

    // ════════════════════════════════════════════════════════════════════════
    //                v2 — Typed fast-paths: Access-control & lifecycle
    // ════════════════════════════════════════════════════════════════════════

    function emitRoleChange(
        uint8 action,
        bytes32 role,
        address account,
        address sender,
        bytes32 previousAdminRole
    ) external override onlyAuthorized {
        _requireTyped();
        emit RoleChange(
            action, role, account, sender, previousAdminRole,
            block.timestamp, block.number
        );
    }

    function emitUpgraded(
        address proxy,
        address newImplementation,
        uint8 kind
    ) external override onlyAuthorized {
        if (msg.sender != proxy) revert Unauthorized();
        emit ContractUpgraded(
            proxy, newImplementation, kind,
            block.timestamp, block.number
        );
    }

    function emitPauseToggle(
        address pausedContract,
        bool paused
    ) external override onlyAuthorized {
        if (msg.sender != pausedContract) revert Unauthorized();
        emit PauseToggle(pausedContract, paused, block.timestamp, block.number);
    }

    // ════════════════════════════════════════════════════════════════════════
    //                v2 — Typed fast-paths: Launchpad mirrors
    // ════════════════════════════════════════════════════════════════════════

    function emitFeeFlow(
        uint8 kind,
        address pool,
        address party,
        uint256 amount,
        uint256 protocolCut,
        uint256 poolCut,
        uint256 epoch
    ) external override onlyAuthorized {
        _requireTyped();
        emit FeeFlow(
            kind, pool, party, amount, protocolCut, poolCut, epoch,
            block.timestamp, block.number
        );
    }

    function emitRouterTrade(
        uint8 kind,
        address pool,
        address sender,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 intermediateUsdl
    ) external override onlyAuthorized {
        _requireTyped();
        emit RouterTrade(
            kind, pool, sender, tokenIn, tokenOut,
            amountIn, amountOut, intermediateUsdl,
            block.timestamp, block.number
        );
    }

    function emitNftMint(
        uint256 tokenId,
        address creator,
        address pool,
        uint8 strategy
    ) external override onlyAuthorized {
        _requireTyped();
        emit NftMint(
            tokenId, creator, pool, strategy,
            block.timestamp, block.number
        );
    }

    function emitPoolRegistered(
        address pool,
        address token,
        address creator,
        address optical,
        uint256 nftId
    ) external override onlyAuthorized {
        if (!_typedEmitters[msg.sig][msg.sender] && (msg.sender != poolRegistry || msg.sender == address(0))) revert Unauthorized();
        if (!_typedEmitters[msg.sig][msg.sender]) {
            IPoolRegistry.PoolMetadata memory meta = IPoolRegistry(poolRegistry).getPoolMetadata(pool);
            if (meta.token != token || meta.creator != creator || meta.optical != optical || meta.nftId != nftId) revert Unauthorized();
        }
        emit PoolRegistered(
            pool, token, creator, optical, nftId,
            block.timestamp, block.number
        );
    }

    function emitTokenDeployed(
        address token,
        address pool,
        address creator,
        bytes32 salt,
        string calldata name,
        string calldata symbol,
        uint8 decimals,
        uint256 totalSupply
    ) external override onlyAuthorized {
        _requireFactory();
        emit TokenDeployed(
            token, pool, creator, salt, name, symbol, decimals, totalSupply,
            block.timestamp, block.number
        );
    }
}

contracts/data/FeeAccumulator.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../base/ReentrancyGuard.sol";
import "../interfaces/IFeeAccumulator.sol";
import "../interfaces/IProtocolConfig.sol";
import "../interfaces/IPoolRegistry.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/IEventEmitter.sol";
import "../libraries/TransferHelper.sol";
import "../libraries/BitFlag.sol";

/// @dev Minimal interface for optical hooks used by FeeAccumulator
interface ICheckpointToken {
    function getPastBalance(address account, uint256 blockNumber) external view returns (uint256);
    function getPastTotalSupply(uint256 blockNumber) external view returns (uint256);
}

interface IOpticalFee {
    function beforeFeeDistribution(address pool, uint256 feeAmount) external returns (uint256 adjustedFee);
    function afterFeeDistribution(address pool, uint256 feeAmount) external returns (bytes4);
    function getFlags() external view returns (uint8);
}

/// @title FeeAccumulator
/// @notice Tracks accumulated fees per pool and executes fee distribution strategies
/// @dev UUPS proxy. Inspired by Aerodrome's PoolFees separation.
contract FeeAccumulator is IFeeAccumulator, Initializable, UUPSUpgradeable, AccessControl, ReentrancyGuard {
    event MirrorFailed(bytes4 indexed selector);
    bytes32 public constant POOL_ROLE = keccak256("POOL_ROLE");
    bytes32 public constant FEES_ROUTER_ROLE = keccak256("FEES_ROUTER_ROLE");
    bytes32 public constant FACTORY_ROLE = keccak256("FACTORY_ROLE");
    bytes32 public constant OPTICAL_CLAIM_ROLE = keccak256("OPTICAL_CLAIM_ROLE");
    bytes32 public constant OPTICAL_GRANTER_ROLE = keccak256("OPTICAL_GRANTER_ROLE");

    /// @notice Authorize a pool to record fees. Called by Factory on market creation.
    function authorizePool(address pool) external onlyRole(FACTORY_ROLE) {
        _grantRole(POOL_ROLE, pool);
    }

    address public constant DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    address public protocolConfig;
    address public treasury;
    address public poolRegistry;
    address public eventEmitter;
    address public usdlAddress;

    mapping(address => uint256) private _accumulatedFees;
    uint256 private _protocolFeesPending;

    // Airdrop state
    mapping(address => uint256) private _airdropBalance;
    mapping(address => uint256) private _airdropEpoch;
    mapping(address => mapping(uint256 => uint256)) private _airdropEpochAmount;
    mapping(address => mapping(address => mapping(uint256 => bool))) private _airdropClaimed;

    // LP rewards state
    mapping(address => uint256) private _lpRewardsBalance;

    // Optical surplus state (held on behalf of opticals that divert fees)
    mapping(address => uint256) private _opticalSurplus;

    // Appended storage: never reorder legacy proxy fields above.
    uint256 public totalLiabilities;
    mapping(address => mapping(uint256 => uint256)) public airdropSnapshotBlock;
    mapping(address => mapping(uint256 => uint256)) public airdropEligibleSupply;
    mapping(address => mapping(uint256 => uint256)) public airdropEpochRemaining;
    mapping(address => mapping(uint256 => uint256)) public airdropClaimedSupply;

    bool public accountingInitialized;
    uint256 public accountingMigrationCursor;
    mapping(address => bool) private _accountingMigratedPool;
    mapping(address => uint256) public legacyAirdropUnallocated;
    mapping(address => mapping(uint256 => bytes32)) public legacyAirdropRoot;
    mapping(address => mapping(uint256 => uint256)) public legacyAirdropRemaining;
    event AccountingMigrated(uint256 liabilities);
    event LegacyAirdropAllocated(address indexed pool, uint256 indexed epoch, bytes32 root, uint256 budget);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _protocolConfig,
        address _treasury,
        address _poolRegistry,
        address _eventEmitter,
        address _usdlAddress,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        if (_usdlAddress == address(0)) revert ZeroAddress();
        if (_treasury == address(0)) revert ZeroAddress();

        protocolConfig = _protocolConfig;
        treasury = _treasury;
        poolRegistry = _poolRegistry;
        eventEmitter = _eventEmitter;
        usdlAddress = _usdlAddress;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _initReentrancyGuard();
        accountingInitialized = true;
    }

    /// @inheritdoc IFeeAccumulator
    function recordFee(address pool, uint256 feeAmount) external override onlyRole(POOL_ROLE) nonReentrant {
        if (!accountingInitialized) revert Unauthorized();
        _requirePool(pool);
        if (feeAmount == 0) revert ZeroAmount();
        _requireBacking(feeAmount);
        totalLiabilities += feeAmount;

        // Split fee into protocol and pool portions
        uint256 protocolFeeBps = IProtocolConfig(protocolConfig).protocolFeeBps();
        uint256 protocolCut = (feeAmount * protocolFeeBps) / 10000;
        uint256 poolCut = feeAmount - protocolCut;

        // Accumulate protocol fees
        _protocolFeesPending += protocolCut;

        // Call optical beforeFeeDistribution hook if applicable
        uint256 opticalDivert = 0;
        if (poolRegistry != address(0)) {
            IPoolRegistry.PoolMetadata memory meta = IPoolRegistry(poolRegistry).getPoolMetadata(pool);
            if (meta.optical != address(0)) {
                uint8 flags = IOpticalFee(meta.optical).getFlags();
                if (BitFlag.hasFlag(flags, BitFlag.BEFORE_FEE_DISTRIBUTION)) {
                    uint256 adjustedPoolCut = IOpticalFee(meta.optical).beforeFeeDistribution(pool, poolCut);
                    if (adjustedPoolCut > poolCut) revert InsufficientSurplus();
                    if (adjustedPoolCut < poolCut) {
                        opticalDivert = poolCut - adjustedPoolCut;
                        _opticalSurplus[pool] += opticalDivert;
                        poolCut = adjustedPoolCut;
                        emit OpticalSurplusRecorded(pool, opticalDivert);
        _mirrorFee(7, pool, address(0), opticalDivert, 0, 0, 0);
                    }
                }
            }
        }

        // Accumulate pool fees (after optical diversion)
        _accumulatedFees[pool] += poolCut;

        // Transfer protocol cut to treasury
        if (protocolCut > 0) {
            TransferHelper.safeApprove(usdlAddress, treasury, protocolCut);
            ITreasury(treasury).deposit(usdlAddress, protocolCut);
            _protocolFeesPending -= protocolCut;
            totalLiabilities -= protocolCut;
        }

        if (poolRegistry != address(0)) {
            address optical = IPoolRegistry(poolRegistry).getPoolMetadata(pool).optical;
            if (optical != address(0) && BitFlag.hasFlag(IOpticalFee(optical).getFlags(), BitFlag.AFTER_FEE_DISTRIBUTION)) {
                if (IOpticalFee(optical).afterFeeDistribution(pool, poolCut) != IOpticalFee.afterFeeDistribution.selector) revert Unauthorized();
            }
        }
        emit FeeRecorded(pool, feeAmount, protocolCut, poolCut);
        _mirrorFee(0, pool, address(0), feeAmount, protocolCut, poolCut, 0);
    }

    /// @inheritdoc IFeeAccumulator
    function claim(
        address pool,
        address recipient
    ) external override onlyRole(FEES_ROUTER_ROLE) nonReentrant returns (uint256 amount) {
        if (!accountingInitialized) revert Unauthorized();
        if (recipient == address(0)) revert ZeroAddress();
        amount = _accumulatedFees[pool];
        if (amount == 0) revert NoFeesAccumulated();

        _accumulatedFees[pool] = 0;
        totalLiabilities -= amount;
        TransferHelper.safeTransfer(usdlAddress, recipient, amount);

        emit FeesClaimed(pool, recipient, amount);
        _mirrorFee(1, pool, recipient, amount, 0, 0, 0);
    }

    /// @inheritdoc IFeeAccumulator
    function burn(
        address pool
    ) external override onlyRole(FEES_ROUTER_ROLE) nonReentrant returns (uint256 amount) {
        if (!accountingInitialized) revert Unauthorized();
        amount = _accumulatedFees[pool];
        if (amount == 0) revert NoFeesAccumulated();

        _accumulatedFees[pool] = 0;
        totalLiabilities -= amount;
        TransferHelper.safeTransfer(usdlAddress, DEAD_ADDRESS, amount);

        emit FeesBurned(pool, amount);
        _mirrorFee(2, pool, DEAD_ADDRESS, amount, 0, 0, 0);
    }

    /// @inheritdoc IFeeAccumulator
    function triggerAirdrop(
        address pool
    ) external override onlyRole(FEES_ROUTER_ROLE) nonReentrant returns (uint256 totalAmount) {
        if (!accountingInitialized) revert Unauthorized();
        totalAmount = _accumulatedFees[pool];
        if (totalAmount == 0) revert NoFeesAccumulated();

        _accumulatedFees[pool] = 0;

        IPoolRegistry.PoolMetadata memory meta = IPoolRegistry(poolRegistry).getPoolMetadata(pool);
        if (!supportsAirdrop(pool)) revert UnsupportedSnapshotToken();
        uint256 snapshot = block.number - 1;
        ICheckpointToken token = ICheckpointToken(meta.token);
        uint256 eligible = token.getPastTotalSupply(snapshot)
            - token.getPastBalance(pool, snapshot) - token.getPastBalance(DEAD_ADDRESS, snapshot);
        if (eligible == 0) revert ZeroAmount();
        // Increment epoch and store snapshot
        uint256 newEpoch = _airdropEpoch[pool] + 1;
        _airdropEpoch[pool] = newEpoch;
        _airdropEpochAmount[pool][newEpoch] = totalAmount;
        airdropSnapshotBlock[pool][newEpoch] = snapshot;
        airdropEligibleSupply[pool][newEpoch] = eligible;
        airdropEpochRemaining[pool][newEpoch] = totalAmount;
        _airdropBalance[pool] += totalAmount;

        emit AirdropTriggered(pool, totalAmount, newEpoch);
        _mirrorFee(3, pool, address(0), totalAmount, 0, 0, newEpoch);
    }

    /// @inheritdoc IFeeAccumulator
    function claimAirdrop(
        address pool,
        address holder
    ) external override nonReentrant returns (uint256 amount) {
        if (!accountingInitialized) revert Unauthorized();
        return _claimAirdrop(pool, holder, _airdropEpoch[pool]);
    }

    function claimAirdropEpoch(address pool, address holder, uint256 epoch)
        external override nonReentrant returns (uint256 amount)
    {
        if (!accountingInitialized) revert Unauthorized();
        return _claimAirdrop(pool, holder, epoch);
    }

    function _claimAirdrop(address pool, address holder, uint256 epoch) internal returns (uint256 amount) {
        if (epoch == 0 || epoch > _airdropEpoch[pool]) revert AirdropNotTriggered();
        if (holder == pool || holder == DEAD_ADDRESS || holder == address(0)) revert Unauthorized();
        if (_airdropClaimed[pool][holder][epoch]) revert AlreadyClaimed();
        uint256 supply = airdropEligibleSupply[pool][epoch];
        if (supply == 0) revert AirdropNotTriggered(); // Legacy live-balance epochs require explicit migration.
        address token = IPoolRegistry(poolRegistry).getPoolMetadata(pool).token;
        uint256 balance = ICheckpointToken(token).getPastBalance(holder, airdropSnapshotBlock[pool][epoch]);
        if (balance == 0) revert ZeroAmount();
        amount = _airdropEpochAmount[pool][epoch] * balance / supply;
        _airdropClaimed[pool][holder][epoch] = true;
        uint256 claimedSupply = airdropClaimedSupply[pool][epoch] + balance;
        airdropClaimedSupply[pool][epoch] = claimedSupply;
        // Allocate rounding residue to the final eligible claimant; no epoch funds are lost.
        if (claimedSupply == supply) amount = airdropEpochRemaining[pool][epoch];
        airdropEpochRemaining[pool][epoch] -= amount;
        _airdropBalance[pool] -= amount;
        totalLiabilities -= amount;
        TransferHelper.safeTransfer(usdlAddress, holder, amount);
        emit AirdropClaimed(pool, holder, amount, epoch);
        _mirrorFee(4, pool, holder, amount, 0, 0, epoch);
    }

    /// @inheritdoc IFeeAccumulator
    function sendLpRewards(
        address pool
    ) external override onlyRole(FEES_ROUTER_ROLE) nonReentrant returns (uint256 amount) {
        if (!accountingInitialized) revert Unauthorized();
        amount = _accumulatedFees[pool];
        if (amount == 0) revert NoFeesAccumulated();

        _accumulatedFees[pool] = 0;
        totalLiabilities -= amount;
        _lpRewardsBalance[pool] += amount; // Cumulative liquidity donations, not claimable rewards.
        TransferHelper.safeTransfer(usdlAddress, pool, amount);

        emit LpRewardsSent(pool, amount);
        _mirrorFee(5, pool, pool, amount, 0, 0, 0);
    }

    // --- Views ---

    /// @inheritdoc IFeeAccumulator
    function getAccumulatedFees(address pool) external view override returns (uint256) {
        return _accumulatedFees[pool];
    }

    /// @inheritdoc IFeeAccumulator
    function getProtocolFeesPending() external view override returns (uint256) {
        return _protocolFeesPending;
    }

    /// @inheritdoc IFeeAccumulator
    function getAirdropBalance(address pool) external view override returns (uint256) {
        return _airdropBalance[pool];
    }

    /// @inheritdoc IFeeAccumulator
    function getLpRewardsBalance(address pool) external view override returns (uint256) {
        return _lpRewardsBalance[pool];
    }

    /// @inheritdoc IFeeAccumulator
    /// @notice Existing immutable tokens without checkpoints cannot accept new snapshot distributions.
    function supportsAirdrop(address pool) public view override returns (bool) {
        if (block.number == 0) return false;
        // Capability may be checked during NFT mint before atomic registry registration.
        (bool ok, bytes memory data) = pool.staticcall(abi.encodeWithSignature("tokenAddress()"));
        if (!ok || data.length != 32) return false;
        address token = abi.decode(data, (address));
        if (token.code.length == 0) return false;
        (ok, data) = token.staticcall(abi.encodeWithSelector(ICheckpointToken.getPastTotalSupply.selector, block.number - 1));
        if (!ok || data.length != 32) return false;
        (ok, data) = token.staticcall(abi.encodeWithSelector(ICheckpointToken.getPastBalance.selector, pool, block.number - 1));
        return ok && data.length == 32;
    }

    function getAirdropEpoch(address pool) external view override returns (uint256) {
        return _airdropEpoch[pool];
    }

    /// @inheritdoc IFeeAccumulator
    function hasClaimedAirdrop(
        address pool,
        address holder,
        uint256 epoch
    ) external view override returns (bool) {
        return _airdropClaimed[pool][holder][epoch];
    }

    // --- Internal ---

    function _getTokenBalance(address token, address account) internal view returns (uint256) {
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", account)
        );
        if (!success || data.length < 32) return 0;
        return abi.decode(data, (uint256));
    }

    function _getTokenTotalSupply(address token) internal view returns (uint256) {
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("totalSupply()")
        );
        if (!success || data.length < 32) return 0;
        return abi.decode(data, (uint256));
    }

    /// @notice Authorize an optical contract to claim surplus. Callable by OPTICAL_GRANTER_ROLE (e.g. LaunchpadOpticalFactory).
    function authorizeOptical(address optical) external onlyRole(OPTICAL_GRANTER_ROLE) {
        _grantRole(OPTICAL_CLAIM_ROLE, optical);
    }

    // --- Optical Surplus ---

    /// @inheritdoc IFeeAccumulator
    function recordOpticalSurplus(address pool, uint256 amount) external override onlyRole(POOL_ROLE) nonReentrant {
        if (!accountingInitialized) revert Unauthorized();
        _requirePool(pool);
        if (amount == 0) return;
        _requireBacking(amount);
        totalLiabilities += amount;
        _opticalSurplus[pool] += amount;
        emit OpticalSurplusRecorded(pool, amount);
        _mirrorFee(7, pool, address(0), amount, 0, 0, 0);
    }

    /// @inheritdoc IFeeAccumulator
    function claimOpticalSurplus(
        address pool,
        uint256 amount,
        address recipient
    ) external override nonReentrant {
        if (!accountingInitialized) revert Unauthorized();
        if (IPoolRegistry(poolRegistry).getPoolMetadata(pool).optical != msg.sender || msg.sender.code.length == 0) revert Unauthorized();
        if (recipient == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (_opticalSurplus[pool] < amount) revert InsufficientSurplus();

        _opticalSurplus[pool] -= amount;
        totalLiabilities -= amount;
        TransferHelper.safeTransfer(usdlAddress, recipient, amount);

        emit OpticalSurplusClaimed(pool, recipient, amount);
        _mirrorFee(8, pool, recipient, amount, 0, 0, 0);
    }

    /// @inheritdoc IFeeAccumulator
    function getOpticalSurplus(address pool) external view override returns (uint256) {
        return _opticalSurplus[pool];
    }

    /// @notice Upgrade-only, bounded liability reconciliation. All value mutations stay blocked until complete.
    function migrateAccounting(uint256 maxPools) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (accountingInitialized || maxPools == 0) revert Unauthorized();
        uint256 count = IPoolRegistry(poolRegistry).getPoolCount();
        uint256 cursor = accountingMigrationCursor;
        uint256 n = maxPools > count - cursor ? count - cursor : maxPools;
        address[] memory pools = IPoolRegistry(poolRegistry).getAllPools(cursor, n);
        for (uint256 i; i < pools.length; ++i) {
            _reconcileLegacyPool(pools[i]);
        }
        accountingMigrationCursor = cursor + n;
        if (accountingMigrationCursor == count) {
            if (_getTokenBalance(usdlAddress, address(this)) < totalLiabilities) revert InsufficientSurplus();
            _protocolFeesPending = 0; // Legacy counter represented fees already deposited in Treasury.
            accountingInitialized = true;
            emit AccountingMigrated(totalLiabilities);
        }
    }

    /// @notice Include legacy liability keys discovered from events outside the registered-pool inventory.
    /// @dev The legacy recorder permitted arbitrary pool keys; published migration inventory must include them.
    function migrateAdditionalAccounting(address[] calldata pools) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (accountingInitialized) revert Unauthorized();
        for (uint256 i; i < pools.length; ++i) _reconcileLegacyPool(pools[i]);
    }

    function _reconcileLegacyPool(address pool) internal {
        if (_accountingMigratedPool[pool]) return;
        _accountingMigratedPool[pool] = true;
        totalLiabilities += _accumulatedFees[pool] + _airdropBalance[pool] + _opticalSurplus[pool];
        legacyAirdropUnallocated[pool] = _airdropBalance[pool];
    }

    /// @notice Assign existing legacy custody to an immutable, externally reconstructed entitlement root.
    /// @dev Root leaf is keccak256(abi.encode(pool, epoch, holder, amount)); historical claims must be excluded.
    ///      Administrator must publish the reconstruction and allocations before invoking this migration.
    function allocateLegacyAirdrop(address pool, uint256 epoch, bytes32 root, uint256 budget)
        external onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (!accountingInitialized || root == bytes32(0) || budget == 0 || epoch == 0 || epoch > _airdropEpoch[pool]
            || airdropEligibleSupply[pool][epoch] != 0 || legacyAirdropRoot[pool][epoch] != bytes32(0)
            || budget > legacyAirdropUnallocated[pool]) revert Unauthorized();
        legacyAirdropUnallocated[pool] -= budget;
        legacyAirdropRoot[pool][epoch] = root;
        legacyAirdropRemaining[pool][epoch] = budget;
        emit LegacyAirdropAllocated(pool, epoch, root, budget);
    }

    function claimLegacyAirdrop(address pool, uint256 epoch, address holder, uint256 amount, bytes32[] calldata proof)
        external nonReentrant
    {
        if (!accountingInitialized || amount == 0 || holder == address(0)) revert Unauthorized();
        if (_airdropClaimed[pool][holder][epoch]) revert AlreadyClaimed();
        bytes32 hash = keccak256(abi.encode(pool, epoch, holder, amount));
        for (uint256 i; i < proof.length; ++i) {
            bytes32 sibling = proof[i];
            hash = hash < sibling ? keccak256(abi.encodePacked(hash, sibling)) : keccak256(abi.encodePacked(sibling, hash));
        }
        if (hash != legacyAirdropRoot[pool][epoch] || amount > legacyAirdropRemaining[pool][epoch]) revert Unauthorized();
        _airdropClaimed[pool][holder][epoch] = true;
        legacyAirdropRemaining[pool][epoch] -= amount;
        _airdropBalance[pool] -= amount;
        totalLiabilities -= amount;
        TransferHelper.safeTransfer(usdlAddress, holder, amount);
        emit AirdropClaimed(pool, holder, amount, epoch);
        _mirrorFee(4, pool, holder, amount, 0, 0, epoch);
    }

    function _mirrorFee(uint8 kind, address pool, address party, uint256 amount, uint256 protocolCut, uint256 poolCut, uint256 epoch) internal {
        if (eventEmitter == address(0)) return;
        try IEventEmitter(eventEmitter).emitFeeFlow(kind, pool, party, amount, protocolCut, poolCut, epoch) {}
        catch { emit MirrorFailed(IEventEmitter.emitFeeFlow.selector); }
    }

    function _requirePool(address pool) internal view {
        if (msg.sender != pool || pool.code.length == 0 || !IPoolRegistry(poolRegistry).isRegisteredPool(pool)) revert Unauthorized();
    }

    function _requireBacking(uint256 amount) internal view {
        if (_getTokenBalance(usdlAddress, address(this)) < totalLiabilities + amount) revert InsufficientSurplus();
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/data/PoolRegistry.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/IPoolRegistry.sol";
import "../interfaces/IEventEmitter.sol";

/// @title PoolRegistry
/// @notice On-chain pool discovery and metadata storage
/// @dev UUPS proxy. Only FACTORY_ROLE can register pools.
contract PoolRegistry is IPoolRegistry, Initializable, UUPSUpgradeable, AccessControl {
    event MirrorFailed(bytes4 indexed selector);
    bytes32 public constant FACTORY_ROLE = keccak256("FACTORY_ROLE");

    mapping(address => address) private _tokenToPool;
    mapping(address => uint256) private _poolToNftId;
    mapping(address => address[]) private _creatorToPools;
    mapping(address => PoolMetadata) private _poolMetadata;
    mapping(address => bool) private _registeredPools;

    address[] private _allPools;

    address public eventEmitter;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address _eventEmitter, address _admin) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        eventEmitter = _eventEmitter;
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    /// @inheritdoc IPoolRegistry
    function register(
        address pool,
        address token,
        address creator,
        address optical,
        uint256 nftId
    ) external override onlyRole(FACTORY_ROLE) {
        if (pool == address(0) || token == address(0) || creator == address(0)) revert ZeroAddress();
        if (_tokenToPool[token] != address(0)) revert DuplicateToken();
        if (_registeredPools[pool]) revert DuplicatePool();

        _tokenToPool[token] = pool;
        _poolToNftId[pool] = nftId;
        _creatorToPools[creator].push(pool);
        _registeredPools[pool] = true;

        _poolMetadata[pool] = PoolMetadata({
            creator: creator,
            token: token,
            optical: optical,
            nftId: nftId,
            createdAt: block.timestamp,
            createdBlock: block.number
        });

        _allPools.push(pool);

        emit PoolRegistered(pool, token, creator, optical, nftId, block.timestamp);
        if (eventEmitter != address(0)) {
            try IEventEmitter(eventEmitter).emitPoolRegistered(pool, token, creator, optical, nftId) {}
            catch { emit MirrorFailed(IEventEmitter.emitPoolRegistered.selector); }
        }
    }

    /// @inheritdoc IPoolRegistry
    function getPoolByToken(address token) external view override returns (address) {
        return _tokenToPool[token];
    }

    /// @inheritdoc IPoolRegistry
    function getPoolsByCreator(address creator) external view override returns (address[] memory) {
        return _creatorToPools[creator];
    }

    /// @inheritdoc IPoolRegistry
    function getNftIdByPool(address pool) external view override returns (uint256) {
        return _poolToNftId[pool];
    }

    /// @inheritdoc IPoolRegistry
    function getPoolMetadata(address pool) external view override returns (PoolMetadata memory) {
        return _poolMetadata[pool];
    }

    /// @inheritdoc IPoolRegistry
    function getAllPools(uint256 offset, uint256 limit) external view override returns (address[] memory) {
        uint256 total = _allPools.length;
        if (offset >= total) {
            return new address[](0);
        }

        uint256 end = offset + (limit > total - offset ? total - offset : limit);

        uint256 resultLength = end - offset;
        address[] memory result = new address[](resultLength);
        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = _allPools[offset + i];
        }
        return result;
    }

    /// @inheritdoc IPoolRegistry
    function getPoolCount() external view override returns (uint256) {
        return _allPools.length;
    }

    /// @inheritdoc IPoolRegistry
    function isRegisteredPool(address pool) external view override returns (bool) {
        return _registeredPools[pool];
    }

    function getPoolCountByCreator(address creator) external view override returns (uint256) {
        return _creatorToPools[creator].length;
    }

    function getPoolsByCreatorPage(address creator, uint256 offset, uint256 limit)
        external view override returns (address[] memory result)
    {
        address[] storage pools = _creatorToPools[creator];
        if (offset >= pools.length) return new address[](0);
        uint256 count = limit > pools.length - offset ? pools.length - offset : limit;
        result = new address[](count);
        for (uint256 i; i < count; ++i) result[i] = pools[offset + i];
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/interfaces/IEventEmitter.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title IEventEmitter
/// @notice Interface for the central event hub contract
interface IEventEmitter {
    // --- Errors ---
    error Unauthorized();

    // --- Events ---
    event MarketCreated(
        bytes32 indexed poolId,
        address indexed token,
        address indexed creator,
        address pool,
        address optical,
        uint256 timestamp,
        uint256 blockNumber
    );

    event Swap(
        bytes32 indexed poolId,
        address indexed sender,
        bool isBuy,
        uint256 amountIn,
        uint256 amountOut,
        uint256 fee,
        uint256 price,
        uint256 timestamp,
        uint256 blockNumber
    );

    event FeeRecorded(
        bytes32 indexed poolId,
        uint256 feeAmount,
        uint256 protocolCut,
        uint256 poolCut,
        uint256 timestamp,
        uint256 blockNumber
    );

    event FeeDistributed(
        bytes32 indexed poolId,
        uint256 nftId,
        uint8 strategy,
        uint256 amount,
        address recipient,
        uint256 timestamp,
        uint256 blockNumber
    );

    event FeeStrategyChanged(
        bytes32 indexed poolId,
        uint256 nftId,
        uint8 oldStrategy,
        uint8 newStrategy,
        uint256 timestamp,
        uint256 blockNumber
    );

    event OpticalExecuted(
        bytes32 indexed poolId,
        address indexed optical,
        string hookName,
        bytes data,
        uint256 timestamp,
        uint256 blockNumber
    );

    event PoolStateUpdated(
        bytes32 indexed poolId,
        uint256 virtualReserve,
        uint256 realReserve,
        uint256 tokenReserve,
        uint256 price,
        uint256 timestamp,
        uint256 blockNumber
    );

    event ConfigUpdated(
        bytes32 indexed key,
        uint256 oldValue,
        uint256 newValue,
        uint256 timestamp,
        uint256 blockNumber
    );

    // --- Functions ---
    function emitMarketCreated(
        bytes32 poolId, address token, address creator, address pool, address optical
    ) external;

    function emitSwap(
        bytes32 poolId, address sender, bool isBuy,
        uint256 amountIn, uint256 amountOut, uint256 fee, uint256 price
    ) external;

    function emitFeeRecorded(
        bytes32 poolId, uint256 feeAmount, uint256 protocolCut, uint256 poolCut
    ) external;

    function emitFeeDistributed(
        bytes32 poolId, uint256 nftId, uint8 strategy, uint256 amount, address recipient
    ) external;

    function emitFeeStrategyChanged(
        bytes32 poolId, uint256 nftId, uint8 oldStrategy, uint8 newStrategy
    ) external;

    function emitPoolStateUpdated(
        bytes32 poolId, uint256 virtualReserve, uint256 realReserve, uint256 tokenReserve, uint256 price
    ) external;

    function emitOpticalExecuted(
        bytes32 poolId, address optical, string calldata hookName, bytes calldata data
    ) external;

    function emitConfigUpdated(bytes32 key, uint256 oldValue, uint256 newValue) external;

    function isAuthorizedEmitter(address emitter) external view returns (bool);
    function setAuthorizedEmitter(address emitter, bool authorized) external;

    // ════════════════════════════════════════════════════════════════════════
    //                                  v2
    //
    // Backward-compatible expansion of the v1 surface. All v1 events and
    // functions above remain identical (same selectors, same topic0, same
    // storage layout). v2 adds:
    //   - Generic schemaless emission (EventLog / EventLog1 / EventLog2)
    //     with indexed keccak256(eventName) for cheap topic1 filtering.
    //   - Typed fast-path emitters covering Meta-AG/PECOR, oracle,
    //     vault, governance, treasury, optical, NFT, token, role,
    //     upgrade and pause domains.
    //   - VERSION() accessor.
    //   - EVENT_EMITTER_ROLE — distinct from DEFAULT_ADMIN_ROLE — for
    //     emission authorization without granting upgrade rights.
    //
    // Reference: contracts/data/EVENT-EMITTER-V2-PLAN.md
    // ════════════════════════════════════════════════════════════════════════

    // --- Generic schemaless payload (GMX V2 pattern) ----------------------

    struct AddressKeyValue       { string key; address value; }
    struct AddressArrayKeyValue  { string key; address[] value; }
    struct UintKeyValue          { string key; uint256 value; }
    struct UintArrayKeyValue     { string key; uint256[] value; }
    struct IntKeyValue           { string key; int256 value; }
    struct IntArrayKeyValue      { string key; int256[] value; }
    struct BoolKeyValue          { string key; bool value; }
    struct BoolArrayKeyValue     { string key; bool[] value; }
    struct Bytes32KeyValue       { string key; bytes32 value; }
    struct Bytes32ArrayKeyValue  { string key; bytes32[] value; }
    struct BytesKeyValue         { string key; bytes value; }
    struct BytesArrayKeyValue    { string key; bytes[] value; }
    struct StringKeyValue        { string key; string value; }
    struct StringArrayKeyValue   { string key; string[] value; }

    struct AddressItems  { AddressKeyValue[]  items; AddressArrayKeyValue[]  arrayItems; }
    struct UintItems     { UintKeyValue[]     items; UintArrayKeyValue[]     arrayItems; }
    struct IntItems      { IntKeyValue[]      items; IntArrayKeyValue[]      arrayItems; }
    struct BoolItems     { BoolKeyValue[]     items; BoolArrayKeyValue[]     arrayItems; }
    struct Bytes32Items  { Bytes32KeyValue[]  items; Bytes32ArrayKeyValue[]  arrayItems; }
    struct BytesItems    { BytesKeyValue[]    items; BytesArrayKeyValue[]    arrayItems; }
    struct StringItems   { StringKeyValue[]   items; StringArrayKeyValue[]   arrayItems; }

    struct EventData {
        AddressItems addressItems;
        UintItems    uintItems;
        IntItems     intItems;
        BoolItems    boolItems;
        Bytes32Items bytes32Items;
        BytesItems   bytesItems;
        StringItems  stringItems;
    }

    /// @notice Generic schemaless event with no extra topics beyond eventNameHash.
    /// @dev `msgSender` records the actual caller (real provenance).
    ///      `eventNameHash = keccak256(bytes(eventName))` — indexed so off-chain
    ///      consumers filter on topic1 without decoding the string body.
    event EventLog(
        address indexed msgSender,
        bytes32 indexed eventNameHash,
        string eventName,
        EventData eventData,
        uint256 timestamp,
        uint256 blockNumber
    );

    /// @notice Generic schemaless event with one extra topic (eg. user / pool / token).
    event EventLog1(
        address indexed msgSender,
        bytes32 indexed eventNameHash,
        bytes32 indexed topic1,
        string eventName,
        EventData eventData,
        uint256 timestamp,
        uint256 blockNumber
    );

    /// @notice Generic schemaless event with two extra topics (eg. user + token, pool + nft).
    event EventLog2(
        address indexed msgSender,
        bytes32 indexed eventNameHash,
        bytes32 indexed topic1,
        bytes32 topic2,
        string eventName,
        EventData eventData,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitEventLog(
        string calldata eventName,
        EventData calldata data
    ) external;

    function emitEventLog1(
        string calldata eventName,
        bytes32 topic1,
        EventData calldata data
    ) external;

    function emitEventLog2(
        string calldata eventName,
        bytes32 topic1,
        bytes32 topic2,
        EventData calldata data
    ) external;

    // --- Typed fast-path: Meta-AG / PECOR ---------------------------------

    event PecorSwap(
        address indexed user,
        address indexed tokenIn,
        address indexed tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 priceIn,
        uint256 priceOut,
        uint256 volumeUSD,
        uint256 feeBps,
        uint256 feeAmount,
        uint256 impactBps,
        uint8 swapKind,        // 0=ExactIn 1=ExactOut 2=Market 3=Native 4=BestRoute
        uint256 timestamp,
        uint256 blockNumber
    );

    event PecorOrderCreated(
        uint256 indexed orderId,
        address indexed user,
        uint8 orderKind,       // 0=Limit 1=StopLimit 2=StopLoss
        uint8 orderType,       // 0=Buy 1=Sell
        address tokenIn,
        address tokenOut,
        uint256 amount,
        uint256 targetPrice,
        uint256 stopPrice,
        uint256 limitPrice,
        uint256 timestamp,
        uint256 blockNumber
    );

    event PecorOrderLifecycle(
        uint256 indexed orderId,
        address indexed user,
        uint8 orderKind,       // 0=Limit 1=StopLimit 2=StopLoss
        uint8 phase,           // 0=Activated 1=Executed 2=Cancelled 3=KeeperUpdated
        uint256 price,
        bytes payload,
        uint256 timestamp,
        uint256 blockNumber
    );

    event BestRouteSwap(
        address indexed user,
        address indexed tokenIn,
        address indexed tokenOut,
        bytes32 routeId,
        uint256 amountIn,
        uint256 amountOut,
        address[] hops,
        uint256 protocolFeeBps,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitPecorSwap(
        address user,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 priceIn,
        uint256 priceOut,
        uint256 volumeUSD,
        uint256 feeBps,
        uint256 feeAmount,
        uint256 impactBps,
        uint8 swapKind
    ) external;

    function emitPecorOrderCreated(
        uint256 orderId,
        address user,
        uint8 orderKind,
        uint8 orderType,
        address tokenIn,
        address tokenOut,
        uint256 amount,
        uint256 targetPrice,
        uint256 stopPrice,
        uint256 limitPrice
    ) external;

    function emitPecorOrderLifecycle(
        uint256 orderId,
        address user,
        uint8 orderKind,
        uint8 phase,
        uint256 price,
        bytes calldata payload
    ) external;

    function emitBestRouteSwap(
        address user,
        address tokenIn,
        address tokenOut,
        bytes32 routeId,
        uint256 amountIn,
        uint256 amountOut,
        address[] calldata hops,
        uint256 protocolFeeBps
    ) external;

    // --- Typed fast-path: Oracle ------------------------------------------

    event PriceUpdated(
        address indexed token,
        uint256 indexed roundId,
        address indexed relayer,
        uint256 price,
        uint256 confidence,
        bytes32 sourceId,
        uint256 timestamp,
        uint256 blockNumber
    );

    event CircuitBreakerTriggered(
        address indexed token,
        bytes32 indexed sourceId,
        uint256 reportedPrice,
        uint256 referencePrice,
        uint256 deviationBps,
        uint256 timestamp,
        uint256 blockNumber
    );

    event OracleAdapterLifecycle(
        bytes32 indexed sourceId,
        address indexed adapter,
        uint8 phase,           // 0=Registered 1=Activated 2=Deactivated 3=PriorityUpdated
        uint256 priority,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitPriceUpdated(
        address token,
        uint256 roundId,
        address relayer,
        uint256 price,
        uint256 confidence,
        bytes32 sourceId
    ) external;

    function emitCircuitBreaker(
        address token,
        bytes32 sourceId,
        uint256 reportedPrice,
        uint256 referencePrice,
        uint256 deviationBps
    ) external;

    function emitOracleAdapterLifecycle(
        bytes32 sourceId,
        address adapter,
        uint8 phase,
        uint256 priority
    ) external;

    // --- Typed fast-path: Vault -------------------------------------------

    event VaultFlow(
        uint8 indexed flowType,    // 0=Deposit 1=Withdrawal 2=NativeDeposit 3=NativeWithdrawal 4=Emergency 5=ReservesSync
        address indexed token,
        address indexed party,
        uint256 amount,
        uint256 newReserve,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitVaultFlow(
        uint8 flowType,
        address token,
        address party,
        uint256 amount,
        uint256 newReserve
    ) external;

    // --- Typed fast-path: Governance / Timelock ---------------------------

    event Governance(
        uint8 indexed action,      // 0=TxQueued 1=TxExecuted 2=TxCancelled
                                   // 3=ProposalCreated 4=VoteCast 5=ProposalExecuted 6=ProposalCancelled
                                   // 7=ProposerChanged 8=GuardianChanged 9=AdminModeDeactivated
        bytes32 indexed id,
        address indexed actor,
        bytes payload,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitGovernance(
        uint8 action,
        bytes32 id,
        address actor,
        bytes calldata payload
    ) external;

    // --- Typed fast-path: Treasury ----------------------------------------

    event TreasuryFlow(
        uint8 indexed direction,   // 0=Deposit 1=Withdraw
        address indexed token,
        address indexed party,
        uint256 amount,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitTreasuryFlow(
        uint8 direction,
        address token,
        address party,
        uint256 amount
    ) external;

    // --- Typed fast-path: Optical -----------------------------------------

    event OpticalLifecycle(
        uint8 indexed action,      // 0=Registered 1=Deregistered 2=MetadataUpdated
                                   // 3=Deployed 4=Hooked 5=Triggered
        address indexed optical,
        address indexed pool,
        bytes32 name,
        bytes payload,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitOpticalLifecycle(
        uint8 action,
        address optical,
        address pool,
        bytes32 name,
        bytes calldata payload
    ) external;

    // --- Typed fast-path: Token / NFT mirrors -----------------------------

    event TokenTransfer(
        address indexed token,
        address indexed from,
        address indexed to,
        uint256 value,
        uint256 timestamp,
        uint256 blockNumber
    );

    event NftTransfer(
        address indexed nft,
        address indexed from,
        address indexed to,
        uint256 tokenId,
        uint256 timestamp,
        uint256 blockNumber
    );

    event AssetApproval(
        address indexed asset,
        address indexed owner,
        address indexed spender,
        uint256 valueOrTokenId,
        bool isNft,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitTokenTransfer(
        address token,
        address from,
        address to,
        uint256 value
    ) external;

    function emitNftTransfer(
        address nft,
        address from,
        address to,
        uint256 tokenId
    ) external;

    function emitAssetApproval(
        address asset,
        address owner,
        address spender,
        uint256 valueOrTokenId,
        bool isNft
    ) external;

    // --- Typed fast-path: Access-control & lifecycle ----------------------

    event RoleChange(
        uint8 indexed action,      // 0=Granted 1=Revoked 2=AdminChanged
        bytes32 indexed role,
        address indexed account,
        address sender,
        bytes32 previousAdminRole,
        uint256 timestamp,
        uint256 blockNumber
    );

    event ContractUpgraded(
        address indexed proxy,
        address indexed newImplementation,
        uint8 kind,                // 0=UUPS 1=Beacon 2=AdminChanged
        uint256 timestamp,
        uint256 blockNumber
    );

    event PauseToggle(
        address indexed pausedContract,
        bool paused,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitRoleChange(
        uint8 action,
        bytes32 role,
        address account,
        address sender,
        bytes32 previousAdminRole
    ) external;

    function emitUpgraded(
        address proxy,
        address newImplementation,
        uint8 kind
    ) external;

    function emitPauseToggle(
        address pausedContract,
        bool paused
    ) external;

    // --- Typed fast-path: Launchpad mirrors (additive to v1) --------------

    /// @notice Mirror of FeeAccumulator's full event surface, collapsed
    ///         into a single typed channel for indexer simplicity.
    event FeeFlow(
        uint8 indexed kind,        // 0=Recorded 1=Claimed 2=Burned
                                   // 3=AirdropTriggered 4=AirdropClaimed 5=LpRewardsSent
                                   // 6=ProtocolFeeSwept 7=OpticalSurplusRecorded 8=OpticalSurplusClaimed
        address indexed pool,
        address indexed party,
        uint256 amount,
        uint256 protocolCut,
        uint256 poolCut,
        uint256 epoch,
        uint256 timestamp,
        uint256 blockNumber
    );

    event RouterTrade(
        uint8 indexed kind,        // 0=Buy 1=Sell 2=MultihopSwap
        address indexed pool,
        address indexed sender,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 intermediateUsdl,
        uint256 timestamp,
        uint256 blockNumber
    );

    event NftMint(
        uint256 indexed tokenId,
        address indexed creator,
        address indexed pool,
        uint8 strategy,
        uint256 timestamp,
        uint256 blockNumber
    );

    event PoolRegistered(
        address indexed pool,
        address indexed token,
        address indexed creator,
        address optical,
        uint256 nftId,
        uint256 timestamp,
        uint256 blockNumber
    );

    event TokenDeployed(
        address indexed token,
        address indexed pool,
        address indexed creator,
        bytes32 salt,
        string name,
        string symbol,
        uint8 decimals,
        uint256 totalSupply,
        uint256 timestamp,
        uint256 blockNumber
    );

    function emitFeeFlow(
        uint8 kind,
        address pool,
        address party,
        uint256 amount,
        uint256 protocolCut,
        uint256 poolCut,
        uint256 epoch
    ) external;

    function emitRouterTrade(
        uint8 kind,
        address pool,
        address sender,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 intermediateUsdl
    ) external;

    function emitNftMint(
        uint256 tokenId,
        address creator,
        address pool,
        uint8 strategy
    ) external;

    function emitPoolRegistered(
        address pool,
        address token,
        address creator,
        address optical,
        uint256 nftId
    ) external;

    function emitTokenDeployed(
        address token,
        address pool,
        address creator,
        bytes32 salt,
        string calldata name,
        string calldata symbol,
        uint8 decimals,
        uint256 totalSupply
    ) external;

    // --- v2 administrative surface ----------------------------------------

    event TypedEmitterPermission(address indexed emitter, bytes4 indexed selector, bool allowed);
    function setTypedEmitter(address emitter, bytes4 selector, bool allowed) external;
    function isTypedEmitter(address emitter, bytes4 selector) external view returns (bool);

    /// @notice Semantic version string of the deployed implementation.
    function VERSION() external pure returns (string memory);

    /// @notice The role that can authorize emitters and wire registries.
    ///         Distinct from DEFAULT_ADMIN_ROLE (which retains upgrade authority).
    function EVENT_EMITTER_ROLE() external view returns (bytes32);

    /// @notice Wire dynamic auth registries (one-time admin call after v2 upgrade).
    function setOpticalRegistry(address registry) external;
    function setMetaAGRouter(address router) external;
    function setSidioraFactory(address factory) external;
    function setTokenRegistry(address registry) external;

    /// @notice Per-token registration for the dynamic ERC20 auto-auth path.
    ///         Allows pool-token Transfer mirrors without per-token admin tx.
    function registerToken(address token, address pool) external;
    function deregisterToken(address token) external;
    function isRegisteredToken(address token) external view returns (bool);

    /// @notice One-time storage migration entrypoint for v1 → v2 proxy upgrade.
    ///         Idempotent — safe to call once.
    function reinitializeV2(address adminWithEmitterRole) external;
}

contracts/interfaces/IFeeAccumulator.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title IFeeAccumulator
/// @notice Interface for fee tracking and distribution across pools
interface IFeeAccumulator {
    // --- Errors ---
    error Unauthorized();
    error ZeroAddress();
    error ZeroAmount();
    error NoFeesAccumulated();
    error WrongStrategy();
    error AlreadyClaimed();
    error AirdropNotTriggered();
    error InsufficientSurplus();
    error UnsupportedSnapshotToken();

    // --- Events ---
    event FeeRecorded(
        address indexed pool,
        uint256 feeAmount,
        uint256 protocolCut,
        uint256 poolCut
    );

    event FeesClaimed(
        address indexed pool,
        address indexed recipient,
        uint256 amount
    );

    event FeesBurned(
        address indexed pool,
        uint256 amount
    );

    event AirdropTriggered(
        address indexed pool,
        uint256 totalAmount,
        uint256 epoch
    );

    event AirdropClaimed(
        address indexed pool,
        address indexed holder,
        uint256 amount,
        uint256 epoch
    );

    event LpRewardsSent(
        address indexed pool,
        uint256 amount
    );

    event ProtocolFeeSwept(
        uint256 amount
    );

    event OpticalSurplusRecorded(
        address indexed pool,
        uint256 amount
    );

    event OpticalSurplusClaimed(
        address indexed pool,
        address indexed recipient,
        uint256 amount
    );

    // --- Functions ---

    /// @notice Record fees from a swap (pool-only)
    /// @param pool The pool address the fees are from
    /// @param feeAmount Total fee amount in USDL
    function recordFee(address pool, uint256 feeAmount) external;

    /// @notice Claim accumulated fees for a pool (CLAIM strategy, FeesRouter-only)
    /// @param pool The pool address
    /// @param recipient Address to receive the fees
    /// @return amount The amount of USDL claimed
    function claim(address pool, address recipient) external returns (uint256 amount);

    /// @notice Burn accumulated fees for a pool (BURN strategy, FeesRouter-only)
    /// @param pool The pool address
    /// @return amount The amount of USDL burned
    function burn(address pool) external returns (uint256 amount);

    /// @notice Trigger airdrop distribution for a pool (AIRDROP strategy, FeesRouter-only)
    /// @param pool The pool address
    /// @return totalAmount The total amount distributed
    function triggerAirdrop(address pool) external returns (uint256 totalAmount);
    function supportsAirdrop(address pool) external view returns (bool);

    /// @notice Claim airdrop share for a token holder
    /// @param pool The pool address
    /// @param holder The token holder address
    /// @return amount The amount of USDL claimed
    function claimAirdrop(address pool, address holder) external returns (uint256 amount);
    function claimAirdropEpoch(address pool, address holder, uint256 epoch) external returns (uint256 amount);

    /// @notice Send accumulated fees to pool as LP rewards (LP_REWARDS strategy, FeesRouter-only)
    /// @param pool The pool address
    /// @return amount The amount of USDL sent
    function sendLpRewards(address pool) external returns (uint256 amount);

    /// @notice Authorize a pool to record fees (Factory-only via FACTORY_ROLE)
    /// @param pool The pool address to authorize
    function authorizePool(address pool) external;

    /// @notice Get accumulated fees for a pool
    function getAccumulatedFees(address pool) external view returns (uint256);

    /// @notice Get pending protocol fees waiting to be swept
    function getProtocolFeesPending() external view returns (uint256);

    /// @notice Get airdrop balance for a pool
    function getAirdropBalance(address pool) external view returns (uint256);

    /// @notice Get cumulative USDL donated to pool liquidity
    function getLpRewardsBalance(address pool) external view returns (uint256);

    /// @notice Get current airdrop epoch for a pool
    function getAirdropEpoch(address pool) external view returns (uint256);

    /// @notice Check if holder has claimed for a specific epoch
    function hasClaimedAirdrop(address pool, address holder, uint256 epoch) external view returns (bool);

    /// @notice Authorize an optical to claim surplus (OPTICAL_GRANTER_ROLE only)
    /// @param optical The optical contract address to authorize
    function authorizeOptical(address optical) external;

    /// @notice Record optical surplus when beforeFeeDistribution returns adjustedFee < feeAmount
    /// @param pool The pool address
    /// @param amount The surplus amount to record
    function recordOpticalSurplus(address pool, uint256 amount) external;

    /// @notice Claim optical surplus for a pool (OPTICAL_CLAIM_ROLE only)
    /// @param pool The pool address
    /// @param amount Amount to claim
    /// @param recipient Address to receive the USDL
    function claimOpticalSurplus(address pool, uint256 amount, address recipient) external;

    /// @notice Get optical surplus balance for a pool
    function getOpticalSurplus(address pool) external view returns (uint256);
}

contracts/interfaces/IFeesRouter.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title IFeesRouter
/// @notice Interface for NFT-holder fee management
interface IFeesRouter {
    error UnsupportedSnapshotToken();
    // --- Errors ---
    error NotNftOwner();
    error WrongStrategy();
    error ZeroAddress();

    // --- Events ---
    event FeesClaimed(uint256 indexed nftId, address indexed owner, uint256 amount);
    event FeesBurned(uint256 indexed nftId, uint256 amount);
    event AirdropExecuted(uint256 indexed nftId, uint256 amount);
    event AirdropClaimed(uint256 indexed nftId, address indexed holder, uint256 amount);
    event LpRewardsExecuted(uint256 indexed nftId, uint256 amount);
    event FeeStrategyChanged(uint256 indexed nftId, uint8 oldStrategy, uint8 newStrategy);

    // --- Functions ---

    /// @notice Set fee strategy for a pool NFT (owner-only)
    /// @param nftId The NFT token ID
    /// @param newStrategy New fee strategy (0=CLAIM,1=BURN,2=AIRDROP,3=LP_REWARDS)
    function setFeeStrategy(uint256 nftId, uint8 newStrategy) external;

    /// @notice Claim accumulated fees (CLAIM strategy only, NFT owner)
    /// @param nftId The NFT token ID
    /// @return amount USDL amount claimed
    function claimFees(uint256 nftId) external returns (uint256 amount);

    /// @notice Execute burn of accumulated fees (BURN strategy only, NFT owner)
    /// @param nftId The NFT token ID
    /// @return amount USDL amount burned
    function executeBurn(uint256 nftId) external returns (uint256 amount);

    /// @notice Execute airdrop distribution (AIRDROP strategy only, NFT owner)
    /// @param nftId The NFT token ID
    /// @return amount Total USDL distributed
    function executeAirdrop(uint256 nftId) external returns (uint256 amount);

    /// @notice Claim airdrop share as a token holder
    /// @param nftId The NFT token ID for the pool
    /// @return amount USDL amount claimed
    function claimAirdrop(uint256 nftId) external returns (uint256 amount);
    function claimAirdropEpoch(uint256 nftId, uint256 epoch) external returns (uint256 amount);

    /// @notice Execute LP rewards transfer (LP_REWARDS strategy only, NFT owner)
    /// @param nftId The NFT token ID
    /// @return amount USDL amount sent to pool
    function executeLpRewards(uint256 nftId) external returns (uint256 amount);
}

