// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title PoolAddress
/// @notice Computes deterministic pool addresses from BeaconProxy CREATE2 parameters
/// @dev Used by Factory, Router, and Quoter to predict pool addresses before deployment
library PoolAddress {
    /// @notice Computes the CREATE2 address for a pool BeaconProxy
    /// @param factory The factory contract address (deployer)
    /// @param beacon The PoolBeacon address
    /// @param token The SidioraERC20 token address (used in salt)
    /// @param creationCode The BeaconProxy creation code
    /// @return pool The deterministic pool address
    function computeAddress(
        address factory,
        address beacon,
        address token,
        bytes memory creationCode,
        bytes memory initData
    ) internal pure returns (address pool) {
        bytes32 salt = keccak256(abi.encodePacked(token));
        bytes32 initCodeHash = keccak256(
            abi.encodePacked(creationCode, abi.encode(beacon, initData))
        );
        pool = address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(bytes1(0xff), factory, salt, initCodeHash)
                    )
                )
            )
        );
    }

    /// @notice Computes the salt used for pool CREATE2 deployment
    /// @param token The token address
    /// @return salt The salt bytes32
    function computeSalt(address token) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(token));
    }
}

contracts/libraries/ReserveLib.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "./SidioraMath.sol";

/// @title ReserveLib
/// @notice Constant-product AMM math with virtual reserves
/// @dev All functions are pure. Used by SidioraPool and Quoter.
///
/// Effective USDL Reserve = virtualUsdlReserve + realUsdlBalance
/// k = effectiveUsdlReserve × tokenReserve
///
/// BUY (USDL → Token):
///   amountOut = (tokenReserve × amountIn) / (effectiveUsdl + amountIn)
///
/// SELL (Token → USDL):
///   amountOut = (effectiveUsdl × amountIn) / (tokenReserve + amountIn)
library ReserveLib {
    error InsufficientInput();
    error InsufficientLiquidity();

    /// @notice Calculates effective USDL reserve (virtual + real)
    function getEffectiveReserves(
        uint256 virtualUsdl,
        uint256 realUsdl
    ) internal pure returns (uint256) {
        return virtualUsdl + realUsdl;
    }

    /// @notice Given an input amount and reserves, returns the output amount
    /// @dev Uses constant product formula: amountOut = (reserveOut * amountIn) / (reserveIn + amountIn)
    /// @param reserveIn Input reserve (effectiveUsdl for buys, tokenReserve for sells)
    /// @param reserveOut Output reserve (tokenReserve for buys, effectiveUsdl for sells)
    /// @param amountIn Input amount (after fee deduction)
    /// @return amountOut Output amount
    function getAmountOut(
        uint256 reserveIn,
        uint256 reserveOut,
        uint256 amountIn
    ) internal pure returns (uint256 amountOut) {
        if (amountIn == 0) revert InsufficientInput();
        if (reserveIn == 0 || reserveOut == 0) revert InsufficientLiquidity();

        // amountOut = (reserveOut * amountIn) / (reserveIn + amountIn)
        uint256 denominator = reserveIn + amountIn;
        amountOut = SidioraMath.mulDiv(reserveOut, amountIn, denominator);
    }

    /// @notice Given a desired output amount and reserves, returns the required input
    /// @dev Inverse of getAmountOut: amountIn = (reserveIn * amountOut) / (reserveOut - amountOut) + 1
    /// @param reserveIn Input reserve
    /// @param reserveOut Output reserve
    /// @param amountOut Desired output amount
    /// @return amountIn Required input amount
    function getAmountIn(
        uint256 reserveIn,
        uint256 reserveOut,
        uint256 amountOut
    ) internal pure returns (uint256 amountIn) {
        if (amountOut == 0) revert InsufficientInput();
        if (reserveIn == 0 || reserveOut == 0) revert InsufficientLiquidity();
        if (amountOut >= reserveOut) revert InsufficientLiquidity();

        // amountIn = (reserveIn * amountOut) / (reserveOut - amountOut) + 1
        uint256 denominator = reserveOut - amountOut;
        amountIn = SidioraMath.mulDiv(reserveIn, amountOut, denominator) + 1;
    }

    /// @notice Returns the current token price in USDL (18 decimal fixed-point)
    /// @dev price = effectiveUsdl * 1e18 / tokenReserve
    /// @param effectiveUsdl Virtual + real USDL reserve
    /// @param tokenReserve Token reserve
    /// @return price Token price in USDL with 18 decimals
    function getPrice(
        uint256 effectiveUsdl,
        uint256 tokenReserve
    ) internal pure returns (uint256 price) {
        if (tokenReserve == 0) revert InsufficientLiquidity();
        price = SidioraMath.mulDiv(effectiveUsdl, 1e18, tokenReserve);
    }

    /// @notice Returns market cap in USDL
    /// @dev marketCap = price * totalSupply / 1e18
    /// @param effectiveUsdl Virtual + real USDL reserve
    /// @param tokenReserve Token reserve in pool
    /// @param totalSupply Total token supply (including tokens outside pool)
    /// @return marketCap Market capitalization in USDL
    function getMarketCap(
        uint256 effectiveUsdl,
        uint256 tokenReserve,
        uint256 totalSupply
    ) internal pure returns (uint256 marketCap) {
        uint256 price = getPrice(effectiveUsdl, tokenReserve);
        marketCap = SidioraMath.mulDiv(price, totalSupply, 1e18);
    }
}

contracts/libraries/SidioraMath.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title SidioraMath
/// @notice Core math primitives: sqrt, mulDiv, min, max, abs, safe casting
/// @dev All functions are pure/internal. No external dependencies.
library SidioraMath {
    error Overflow();
    error DivisionByZero();

    /// @notice Calculates floor(sqrt(x)) using the Babylonian method
    /// @param x The value to take the square root of
    /// @return z The floor of the square root
    function sqrt(uint256 x) internal pure returns (uint256 z) {
        if (x == 0) return 0;
        if (x <= 3) return 1;

        z = x;
        uint256 y = (x >> 1) + 1;
        while (y < z) {
            z = y;
            y = (x / y + y) >> 1;
        }
    }

    /// @notice Calculates (a * b) / denominator with 512-bit intermediate precision
    /// @dev Reverts on denominator == 0 or result overflow
    /// @param a Multiplicand
    /// @param b Multiplier
    /// @param denominator Divisor
    /// @return result The 256-bit result
    function mulDiv(
        uint256 a,
        uint256 b,
        uint256 denominator
    ) internal pure returns (uint256 result) {
        if (denominator == 0) revert DivisionByZero();

        uint256 prod0;
        uint256 prod1;
        assembly {
            let mm := mulmod(a, b, not(0))
            prod0 := mul(a, b)
            prod1 := sub(sub(mm, prod0), lt(mm, prod0))
        }

        if (prod1 == 0) {
            return prod0 / denominator;
        }

        if (prod1 >= denominator) revert Overflow();

        unchecked {
            uint256 remainder;
            assembly {
                remainder := mulmod(a, b, denominator)
                prod1 := sub(prod1, gt(remainder, prod0))
                prod0 := sub(prod0, remainder)
            }

            uint256 twos = denominator & (0 - denominator);
            assembly {
                denominator := div(denominator, twos)
                prod0 := div(prod0, twos)
                twos := add(div(sub(0, twos), twos), 1)
            }
            prod0 |= prod1 * twos;

            uint256 inverse = (3 * denominator) ^ 2;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;
            inverse *= 2 - denominator * inverse;

            result = prod0 * inverse;
        }
    }

    /// @notice Calculates (a * b) / denominator, rounded up
    function mulDivRoundingUp(
        uint256 a,
        uint256 b,
        uint256 denominator
    ) internal pure returns (uint256 result) {
        result = mulDiv(a, b, denominator);
        if (mulmod(a, b, denominator) > 0) {
            if (result == type(uint256).max) revert Overflow();
            result++;
        }
    }

    /// @notice Returns the smaller of two values
    function min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }

    /// @notice Returns the larger of two values
    function max(uint256 a, uint256 b) internal pure returns (uint256) {
        return a > b ? a : b;
    }

    /// @notice Returns the absolute value of a signed integer
    function abs(int256 x) internal pure returns (uint256) {
        return x >= 0 ? uint256(x) : uint256(-(x + 1)) + 1;
    }

    /// @notice Safely casts a uint256 to uint128
    function safeCastToUint128(uint256 x) internal pure returns (uint128) {
        if (x > type(uint128).max) revert Overflow();
        return uint128(x);
    }

    /// @notice Safely casts a uint256 to int256
    function safeCastToInt256(uint256 x) internal pure returns (int256) {
        if (x > uint256(type(int256).max)) revert Overflow();
        return int256(x);
    }
}

