// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title TokenAddress
/// @notice Computes deterministic SidioraERC20 token addresses from CREATE2 parameters
/// @dev Used by Factory, Router, and Quoter to predict token addresses before deployment
library TokenAddress {
    /// @notice Computes the CREATE2 address for a SidioraERC20 token
    /// @param factory The factory contract address (deployer)
    /// @param creator The market creator address
    /// @param name Token name
    /// @param symbol Token symbol
    /// @param nonce Creator's nonce for uniqueness
    /// @param creationCode The SidioraERC20 creation code (without constructor args)
    /// @param totalSupply Token total supply
    /// @param recipient Initial token recipient (the pool)
    /// @return token The deterministic token address
    function computeAddress(
        address factory,
        address creator,
        string memory name,
        string memory symbol,
        uint256 nonce,
        bytes memory creationCode,
        uint256 totalSupply,
        address recipient
    ) internal pure returns (address token) {
        bytes32 salt = computeSalt(creator, name, symbol, nonce);
        bytes32 initCodeHash = keccak256(
            abi.encodePacked(creationCode, abi.encode(name, symbol, totalSupply, recipient))
        );
        token = address(
            uint160(
                uint256(
                    keccak256(
                        abi.encodePacked(bytes1(0xff), factory, salt, initCodeHash)
                    )
                )
            )
        );
    }

    /// @notice Computes the salt for token CREATE2 deployment
    /// @param creator The market creator
    /// @param name Token name
    /// @param symbol Token symbol
    /// @param nonce Creator's nonce
    /// @return salt The salt bytes32
    function computeSalt(
        address creator,
        string memory name,
        string memory symbol,
        uint256 nonce
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(creator, name, symbol, nonce));
    }
}

contracts/libraries/TransferHelper.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title TransferHelper
/// @notice Safe ERC20 transfer wrappers that handle non-standard return values
/// @dev Handles tokens that return bool, return nothing, or revert
library TransferHelper {
    error TransferFailed();
    error TransferFromFailed();
    error ApproveFailed();

    function _validReturn(bytes memory data) private pure returns (bool) {
        if (data.length == 0) return true;
        if (data.length != 32) return false;
        uint256 result;
        assembly { result := mload(add(data, 32)) }
        return result == 1;
    }

    /// @notice Safely transfers tokens (handles non-standard ERC20s)
    function safeTransfer(address token, address to, uint256 value) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0xa9059cbb, to, value) // transfer(address,uint256)
        );
        if (token.code.length == 0 || !success || !_validReturn(data)) {
            revert TransferFailed();
        }
    }

    /// @notice Safely transfers tokens from a sender (handles non-standard ERC20s)
    function safeTransferFrom(
        address token,
        address from,
        address to,
        uint256 value
    ) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x23b872dd, from, to, value) // transferFrom(address,address,uint256)
        );
        if (token.code.length == 0 || !success || !_validReturn(data)) {
            revert TransferFromFailed();
        }
    }

    /// @notice Safely approves a spender (handles non-standard ERC20s)
    function safeApprove(address token, address spender, uint256 value) internal {
        (bool success, bytes memory data) = token.call(
            abi.encodeWithSelector(0x095ea7b3, spender, value) // approve(address,uint256)
        );
        if (token.code.length == 0 || !success || !_validReturn(data)) {
            revert ApproveFailed();
        }
    }
}

contracts/meta-ag/adapters/SidioraAdapte.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

import {ISidioraPool} from "../../interfaces/ISidioraPool.sol";
import {ReentrancyGuard} from "../../base/ReentrancyGuard.sol";
import {IProtocolAdapter} from "../interfaces/IProtocolAdapter.sol";
import {IRouter} from "../../interfaces/IRouter.sol";
import {IQuoter} from "../../interfaces/IQuoter.sol";
import {IPoolRegistry} from "../../interfaces/IPoolRegistry.sol";
import {IERC20Minimal} from "../interfaces/IERC20Minimal.sol";
import {AccessControl} from "../../base/AccessControl.sol";
import {SidioraMath} from "../../libraries/SidioraMath.sol";
import {TransferHelper} from "../../libraries/TransferHelper.sol";

/// @title SidioraAdapter — IProtocolAdapter wrapper for Sidiora bonding-curve AMM
/// @notice Plugs the live Sidiora Launchpad Router/Quoter/PoolRegistry into
///         MetaAGRouter. Supports buy (USDL → token), sell (token → USDL),
///         and multihop (token → USDL → token) routes.
/// @dev Spec §7.10. Port of `dev/adapters/SidioraAdapter.sol` with:
///       - Live launchpad interfaces (`IRouter`, `IQuoter`, `IPoolRegistry`)
///       - FIX: `swapTokenToToken` → `swapTokenForToken` (actual live name)
///       - FIX: `swapTokenForToken` returns `(amountOut, intermediateUsdl)`
///       - Zero OpenZeppelin: `forceApprove` → `TransferHelper.safeApprove`
///         with S9 zero-first reset before approval, zero-reset after.
///       - Ownable → AccessControl with DEFAULT_ADMIN_ROLE on Timelock.
///
/// Flow:
///   1. caller (MetaAGRouter) approves this adapter for `amountIn` of tokenIn
///   2. executeSwap pulls tokenIn from `from` into the adapter
///   3. adapter approves the live Sidiora Router (zero→amountIn, S9)
///   4. adapter calls buy/sell/swapTokenForToken on the live Router
///   5. adapter resets approval to 0 (S9 cleanup)
///   6. adapter forwards received tokenOut to `recipient`
contract SidioraAdapter is IProtocolAdapter, AccessControl, ReentrancyGuard {

    bytes32 private constant _ADAPTER_ID = keccak256("SidioraAMM.v1");

    uint8 private constant _MODE_BUY = 0;
    uint8 private constant _MODE_SELL = 1;
    uint8 private constant _MODE_MULTIHOP = 2;

    error UnauthorizedPayer();
    error TransferAmountMismatch();
    event ConfigurationUpdated(bytes32 indexed field, address oldValue, address newValue);
    error ZeroAddress();
    error ZeroAmount();
    error Expired();
    error PairNotSupported();
    error PoolNotFound();
    error SlippageExceeded();

    IPoolRegistry public poolRegistry;
    IQuoter public quoter;
    IRouter public sidioraRouter;
    address public usdl;

    constructor(
        address poolRegistry_,
        address quoter_,
        address sidioraRouter_,
        address usdl_,
        address admin_
    ) {
        if (poolRegistry_ == address(0)) revert ZeroAddress();
        if (quoter_ == address(0)) revert ZeroAddress();
        if (sidioraRouter_ == address(0)) revert ZeroAddress();
        if (usdl_ == address(0)) revert ZeroAddress();
        if (admin_ == address(0)) revert ZeroAddress();

        _initReentrancyGuard();
        poolRegistry = IPoolRegistry(poolRegistry_);
        emit ConfigurationUpdated("quoter", address(quoter), quoter_);
        quoter = IQuoter(quoter_);
        sidioraRouter = IRouter(sidioraRouter_);
        emit ConfigurationUpdated("usdl", address(usdl), usdl_);
        usdl = usdl_;

        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
    }

    function setPoolRegistry(address registry) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (registry == address(0)) revert ZeroAddress();
        emit ConfigurationUpdated("poolRegistry", address(poolRegistry), registry);
        poolRegistry = IPoolRegistry(registry);
    }

    function setQuoter(address quoter_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (quoter_ == address(0)) revert ZeroAddress();
        quoter = IQuoter(quoter_);
    }

    function setSidioraRouter(address router) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (router == address(0)) revert ZeroAddress();
        emit ConfigurationUpdated("sidioraRouter", address(sidioraRouter), router);
        sidioraRouter = IRouter(router);
    }

    function setUsdl(address usdl_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (usdl_ == address(0)) revert ZeroAddress();
        usdl = usdl_;
    }

    function adapterId() external pure override returns (bytes32) {
        return _ADAPTER_ID;
    }

    function adapterName() external pure override returns (string memory) {
        return "SidioraAMM.v1";
    }

    function adapterVersion() external pure override returns (string memory) {
        return "1.0.0";
    }

    /// @inheritdoc IProtocolAdapter
    function supportsSwap(
        address tokenIn,
        address tokenOut
    ) public view override returns (bool) {
        if (tokenIn == tokenOut) return false;
        address usdl_ = usdl;
        if (tokenIn == usdl_) return _hasPool(tokenOut);
        if (tokenOut == usdl_) return _hasPool(tokenIn);
        return _hasPool(tokenIn) && _hasPool(tokenOut);
    }

    /// @inheritdoc IProtocolAdapter
    /// @dev Sidiora pools are dynamically discovered via the registry; returning
    ///      an empty list is the cheapest and forwards discovery to supportsSwap.
    function getSupportedPairs()
        external
        pure
        override
        returns (address[] memory tokenIns, address[] memory tokenOuts)
    {
        return (new address[](0), new address[](0));
    }

    /// @inheritdoc IProtocolAdapter
    function getMaxInput(
        address tokenIn,
        address tokenOut
    ) external view override returns (uint256) {
        if (!supportsSwap(tokenIn, tokenOut)) return 0;
        if (tokenIn == usdl) return type(uint256).max;
        address pool = _getPool(tokenIn);
        // Conservative fee-independent bound: gross curve output cannot exceed real USDL.
        try ISidioraPool(pool).getReserves() returns (uint256 virtualUsdl, uint256 realUsdl, uint256 tokens) {
            if (virtualUsdl == 0) return type(uint256).max;
            if (realUsdl == 0) return 0;
            return SidioraMath.mulDiv(realUsdl, tokens, virtualUsdl);
        } catch { return 0; }
    }

    /// @inheritdoc IProtocolAdapter
    /// @dev Invariant I1 — never reverts. Returns `available=false` on any issue.
    function getQuote(
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external view override returns (QuoteResult memory result) {
        try this.quoteChecked(tokenIn, tokenOut, amountIn) returns (QuoteResult memory q) { return q; } catch { return result; }
    }

    function quoteChecked(address tokenIn, address tokenOut, uint256 amountIn) external view returns (QuoteResult memory result) {
        if (tokenIn == tokenOut || amountIn == 0) return result;
        if (!supportsSwap(tokenIn, tokenOut)) return result;

        address usdl_ = usdl;

        if (tokenIn == usdl_) {
            address pool = _getPool(tokenOut);
            if (pool == address(0) || ISidioraPool(pool).opticalAddress() != address(0)) return result;
            try quoter.quoteExactInput(pool, amountIn, true) returns (IQuoter.QuoteResult memory q) {
                result = QuoteResult({
                    amountOut: q.amountOut,
                    priceImpactBps: q.priceImpactBps,
                    feeBps: 0,
                    feeAmount: q.feeAmount,
                    available: q.amountOut > 0,
                    adapterData: abi.encode(_MODE_BUY, pool, address(0))
                });
            } catch {}
            return result;
        }

        if (tokenOut == usdl_) {
            address pool = _getPool(tokenIn);
            if (pool == address(0) || ISidioraPool(pool).opticalAddress() != address(0)) return result;
            try quoter.quoteExactInput(pool, amountIn, false) returns (IQuoter.QuoteResult memory q) {
                result = QuoteResult({
                    amountOut: q.amountOut,
                    priceImpactBps: q.priceImpactBps,
                    feeBps: 0,
                    feeAmount: q.feeAmount,
                    available: q.amountOut > 0 && _hasRealLiquidity(pool, q.amountOut),
                    adapterData: abi.encode(_MODE_SELL, pool, address(0))
                });
            } catch {}
            return result;
        }

        try quoter.quoteMultihop(tokenIn, tokenOut, amountIn) returns (
            IQuoter.MultihopQuoteResult memory mq
        ) {
            if (ISidioraPool(mq.poolA).opticalAddress() != address(0) || ISidioraPool(mq.poolB).opticalAddress() != address(0)) return result;
            if (!_hasRealLiquidity(mq.poolA, mq.intermediateUsdl)) return result;
            // feeAmount is in USDL for this multihop quote. Convert the sell
            // fee at the first leg execution rate before adding the buy fee.
            uint256 totalFee = mq.buyFeeAmount;
            if (amountIn > mq.sellFeeAmount) totalFee += SidioraMath.mulDiv(mq.sellFeeAmount, mq.intermediateUsdl, amountIn - mq.sellFeeAmount);
            result = QuoteResult({
                amountOut: mq.amountOut,
                priceImpactBps: mq.combinedPriceImpactBps,
                feeBps: 0,
                feeAmount: totalFee,
                available: mq.amountOut > 0,
                adapterData: abi.encode(_MODE_MULTIHOP, mq.poolA, mq.poolB)
            });
        } catch {}
    }

    /// @inheritdoc IProtocolAdapter
    /// @dev Caller must have approved THIS adapter for at least `amountIn` of tokenIn
    ///      before calling. The adapter performs the S9 approval-reset dance against
    ///      the live Sidiora Router to stay compatible with non-standard ERC20s.
    function executeSwap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address from,
        address recipient,
        uint256 deadline,
        bytes calldata adapterData
    ) external override nonReentrant returns (SwapResult memory result) {
        if (from != msg.sender) revert UnauthorizedPayer();
        if (recipient == address(0)) revert ZeroAddress();
        if (deadline != 0 && block.timestamp > deadline) revert Expired();
        if (amountIn == 0) revert ZeroAmount();
        if (!supportsSwap(tokenIn, tokenOut)) revert PairNotSupported();
        // This adapter cannot authenticate the original trader through the
        // legacy periphery entry points. Do not bypass per-user optical rules.
        if (tokenIn != usdl && ISidioraPool(_getPool(tokenIn)).opticalAddress() != address(0)) revert PairNotSupported();
        if (tokenOut != usdl && ISidioraPool(_getPool(tokenOut)).opticalAddress() != address(0)) revert PairNotSupported();

        (uint8 mode, , ) = abi.decode(adapterData, (uint8, address, address));
        uint8 expectedMode = tokenIn == usdl ? _MODE_BUY : tokenOut == usdl ? _MODE_SELL : _MODE_MULTIHOP;
        if (mode != expectedMode) revert PairNotSupported();

        uint256 beforeInput = IERC20Minimal(tokenIn).balanceOf(address(this));
        TransferHelper.safeTransferFrom(tokenIn, from, address(this), amountIn);
        if (IERC20Minimal(tokenIn).balanceOf(address(this)) - beforeInput != amountIn) revert TransferAmountMismatch();
        uint256 beforeOutput = IERC20Minimal(tokenOut).balanceOf(address(this));

        address sidioraRouter_ = address(sidioraRouter);
        uint256 routerDeadline = deadline == 0 ? type(uint256).max : deadline;

        TransferHelper.safeApprove(tokenIn, sidioraRouter_, 0);
        TransferHelper.safeApprove(tokenIn, sidioraRouter_, amountIn);

        uint256 amountOut;
        if (mode == _MODE_BUY) {
            address pool = _getPool(tokenOut);
            if (pool == address(0)) revert PoolNotFound();
            amountOut = sidioraRouter.buy(pool, amountIn, minAmountOut, routerDeadline);
        } else if (mode == _MODE_SELL) {
            address pool = _getPool(tokenIn);
            if (pool == address(0)) revert PoolNotFound();
            amountOut = sidioraRouter.sell(pool, amountIn, minAmountOut, routerDeadline);
        } else {
            (amountOut, ) = sidioraRouter.swapTokenForToken(
                tokenIn,
                tokenOut,
                amountIn,
                minAmountOut,
                routerDeadline
            );
        }

        TransferHelper.safeApprove(tokenIn, sidioraRouter_, 0);

        if (IERC20Minimal(tokenIn).balanceOf(address(this)) != beforeInput) revert TransferAmountMismatch();
        amountOut = IERC20Minimal(tokenOut).balanceOf(address(this)) - beforeOutput;
        if (recipient != address(this)) {
            uint256 beforeReceipt = IERC20Minimal(tokenOut).balanceOf(recipient);
            TransferHelper.safeTransfer(tokenOut, recipient, amountOut);
            amountOut = IERC20Minimal(tokenOut).balanceOf(recipient) - beforeReceipt;
        }
        if (amountOut < minAmountOut) revert SlippageExceeded();

        emit SwapExecuted(_ADAPTER_ID, tokenIn, tokenOut, amountIn, amountOut, recipient);

        result = SwapResult({
            amountOut: amountOut,
            feeAmount: 0,
            adapterData: ""
        });
    }

    function _hasRealLiquidity(address pool, uint256 output) internal view returns (bool) {
        (, uint256 realUsdl, ) = ISidioraPool(pool).getReserves();
        return output <= realUsdl;
    }

    function _hasPool(address token) internal view returns (bool) {
        return _getPool(token) != address(0);
    }

    function _getPool(address token) internal view returns (address pool) {
        try poolRegistry.getPoolByToken(token) returns (address p) {
            return p;
        } catch {
            return address(0);
        }
    }
}

