// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

import {ITransactionTracker} from "../interfaces/ITransactionTracker.sol";
import {Initializable} from "../../base/Initializable.sol";
import {UUPSUpgradeable} from "../../base/UUPSUpgradeable.sol";
import {AccessControl} from "../../base/AccessControl.sol";

/// @title TransactionTracker — PECOR-flow analytics event hub
/// @notice Sibling of Sidiora Launchpad's `EventEmitter` (spec §7.12). Authorized
///         emitters (PECOR, PECOROrders, PECORVault, MetaAGRouter) call in via
///         EMITTER_ROLE to record trade / order / liquidity events + aggregate
///         daily/token/user stats. Indexers consume the emitted events off-chain.
/// @dev Spec reference: `docs/architecture/pecor-sidiora-aggregator-spec.md` §7.12
///      (FROZEN 2026-04-24). Interface:
///      `contracts/meta-ag/interfaces/ITransactionTracker.sol`.
///
/// Inheritance (spec §7.12):
///   ITransactionTracker, Initializable, UUPSUpgradeable, AccessControl
///
/// Roles:
///   - DEFAULT_ADMIN_ROLE → Timelock at deploy (invariant S1)
///   - EMITTER_ROLE       → granted to each authorized emitter via
///                          {setAuthorizedEmitter} (invariant S11)
///
/// Storage layout (append-only per S12):
///   slot 0:  AccessControl._roles             (mapping)
///   slot 1:  authorizedEmitters               (mapping) — mirror of EMITTER_ROLE
///   slot 2:  currentDayTimestamp              (uint256)
///   slot 3:  currentDayStats                  (DailyStats, 4 slots: 3..6)
///   slot 7:  dailyStats                       (mapping)
///   slot 8:  tokenStats                       (mapping)
///   slot 9:  userStats                        (mapping)
///   slot 10: dailyTraders                     (nested mapping)
///   slot 11..60: __gap[50]
contract TransactionTracker is
    ITransactionTracker,
    Initializable,
    UUPSUpgradeable,
    AccessControl
{

    bytes32 public constant EMITTER_ROLE = keccak256("EMITTER_ROLE");

    error ZeroAddress();

    /// @notice Mirror of `EMITTER_ROLE` membership (kept for cheap O(1) bool view).
    mapping(address => bool) public authorizedEmitters;

    /// @notice Start-of-day Unix timestamp (floored to 1 day) for the active bucket.
    uint256 public currentDayTimestamp;

    /// @notice Aggregated stats for the currently-accumulating day.
    DailyStats public currentDayStats;

    /// @notice Historical daily stats keyed by day-floor timestamp.
    mapping(uint256 => DailyStats) public dailyStats;

    /// @notice Per-token lifetime totals.
    mapping(address => TokenStats) public tokenStats;

    /// @notice Per-user lifetime totals.
    mapping(address => UserStats) public userStats;

    /// @dev Bitmap of which users have traded in a given day (drives
    ///      `currentDayStats.uniqueTraders`). Private; not exposed on ABI.
    mapping(uint256 => mapping(address => bool)) private _dailyTraders;

    /// @dev Reserved storage for future upgrades (S12: append-only, 50 * 32 bytes).
    uint256[50] private __gap;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @inheritdoc ITransactionTracker
    function initialize(address admin) external override initializer {
        if (admin == address(0)) revert ZeroAddress();
        currentDayTimestamp = _getDayTimestamp(block.timestamp);
        currentDayStats.timestamp = currentDayTimestamp;
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}

    /// @inheritdoc ITransactionTracker
    function setAuthorizedEmitter(
        address emitter,
        bool authorized
    ) external override onlyRole(DEFAULT_ADMIN_ROLE) {
        if (emitter == address(0)) revert ZeroAddress();
        authorizedEmitters[emitter] = authorized;
        if (authorized) {
            _grantRole(EMITTER_ROLE, emitter);
        } else {
            _revokeRole(EMITTER_ROLE, emitter);
        }
        emit AuthorizedEmitterUpdated(emitter, authorized);
    }

    /// @inheritdoc ITransactionTracker
    function forceDaySnapshot() external override onlyRole(DEFAULT_ADMIN_ROLE) {
        _updateDayIfNeeded();
    }

    /// @inheritdoc ITransactionTracker
    function recordTrade(
        address user,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 volumeUSD
    ) external override onlyRole(EMITTER_ROLE) {
        _updateDayIfNeeded();

        currentDayStats.totalVolume += volumeUSD;
        currentDayStats.totalTrades += 1;

        if (!_dailyTraders[currentDayTimestamp][user]) {
            _dailyTraders[currentDayTimestamp][user] = true;
            currentDayStats.uniqueTraders += 1;
        }

        uint256 halfVolume = volumeUSD / 2;
        TokenStats storage sIn = tokenStats[tokenIn];
        sIn.totalVolume += halfVolume;
        sIn.tradeCount += 1;
        sIn.lastTradeTimestamp = block.timestamp;

        TokenStats storage sOut = tokenStats[tokenOut];
        sOut.totalVolume += halfVolume;
        sOut.tradeCount += 1;
        sOut.lastTradeTimestamp = block.timestamp;

        UserStats storage u = userStats[user];
        if (u.firstTradeTimestamp == 0) {
            u.firstTradeTimestamp = block.timestamp;
        }
        u.totalVolume += volumeUSD;
        u.tradeCount += 1;
        u.lastTradeTimestamp = block.timestamp;

        emit TradeExecuted(
            user,
            tokenIn,
            tokenOut,
            amountIn,
            amountOut,
            volumeUSD,
            block.timestamp
        );
        emit UserTradeMetrics(user, u.totalVolume, u.tradeCount, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordMarketTrade(
        address user,
        address stablecoin,
        address token,
        uint256 stablecoinAmount,
        uint256 tokenAmount,
        bool isBuy,
        uint256 executionPrice
    ) external override onlyRole(EMITTER_ROLE) {
        emit MarketTrade(
            user,
            stablecoin,
            token,
            stablecoinAmount,
            tokenAmount,
            isBuy,
            executionPrice,
            block.timestamp
        );
    }

    /// @inheritdoc ITransactionTracker
    function recordLimitOrderPlaced(
        uint256 orderId,
        address user,
        address token,
        address stablecoin,
        uint256 amount,
        uint256 targetPrice,
        bool isBuy
    ) external override onlyRole(EMITTER_ROLE) {
        emit LimitOrderPlaced(
            orderId,
            user,
            token,
            stablecoin,
            amount,
            targetPrice,
            isBuy,
            block.timestamp
        );
    }

    /// @inheritdoc ITransactionTracker
    function recordLimitOrderExecuted(
        uint256 orderId,
        address user,
        uint256 executionPrice
    ) external override onlyRole(EMITTER_ROLE) {
        emit LimitOrderExecuted(orderId, user, executionPrice, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordLimitOrderCancelled(
        uint256 orderId,
        address user
    ) external override onlyRole(EMITTER_ROLE) {
        emit LimitOrderCancelled(orderId, user, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordStopLossPlaced(
        uint256 orderId,
        address user,
        address token,
        uint256 tokenAmount,
        uint256 triggerPrice
    ) external override onlyRole(EMITTER_ROLE) {
        emit StopLossPlaced(orderId, user, token, tokenAmount, triggerPrice, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordStopLossTriggered(
        uint256 orderId,
        address user,
        uint256 triggerPrice,
        uint256 executionPrice,
        uint256 amountOut
    ) external override onlyRole(EMITTER_ROLE) {
        emit StopLossTriggered(
            orderId,
            user,
            triggerPrice,
            executionPrice,
            amountOut,
            block.timestamp
        );
    }

    /// @inheritdoc ITransactionTracker
    function recordStopLimitPlaced(
        uint256 orderId,
        address user,
        address token,
        uint256 amount,
        uint256 stopPrice,
        uint256 limitPrice,
        bool isBuy
    ) external override onlyRole(EMITTER_ROLE) {
        emit StopLimitPlaced(
            orderId,
            user,
            token,
            amount,
            stopPrice,
            limitPrice,
            isBuy,
            block.timestamp
        );
    }

    /// @inheritdoc ITransactionTracker
    function recordStopLimitActivated(
        uint256 orderId,
        uint256 activationPrice
    ) external override onlyRole(EMITTER_ROLE) {
        emit StopLimitActivated(orderId, activationPrice, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordStopLimitExecuted(
        uint256 orderId,
        address user,
        uint256 executionPrice
    ) external override onlyRole(EMITTER_ROLE) {
        emit StopLimitExecuted(orderId, user, executionPrice, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordLiquidityAdded(
        address token,
        address provider,
        uint256 amount,
        uint256 newReserve
    ) external override onlyRole(EMITTER_ROLE) {
        emit LiquidityAdded(token, provider, amount, newReserve, block.timestamp);
        emit VaultLiquidityUpdate(token, newReserve, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function recordLiquidityRemoved(
        address token,
        address remover,
        uint256 amount,
        uint256 newReserve
    ) external override onlyRole(EMITTER_ROLE) {
        emit LiquidityRemoved(token, remover, amount, newReserve, block.timestamp);
        emit VaultLiquidityUpdate(token, newReserve, block.timestamp);
    }

    /// @inheritdoc ITransactionTracker
    function getDailyStats(
        uint256 dayTimestamp
    ) external view override returns (DailyStats memory) {
        if (dayTimestamp == currentDayTimestamp) {
            return currentDayStats;
        }
        return dailyStats[dayTimestamp];
    }

    /// @inheritdoc ITransactionTracker
    function getTokenStats(address token) external view override returns (TokenStats memory) {
        return tokenStats[token];
    }

    /// @inheritdoc ITransactionTracker
    function getUserStats(address user) external view override returns (UserStats memory) {
        return userStats[user];
    }

    /// @inheritdoc ITransactionTracker
    function getCurrentDayStats() external view override returns (DailyStats memory stats) {
        uint256 today = _getDayTimestamp(block.timestamp);
        if (today > currentDayTimestamp) { stats.timestamp = today; return stats; }
        return currentDayStats;
    }

    function _grantRole(bytes32 role, address account) internal override returns (bool changed) {
        changed = super._grantRole(role, account);
        if (role == EMITTER_ROLE) authorizedEmitters[account] = true;
    }

    function _revokeRole(bytes32 role, address account) internal override returns (bool changed) {
        changed = super._revokeRole(role, account);
        if (role == EMITTER_ROLE) authorizedEmitters[account] = false;
    }

    function _getDayTimestamp(uint256 ts) private pure returns (uint256) {
        return (ts / 1 days) * 1 days;
    }

    function _updateDayIfNeeded() private {
        uint256 today = _getDayTimestamp(block.timestamp);
        if (today > currentDayTimestamp) {
            dailyStats[currentDayTimestamp] = currentDayStats;
            emit DailyStatsSnapshot(
                currentDayTimestamp,
                currentDayStats.totalVolume,
                currentDayStats.totalTrades,
                currentDayStats.uniqueTraders
            );

            currentDayTimestamp = today;
            currentDayStats = DailyStats({
                totalVolume: 0,
                totalTrades: 0,
                uniqueTraders: 0,
                timestamp: today
            });
        }
    }
}

