// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

import {SidioraMath} from "../../libraries/SidioraMath.sol";

/// @notice Exact decimal-normalized rational conversion without overflowing a
/// representable result. Prices are positive; supported token decimals are 0..36.
library PECORMath {
    error InvalidPriceOrDecimals();
    error QuoteOverflow();

    function convert(uint256 amount, uint256 priceIn, uint256 priceOut, uint8 dIn, uint8 dOut, bool up)
        internal pure returns (uint256 result)
    {
        if (priceIn == 0 || priceOut == 0 || dIn > 36 || dOut > 36) revert InvalidPriceOrDecimals();
        if (dOut >= dIn) {
            uint256 scale = 10 ** uint256(dOut - dIn);
            uint256 quotient = SidioraMath.mulDiv(amount, priceIn, priceOut);
            uint256 remainder = mulmod(amount, priceIn, priceOut);
            result = quotient * scale + SidioraMath.mulDiv(remainder, scale, priceOut);
            if (up && mulmod(remainder, scale, priceOut) != 0) ++result;
        } else {
            uint256 scale = 10 ** uint256(dIn - dOut);
            if (priceOut <= type(uint256).max / scale) {
                uint256 denominator = priceOut * scale;
                result = SidioraMath.mulDiv(amount, priceIn, denominator);
                if (up && mulmod(amount, priceIn, denominator) != 0) ++result;
            } else {
                // Only the extreme denominator case uses long division. Both
                // numerator and denominator remain exact 512-bit integers.
                (uint256 nHi, uint256 nLo) = _multiply(amount, priceIn);
                (uint256 dHi, uint256 dLo) = _multiply(priceOut, scale);
                uint256 rHi;
                uint256 rLo;
                for (uint256 bit = 512; bit != 0;) {
                    unchecked { --bit; }
                    rHi = (rHi << 1) | (rLo >> 255);
                    rLo = (rLo << 1) | (bit >= 256 ? (nHi >> (bit - 256)) & 1 : (nLo >> bit) & 1);
                    if (rHi > dHi || (rHi == dHi && rLo >= dLo)) {
                        unchecked {
                            rHi = rHi - dHi - (rLo < dLo ? 1 : 0);
                            rLo -= dLo;
                        }
                        if (bit >= 256) revert QuoteOverflow();
                        result |= uint256(1) << bit;
                    }
                }
                if (up && (rHi != 0 || rLo != 0)) ++result;
            }
        }
    }

    function _multiply(uint256 a, uint256 b) private pure returns (uint256 hi, uint256 lo) {
        assembly ("memory-safe") {
            let mm := mulmod(a, b, not(0))
            lo := mul(a, b)
            hi := sub(sub(mm, lo), lt(mm, lo))
        }
    }
}

contracts/meta-ag/engine/PECOROrderViews.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;
import {IPECOROrders} from "../interfaces/IPECOROrders.sol";
import {IPECORVault} from "../interfaces/IPECORVault.sol";
import {IERC20Minimal} from "../interfaces/IERC20Minimal.sol";
import {IPriceOracle} from "../interfaces/IPriceOracle.sol";
import {SidioraMath} from "../../libraries/SidioraMath.sol";
import {PECORMath} from "./PECORMath.sol";

struct PECOROrderPricing {
    uint256 fee;
    uint256 tier1;
    uint256 tier2;
    uint256 scalar;
    bool impact;
}

interface IPECOROrderViewState is IPECOROrders {
    function priceOracle() external view returns (address);
    function vault() external view returns (address);
    function getPricingConfig() external view returns (PECOROrderPricing memory);
    function orderExecutionPaused() external view returns (bool);
    function orderMinOutput(uint256 id) external view returns (uint256);
    function activeLimitOrderIds(uint256 index) external view returns (uint256);
    function activeStopLimitOrderIds(uint256 index) external view returns (uint256);
    function getActiveLimitOrderCount() external view returns (uint256);
    function getActiveStopLimitOrderCount() external view returns (uint256);
}

/// @notice Immutable read-only companion deployed by each Orders implementation.
/// No delegatecalls, custody or mutable state. Factoring views keeps the trading
/// implementation deployable under EIP-170 without changing compiler safety.
contract PECOROrderViews {
    error OrderNotFound();
    error InvalidDiscoveryKind();

    function price(address orders, address input, address output, uint256 amount)
        public view returns (uint256 gross, uint256 net)
    {
        IPECOROrderViewState state = IPECOROrderViewState(orders);
        IPriceOracle oracle = IPriceOracle(state.priceOracle());
        IPECORVault vault = IPECORVault(state.vault());
        PECOROrderPricing memory config = state.getPricingConfig();
        uint256 priceIn = oracle.getPrice(input);
        uint256 priceOut = oracle.getPrice(output);
        gross = PECORMath.convert(amount, priceIn, priceOut, vault.getTokenDecimals(input), vault.getTokenDecimals(output), false);
        uint256 volume = SidioraMath.mulDiv(amount, priceIn, 10 ** vault.getTokenDecimals(input));
        uint256 fees = config.fee;
        if (volume >= 10_000e18) fees += config.tier1;
        if (volume >= 100_000e18) fees += config.tier2;
        net = gross - SidioraMath.mulDiv(gross, fees, 10_000);
        uint256 reserveUSD = SidioraMath.mulDiv(vault.getAvailableReserves(output), priceOut, 10 ** vault.getTokenDecimals(output));
        if (config.impact && reserveUSD != 0) {
            uint256 impact = SidioraMath.mulDiv(volume, config.scalar, reserveUSD);
            if (impact > 500) impact = 500;
            net -= SidioraMath.mulDiv(net, impact, 10_000);
        }
    }

    function quoteOrder(address orders, uint256 id, bool stop) external view returns (address output, uint256 gross, uint256 net) {
        IPECOROrderViewState state = IPECOROrderViewState(orders);
        address input;
        uint256 amount;
        if (stop) {
            IPECOROrders.StopLimitOrder memory o = state.getStopLimitOrder(id);
            if (o.id == 0) revert OrderNotFound();
            bool buy = o.orderType == IPECOROrders.OrderType.STOP_LIMIT_BUY;
            input = buy ? o.stablecoin : o.token; output = buy ? o.token : o.stablecoin; amount = o.amount;
        } else {
            IPECOROrders.LimitOrder memory o = state.getLimitOrder(id);
            if (o.id == 0) revert OrderNotFound();
            bool buy = o.orderType == IPECOROrders.OrderType.LIMIT_BUY;
            input = buy ? o.stablecoin : o.token; output = buy ? o.token : o.stablecoin; amount = o.amount;
        }
        (gross, net) = price(orders, input, output, amount);
    }

    function canExecuteLimitOrder(address orders, uint256 id) public view returns (bool, string memory) {
        IPECOROrderViewState state = IPECOROrderViewState(orders);
        IPECOROrders.LimitOrder memory order = state.getLimitOrder(id);
        if (order.id == 0) return (false, "Order not found");
        if (order.status != IPECOROrders.OrderStatus.PENDING) return (false, "Order not pending");
        if (state.orderExecutionPaused()) return (false, "Paused");
        if (order.expiresAt != 0 && order.expiresAt <= block.timestamp) return (false, "Order expired");
        uint256 currentPrice;
        try IPriceOracle(state.priceOracle()).getPrice(order.token) returns (uint256 p) { currentPrice = p; }
        catch { return (false, "Price unavailable"); }
        if (order.orderType == IPECOROrders.OrderType.LIMIT_BUY && currentPrice > order.targetPrice) return (false, "Price above target");
        if (order.orderType == IPECOROrders.OrderType.LIMIT_SELL && currentPrice < order.targetPrice) return (false, "Price below target");
        if (order.orderType == IPECOROrders.OrderType.STOP_LOSS && currentPrice > order.targetPrice) return (false, "Price above trigger");
        return _fillFeasibility(state, id, false);
    }

    function _fillFeasibility(IPECOROrderViewState state, uint256 id, bool stop) internal view returns (bool, string memory) {
        try this.quoteOrder(address(state), id, stop) returns (address output, uint256 gross, uint256 net) {
            IPECORVault vault = IPECORVault(state.vault());
            address input;
            if (stop) {
                IPECOROrders.StopLimitOrder memory o = state.getStopLimitOrder(id);
                input = o.orderType == IPECOROrders.OrderType.STOP_LIMIT_BUY ? o.stablecoin : o.token;
            } else {
                IPECOROrders.LimitOrder memory o = state.getLimitOrder(id);
                input = o.orderType == IPECOROrders.OrderType.LIMIT_BUY ? o.stablecoin : o.token;
            }
            try IERC20Minimal(input).balanceOf(address(vault)) returns (uint256 custody) {
                if (custody < vault.getReservedBalance(input)) return (false, "Escrow deficit");
            } catch { return (false, "Escrow unavailable"); }
            if (net == 0 || net < state.orderMinOutput(id)) return (false, "Insufficient output");
            if (!IPECORVault(state.vault()).hasLiquidity(output, gross)) return (false, "Insufficient liquidity");
            return (true, "Executable");
        } catch { return (false, "Price unavailable"); }
    }

    /// @notice kind=0 executable limit, 1 activatable stop, 2 executable stop.
    /// Scan/allocation caps 100. Pin a block across pages: fills swap-and-pop.
    function getOrdersPage(address orders, uint256 cursor, uint256 maxScanned, uint256 maxCount, uint8 kind)
        external view returns (uint256[] memory ids, uint256 next)
    {
        if (kind > 2) revert InvalidDiscoveryKind();
        if (maxScanned > 100) maxScanned = 100;
        if (maxCount > 100) maxCount = 100;
        IPECOROrderViewState state = IPECOROrderViewState(orders);
        uint256 length = kind == 0 ? state.getActiveLimitOrderCount() : state.getActiveStopLimitOrderCount();
        if (cursor > length) cursor = length;
        uint256 end = cursor + (maxScanned < length - cursor ? maxScanned : length - cursor);
        uint256[] memory temp = new uint256[](maxCount);
        uint256 found;
        next = cursor;
        for (; next < end && found < maxCount; ++next) {
            uint256 id = kind == 0 ? state.activeLimitOrderIds(next) : state.activeStopLimitOrderIds(next);
            bool eligible;
            if (kind == 0) (eligible,) = canExecuteLimitOrder(orders, id);
            else {
                IPECOROrders.StopLimitOrder memory o = state.getStopLimitOrder(id);
                if (state.orderExecutionPaused() || o.expiresAt != 0 && o.expiresAt <= block.timestamp) continue;
                if (kind == 1 ? o.status != IPECOROrders.OrderStatus.PENDING : o.status != IPECOROrders.OrderStatus.ACTIVATED) continue;
                try IPriceOracle(state.priceOracle()).getPrice(o.token) returns (uint256 p) {
                    bool buy = o.orderType == IPECOROrders.OrderType.STOP_LIMIT_BUY;
                    eligible = kind == 1 ? (buy ? p >= o.stopPrice : p <= o.stopPrice) : (buy ? p <= o.limitPrice : p >= o.limitPrice);
                } catch { continue; }
                if (eligible && kind == 2) (eligible,) = _fillFeasibility(state, id, true);
            }
            if (eligible) temp[found++] = id;
        }
        ids = new uint256[](found);
        for (uint256 i; i < found; ++i) ids[i] = temp[i];
    }
}

contracts/meta-ag/engine/test/PECORAudit.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;
import {PECORMath} from "../PECORMath.sol";

contract PECORAuditOracle {
    mapping(address => uint256) public prices;
    mapping(address => bool) public unavailable;
    function setPrice(address token, uint256 price) external { prices[token] = price; }
    function setUnavailable(address token, bool value) external { unavailable[token] = value; }
    function getPrice(address token) external view returns (uint256) {
        require(!unavailable[token] && prices[token] != 0, "PRICE_UNAVAILABLE");
        return prices[token];
    }
}

contract PECORAuditTracker {
    fallback() external { revert("ANALYTICS_UNAVAILABLE"); }
}

contract PECORMathHarness {
    function convert(uint256 amount, uint256 inputPrice, uint256 outputPrice, uint8 inputDecimals, uint8 outputDecimals, bool roundUp)
        external pure returns (uint256)
    { return PECORMath.convert(amount, inputPrice, outputPrice, inputDecimals, outputDecimals, roundUp); }
}

/// @dev Raw uint256 metadata deliberately exercises ABI truncation cases.
contract PECORAuditMetadataToken {
    uint256 public decimals;
    uint256 public senderSurchargeBps;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    constructor(uint256 decimals_) { decimals = decimals_; }
    function mint(address user, uint256 amount) external { balanceOf[user] += amount; }
    function burn(address user, uint256 amount) external { balanceOf[user] -= amount; }
    function setSenderSurcharge(uint256 bps) external { senderSurchargeBps = bps; }
    function approve(address spender, uint256 amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transfer(address to, uint256 amount) external returns (bool) { _transfer(msg.sender, to, amount); return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount; _transfer(from, to, amount); return true;
    }
    function _transfer(address from, address to, uint256 amount) internal {
        balanceOf[from] -= amount + amount * senderSurchargeBps / 10000;
        balanceOf[to] += amount;
    }
}

contracts/meta-ag/interfaces/IPECOROrder.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

/**
 * @title IPECOROrders
 * @notice Interface for the PECOROrders engine — limit / stop-loss / stop-limit orders with
 *         keeper execution against PECORVault v2. Spec §7.7.
 * @dev UUPS-upgradeable, Timelock-admin. Funds-custody invariant: user funds are pulled
 *      into the vault at place-time; cancellation returns the exact pulled amount;
 *      execution swaps via vault push (never mints, never reroutes recipient).
 */
interface IPECOROrders {

    enum OrderType {
        LIMIT_BUY,
        LIMIT_SELL,
        STOP_LOSS,
        STOP_LIMIT_BUY,
        STOP_LIMIT_SELL
    }

    enum OrderStatus {
        PENDING,
        ACTIVATED,
        EXECUTED,
        CANCELLED,
        EXPIRED
    }

    /// @notice Trigger/limit prices are USD per whole token. minimumOutput is
    /// denominated in output-token base units and enforced on exact delivery.
    struct OrderRequest {
        OrderType orderType;
        address stablecoin;
        address token;
        uint256 amount;
        uint256 triggerPrice;
        uint256 limitPrice;
        uint256 expiresAt;
        uint256 minimumOutput;
    }

    function placeOrder(OrderRequest calldata request) external returns (uint256 orderId);

    struct LimitOrder {
        uint256 id;
        address user;
        address stablecoin;
        address token;
        uint256 amount;
        uint256 targetPrice;
        OrderType orderType;
        OrderStatus status;
        uint256 createdAt;
        uint256 expiresAt;
    }

    struct StopLimitOrder {
        uint256 id;
        address user;
        address stablecoin;
        address token;
        uint256 amount;
        uint256 stopPrice;
        uint256 limitPrice;
        OrderType orderType;
        OrderStatus status;
        uint256 createdAt;
        uint256 expiresAt;
    }

    /**
     * @notice Initialize the UUPS proxy (spec §7.7)
     * @param priceOracle IPriceOracle address
     * @param vault IPECORVault v2 address (must grant OPERATOR_ROLE to this contract)
     * @param tracker ITransactionTracker address (may be zero at bootstrap)
     * @param admin Timelock — granted DEFAULT_ADMIN_ROLE
     */
    function initialize(
        address priceOracle,
        address vault,
        address tracker,
        address admin
    ) external;

    /// @notice Grant / revoke KEEPER_ROLE in one call (spec §7.7).
    function setKeeper(address keeper, bool authorized) external;

    function pause() external;

    function unpause() external;

    function placeLimitBuy(
        address stablecoin,
        address token,
        uint256 stablecoinAmount,
        uint256 targetPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeLimitSell(
        address token,
        address stablecoin,
        uint256 tokenAmount,
        uint256 targetPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeStopLoss(
        address token,
        address stablecoin,
        uint256 tokenAmount,
        uint256 triggerPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeStopLimitBuy(
        address stablecoin,
        address token,
        uint256 stablecoinAmount,
        uint256 stopPrice,
        uint256 limitPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function placeStopLimitSell(
        address token,
        address stablecoin,
        uint256 tokenAmount,
        uint256 stopPrice,
        uint256 limitPrice,
        uint256 expiresAt
    ) external returns (uint256 orderId);

    function cancelLimitOrder(uint256 orderId) external;

    function cancelStopLimitOrder(uint256 orderId) external;

    function executeLimitOrder(uint256 orderId) external;

    function executeStopLimitOrder(uint256 orderId) external;

    function checkStopLimitActivation(uint256 orderId) external;

    function batchExecuteLimitOrders(
        uint256[] calldata orderIds
    ) external returns (uint256 executedCount);

    function batchCheckAndExecuteStopLimits(
        uint256[] calldata orderIds
    ) external returns (uint256 activatedCount, uint256 executedCount);

    function getLimitOrder(uint256 orderId) external view returns (LimitOrder memory);

    function getStopLimitOrder(uint256 orderId) external view returns (StopLimitOrder memory);

    function getUserLimitOrders(address user) external view returns (uint256[] memory);

    function getUserStopLimitOrders(address user) external view returns (uint256[] memory);

    function canExecuteLimitOrder(uint256 orderId) external view returns (bool, string memory);

    function getExecutableLimitOrders(
        uint256 maxCount
    ) external view returns (uint256[] memory orderIds);

    function getActivatableStopLimits(
        uint256 maxCount
    ) external view returns (uint256[] memory orderIds);

    function getExecutableStopLimits(
        uint256 maxCount
    ) external view returns (uint256[] memory orderIds);

    event LimitOrderCreated(
        uint256 indexed orderId,
        address indexed user,
        OrderType orderType,
        uint256 amount,
        uint256 targetPrice
    );
    event LimitOrderExecuted(uint256 indexed orderId, uint256 executionPrice);
    event LimitOrderCancelled(uint256 indexed orderId);
    event StopLimitOrderCreated(
        uint256 indexed orderId,
        address indexed user,
        OrderType orderType,
        uint256 amount,
        uint256 stopPrice,
        uint256 limitPrice
    );
    event StopLimitActivated(uint256 indexed orderId, uint256 activationPrice);
    event StopLimitExecuted(uint256 indexed orderId, uint256 executionPrice);
    event StopLimitCancelled(uint256 indexed orderId);
    event KeeperUpdated(address indexed keeper, bool authorized);
}

