// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

import {IERC20Minimal} from "../interfaces/IERC20Minimal.sol";

/// @title MockSidioraRouter
/// @notice Spy/stub for the live Sidiora IRouter surface consumed by SidioraAdapter.
/// @dev Only the three methods SidioraAdapter calls are implemented:
///       - buy(pool, usdlAmountIn, minTokensOut, deadline)
///       - sell(pool, tokenAmountIn, minUsdlOut, deadline)
///       - swapTokenForToken(tokenIn, tokenOut, amountIn, minAmountOut, deadline)
///            returns (amountOut, intermediateUsdl)  ← 2-tuple — regression surface
///
///      Not inheriting the full IRouter keeps this mock lightweight and avoids
///      dragging unrelated signatures (createMarket, permit variants, events) into
///      the adapter unit test scope.
///
///      The mock captures:
///        - call args (pool, amountIn, minOut, deadline, caller)
///        - call counts
///        - allowance observed at call entry (witnesses S9 zero→amountIn state)
///
///      The mock performs real ERC20 transfers to match the live Router's
///      transferFrom → transfer flow: pulls tokenIn from msg.sender using the
///      allowance the adapter just set, then sends a pre-funded amount of tokenOut
///      back. Pre-fund this mock with the required tokenOut balance before testing.
contract MockSidioraRouter {
    // ============ RECORDED STATE ============

    struct LastBuy {
        address pool;
        uint256 usdlAmountIn;
        uint256 minTokensOut;
        uint256 deadline;
        address caller;
        uint256 observedAllowance;
    }

    struct LastSell {
        address pool;
        uint256 tokenAmountIn;
        uint256 minUsdlOut;
        uint256 deadline;
        address caller;
        uint256 observedAllowance;
    }

    struct LastMultihop {
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 minAmountOut;
        uint256 deadline;
        address caller;
        uint256 observedAllowance;
    }

    LastBuy public lastBuy;
    LastSell public lastSell;
    LastMultihop public lastMultihop;

    uint256 public buyCallCount;
    uint256 public sellCallCount;
    uint256 public multihopCallCount;

    // ============ CONFIGURABLE RETURNS ============

    uint256 public buyReturn;
    uint256 public sellReturn;
    uint256 public multihopAmountOut;
    uint256 public multihopIntermediateUsdl;

    // ============ BEHAVIOR SWITCHES ============

    bool public revertOnBuy;
    bool public revertOnSell;
    bool public revertOnMultihop;
    string public revertReason;

    /// @notice If true, skip the inbound transferFrom. Useful for edge-case tests
    ///         where the adapter's approval flow should be observed without real
    ///         token movement.
    bool public skipTransfers;

    // ============ TOKEN ROUTING ============

    address public usdl;
    /// @dev For `buy(pool, ...)`: which token to send back. Set once per test.
    address public buyTokenOut;
    /// @dev For `sell(pool, ...)`: always returns USDL — no separate field.

    // ============ CONFIG ============

    function setUsdl(address usdl_) external {
        usdl = usdl_;
    }

    function setBuyTokenOut(address token) external {
        buyTokenOut = token;
    }

    function setBuyReturn(uint256 v) external {
        buyReturn = v;
    }

    function setSellReturn(uint256 v) external {
        sellReturn = v;
    }

    function setMultihopReturn(uint256 amountOut_, uint256 intermediateUsdl_) external {
        multihopAmountOut = amountOut_;
        multihopIntermediateUsdl = intermediateUsdl_;
    }

    function setRevertOnBuy(bool v, string calldata reason) external {
        revertOnBuy = v;
        revertReason = reason;
    }

    function setRevertOnSell(bool v, string calldata reason) external {
        revertOnSell = v;
        revertReason = reason;
    }

    function setRevertOnMultihop(bool v, string calldata reason) external {
        revertOnMultihop = v;
        revertReason = reason;
    }

    function setSkipTransfers(bool v) external {
        skipTransfers = v;
    }

    function resetCounts() external {
        buyCallCount = 0;
        sellCallCount = 0;
        multihopCallCount = 0;
    }

    // ============ IRouter.buy ============

    function buy(
        address pool,
        uint256 usdlAmountIn,
        uint256 minTokensOut,
        uint256 deadline
    ) external returns (uint256 amountOut) {
        if (revertOnBuy) revert(revertReason);

        uint256 allow = IERC20Minimal(usdl).allowance(msg.sender, address(this));

        lastBuy = LastBuy({
            pool: pool,
            usdlAmountIn: usdlAmountIn,
            minTokensOut: minTokensOut,
            deadline: deadline,
            caller: msg.sender,
            observedAllowance: allow
        });
        buyCallCount++;

        if (!skipTransfers) {
            // Pull USDL from caller (exercises adapter's S9 approval).
            IERC20Minimal(usdl).transferFrom(msg.sender, address(this), usdlAmountIn);
            // Send tokenOut back.
            if (buyReturn > 0) {
                IERC20Minimal(buyTokenOut).transfer(msg.sender, buyReturn);
            }
        }

        return buyReturn;
    }

    // ============ IRouter.sell ============

    function sell(
        address pool,
        uint256 tokenAmountIn,
        uint256 minUsdlOut,
        uint256 deadline
    ) external returns (uint256 amountOut) {
        if (revertOnSell) revert(revertReason);

        // tokenIn for a sell is the pool's token — the SidioraAdapter's caller
        // already transferred it into the adapter, which then approved this mock.
        // We don't track tokenIn by name here; the adapter passes it via its own
        // state. We observe allowance via the caller (adapter) directly.
        //
        // For witness purposes: we need to pull tokenAmountIn of *some* token.
        // The adapter passes a concrete tokenIn at call site; we fetch its
        // allowance via a helper the test sets up. To keep this mock simple,
        // the test must set `lastTokenInForSell` via a separate setter, OR
        // skip transfers and verify approval events externally.

        // Simplest approach: skip inbound transfer in sell; test asserts
        // allowance on the tokenIn contract directly.
        lastSell = LastSell({
            pool: pool,
            tokenAmountIn: tokenAmountIn,
            minUsdlOut: minUsdlOut,
            deadline: deadline,
            caller: msg.sender,
            observedAllowance: 0 // see below — captured via sellTokenInSnapshot
        });
        sellCallCount++;

        if (!skipTransfers) {
            // The adapter passes the pool's token in via approval; we honor
            // that by pulling via the tokenIn address set in sellTokenIn.
            if (sellTokenIn != address(0)) {
                lastSell.observedAllowance = IERC20Minimal(sellTokenIn).allowance(
                    msg.sender,
                    address(this)
                );
                IERC20Minimal(sellTokenIn).transferFrom(
                    msg.sender,
                    address(this),
                    tokenAmountIn
                );
            }
            // Send USDL back.
            if (sellReturn > 0) {
                IERC20Minimal(usdl).transfer(msg.sender, sellReturn);
            }
        }

        return sellReturn;
    }

    /// @dev Test sets this BEFORE calling the adapter's executeSwap for a sell,
    ///      so the mock knows which ERC20 to pull from the adapter.
    address public sellTokenIn;

    function setSellTokenIn(address token) external {
        sellTokenIn = token;
    }

    // ============ IRouter.swapTokenForToken ============
    // ⚠ REGRESSION SURFACE: returns (amountOut, intermediateUsdl) 2-tuple.
    //   SidioraAdapter must unpack only the first element — port adaptation
    //   vs the dev/ version's assumed 1-tuple return.

    function swapTokenForToken(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline
    ) external returns (uint256 amountOut, uint256 intermediateUsdl) {
        if (revertOnMultihop) revert(revertReason);

        uint256 allow = IERC20Minimal(tokenIn).allowance(msg.sender, address(this));

        lastMultihop = LastMultihop({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            amountIn: amountIn,
            minAmountOut: minAmountOut,
            deadline: deadline,
            caller: msg.sender,
            observedAllowance: allow
        });
        multihopCallCount++;

        if (!skipTransfers) {
            IERC20Minimal(tokenIn).transferFrom(msg.sender, address(this), amountIn);
            if (multihopAmountOut > 0) {
                IERC20Minimal(tokenOut).transfer(msg.sender, multihopAmountOut);
            }
        }

        return (multihopAmountOut, multihopIntermediateUsdl);
    }
}

contracts/meta-ag/mocks/MockStandardERC2.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

/**
 * @title MockStandardERC20
 * @notice Minimal test ERC20 for Sidiora Meta-AG vault tests.
 * @dev Scope-isolated under `contracts/meta-ag/mocks/` per the Phase 3 handoff;
 *      uses a distinct name from `contracts/test/MockERC20.sol` to avoid
 *      Hardhat `getContractFactory` ambiguity across the two scopes.
 */
contract MockStandardERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_, uint8 decimals_) {
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
    }

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function burn(address from, uint256 amount) external {
        require(balanceOf[from] >= amount, "MockStandardERC20: insufficient balance");
        totalSupply -= amount;
        balanceOf[from] -= amount;
        emit Transfer(from, address(0), amount);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 current = allowance[from][msg.sender];
        require(current >= amount, "MockStandardERC20: insufficient allowance");
        if (current != type(uint256).max) {
            allowance[from][msg.sender] = current - amount;
        }
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(balanceOf[from] >= amount, "MockStandardERC20: insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }
}

contracts/meta-ag/mocks/MockSwapFeeBeaco.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

/**
 * @title MockSwapFeeBeacon
 * @notice Minimal stand-in for the PECOR engine surface used by MetaAGQuoter.
 *         The quoter only ever reads `swapFeeBps()` via low-level staticcall,
 *         so this mock exposes that single function with a configurable value
 *         plus an optional revert switch to exercise the fail-soft path in
 *         `_getFeeBps`.
 * @dev Scope-isolated under `contracts/meta-ag/mocks/`. Do NOT use in
 *      production — this is for unit tests only.
 */
contract MockSwapFeeBeacon {
    error ForcedRevert();

    uint256 private _feeBps;
    bool private _shouldRevert;

    constructor(uint256 initialFeeBps_) {
        _feeBps = initialFeeBps_;
    }

    function setFeeBps(uint256 newFeeBps) external {
        _feeBps = newFeeBps;
    }

    function setRevert(bool flag) external {
        _shouldRevert = flag;
    }

    function swapFeeBps() external view returns (uint256) {
        if (_shouldRevert) revert ForcedRevert();
        return _feeBps;
    }
}

contracts/meta-ag/mocks/MockTxTracker.so.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

/**
 * @title MockTxTracker
 * @notice Deliberately-minimal stub for {ITransactionTracker} used by
 *         {PECORVault} tests. Phase 3 exercises the vault's tracker wiring
 *         (setTransactionTracker + event + zero-address accepted at
 *         bootstrap); the full tracker surface lands in Phase 7 (Task 7.2).
 * @dev The vault never reads back from the tracker during Phase 3, so this
 *      mock exposes no-op recorders. It simply captures the last call on
 *      each hook to keep future-phase compatibility trivial.
 */
contract MockTxTracker {
    address public lastCaller;
    bytes public lastPayload;
    uint256 public callCount;

    event Recorded(address indexed caller, bytes payload);

    /// @dev Generic catch-all recorder used by later phases; kept optional.
    function record(bytes calldata payload) external {
        lastCaller = msg.sender;
        lastPayload = payload;
        unchecked {
            callCount += 1;
        }
        emit Recorded(msg.sender, payload);
    }
}

contracts/meta-ag/mocks/MockWETH9.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

import {IWETH} from "../interfaces/IWETH.sol";

/**
 * @title MockWETH9
 * @notice Minimal WETH-compatible mock that mirrors the WPAX9 live contract
 *         on Paxeer Network. Used by {PECORVault} tests to exercise
 *         `depositNative` (wrap) and `withdrawNative` (unwrap) paths and to
 *         assert the {PECORVault.receive} WethOnly guard.
 * @dev Keeps the WETH9 ABI surface minimal enough to test the vault without
 *      pulling in an external WETH9 source.
 */
contract MockWETH9 is IWETH {
    // Non-constant public state vars (vs `constant`) mirror the pattern used
    // by the other meta-ag mocks (see MockReentrantERC20) and keep solhint's
    // const-name-snakecase rule happy while preserving the exact WETH ABI
    // (lowercase name/symbol/decimals, required for wallet compatibility).
    string public name = "Mock Wrapped PAX";
    string public symbol = "mWPAX";
    uint8 public decimals = 18;

    uint256 private _totalSupply;
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    error InsufficientBalance();
    error InsufficientAllowance();

    function totalSupply() external view override returns (uint256) {
        return _totalSupply;
    }

    function balanceOf(address owner) external view override returns (uint256) {
        return _balances[owner];
    }

    function allowance(address owner, address spender) external view override returns (uint256) {
        return _allowances[owner][spender];
    }

    function deposit() external payable override {
        _balances[msg.sender] += msg.value;
        _totalSupply += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw(uint256 wad) external override {
        if (_balances[msg.sender] < wad) revert InsufficientBalance();
        _balances[msg.sender] -= wad;
        _totalSupply -= wad;
        emit Withdrawal(msg.sender, wad);
        // solhint-disable-next-line avoid-low-level-calls
        (bool ok, ) = payable(msg.sender).call{value: wad}("");
        require(ok, "MockWETH9: native transfer failed");
    }

    function approve(address spender, uint256 value) external override returns (bool) {
        _allowances[msg.sender][spender] = value;
        return true;
    }

    function transfer(address to, uint256 value) external override returns (bool) {
        return _transfer(msg.sender, to, value);
    }

    function transferFrom(address from, address to, uint256 value) external override returns (bool) {
        uint256 current = _allowances[from][msg.sender];
        if (current < value) revert InsufficientAllowance();
        if (current != type(uint256).max) {
            _allowances[from][msg.sender] = current - value;
        }
        return _transfer(from, to, value);
    }

    function _transfer(address from, address to, uint256 value) internal returns (bool) {
        if (_balances[from] < value) revert InsufficientBalance();
        _balances[from] -= value;
        _balances[to] += value;
        return true;
    }

    /// @dev Accept native to let tests simulate arbitrary funding paths.
    receive() external payable {
        _balances[msg.sender] += msg.value;
        _totalSupply += msg.value;
        emit Deposit(msg.sender, msg.value);
    }
}

contracts/meta-ag/oracle/adapters/Sidior.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.27;

import {IDataFeedAdapter} from "../../interfaces/IDataFeedAdapter.sol";
import {ISidioraPool} from "../../../interfaces/ISidioraPool.sol";
import {IPoolRegistry} from "../../../interfaces/IPoolRegistry.sol";
import {IPriceOracle} from "../../interfaces/IPriceOracle.sol";
import {SidioraMath} from "../../../libraries/SidioraMath.sol";
import {AccessControl} from "../../../base/AccessControl.sol";

/// @title SidioraFeedAdapter
/// @notice {IDataFeedAdapter} wrapper that reads prices from Sidiora bonding-curve pools.
/// @dev Non-upgradeable. Admin (Timelock) may rotate the registry pointer and adjust the
///      liquidity threshold, and may register "known tokens" so that `getSupportedTokens`
///      can enumerate without iterating the full `IPoolRegistry`.
///
/// Spec: docs/architecture/pecor-sidiora-aggregator-spec.md §7.4
///
/// Confidence banding (aligned with dev/adapters/SidioraFeedAdapter.sol):
///   - pool.realUsdl >= minLiquidityThreshold        -> 7000 (HIGH)
///   - minLiquidityThreshold/4 <= realUsdl < threshold -> 4000 (MEDIUM)
///   - otherwise (inc. `getReserves` revert)         -> 1500 (LOW)
///   - pool returned zero price or lookups reverted  -> 0 (I7)
///
/// Per I9 documented exception: `feed.timestamp = block.timestamp` because Sidiora pool
/// prices update implicitly on every trade — there is no external "last update" clock.
contract SidioraFeedAdapter is IDataFeedAdapter, AccessControl {

    bytes32 private constant _SOURCE_ID = keccak256("SidioraAMM.v1");
    uint256 private constant _STALENESS_SECONDS = 120;

    uint256 public constant CONFIDENCE_HIGH = 7000;
    uint256 public constant CONFIDENCE_MEDIUM = 4000;
    uint256 public constant CONFIDENCE_LOW = 1500;

    error ZeroAddress();
    error InvalidConfig();
    event PoolRegistryUpdated(address indexed previous, address indexed current);
    event MinLiquidityThresholdUpdated(uint256 previous, uint256 current);
    event KnownTokenRegistered(address indexed token);
    event SpotReferenceConfigured(bool enabled, address indexed usdOracle, address indexed usdlToken);


    IPoolRegistry public poolRegistry;
    uint256 public minLiquidityThreshold;

    address[] private _knownTokens;
    mapping(address => bool) private _knownTokenSet;

    /// @notice Explicit risk opt-in: instantaneous pool reserves are manipulable.
    bool public spotReferenceEnabled;
    IPriceOracle public usdlUsdOracle;
    address public usdlToken;


    constructor(address poolRegistry_, uint256 minLiquidityThreshold_, address admin_) {
        if (poolRegistry_ == address(0) || admin_ == address(0)) revert ZeroAddress();
        if (minLiquidityThreshold_ == 0) revert InvalidConfig();
        poolRegistry = IPoolRegistry(poolRegistry_);
        minLiquidityThreshold = minLiquidityThreshold_;
        _grantRole(DEFAULT_ADMIN_ROLE, admin_);
    }

    function setPoolRegistry(address registry_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (registry_ == address(0)) revert ZeroAddress();
        emit PoolRegistryUpdated(address(poolRegistry), registry_);
        poolRegistry = IPoolRegistry(registry_);
    }

    function setMinLiquidityThreshold(uint256 threshold_) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (threshold_ == 0) revert InvalidConfig();
        emit MinLiquidityThresholdUpdated(minLiquidityThreshold, threshold_);
        minLiquidityThreshold = threshold_;
    }

    /// @notice Opt into manipulable spot references with an independently validated USDL/USD feed.
    /// @dev This is not TWAP or manipulation resistance. Disable for settlement-sensitive use.
    function configureSpotReference(bool enabled, address usdOracle, address usdl) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (enabled && (usdOracle.code.length == 0 || usdl == address(0))) revert InvalidConfig();
        spotReferenceEnabled = enabled;
        usdlUsdOracle = IPriceOracle(usdOracle);
        usdlToken = usdl;
        emit SpotReferenceConfigured(enabled, usdOracle, usdl);
    }

    function registerKnownToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _registerKnownToken(token);
    }

    function registerKnownTokens(address[] calldata tokens) external onlyRole(DEFAULT_ADMIN_ROLE) {
        for (uint256 i = 0; i < tokens.length; ++i) {
            _registerKnownToken(tokens[i]);
        }
    }

    function sourceId() external pure override returns (bytes32) {
        return _SOURCE_ID;
    }

    function adapterName() external pure override returns (string memory) {
        return "SidioraAMM.v1";
    }

    function maxStaleness() external pure override returns (uint256) {
        return _STALENESS_SECONDS;
    }

    function supportsToken(address token) external view override returns (bool) {
        return _getPool(token) != address(0);
    }

    function getSupportedTokens() external view override returns (address[] memory tokens) {
        return _knownTokens;
    }

    function getFeedPrice(address token) external view override returns (FeedPrice memory feed) {
        return _readFeed(token);
    }

    function getFeedPrices(
        address[] calldata tokens
    ) external view override returns (FeedPrice[] memory feeds) {
        feeds = new FeedPrice[](tokens.length);
        for (uint256 i = 0; i < tokens.length; ++i) {
            feeds[i] = _readFeed(tokens[i]);
        }
    }

    function _readFeed(address token) internal view returns (FeedPrice memory feed) {
        feed.sourceId = _SOURCE_ID;
        if (!spotReferenceEnabled) return feed;

        address pool = _getPool(token);
        if (pool == address(0)) return feed;

        uint256 price = _safeGetPrice(pool);
        if (price == 0) return feed;

        // getPrice enforces the reference oracle's configured per-token freshness.
        try usdlUsdOracle.getPrice(usdlToken) returns (uint256 usdPrice) {
            if (usdPrice == 0) return feed;
            feed.price = SidioraMath.mulDiv(price, usdPrice, 1e18);
        } catch { return feed; }
        feed.timestamp = block.timestamp;
        feed.confidence = _computeConfidence(pool);
    }

    function _getPool(address token) internal view returns (address pool) {
        try poolRegistry.getPoolByToken(token) returns (address p) {
            return p;
        } catch {
            return address(0);
        }
    }

    function _safeGetPrice(address pool) internal view returns (uint256 price) {
        try ISidioraPool(pool).getPrice() returns (uint256 p) {
            return p;
        } catch {
            return 0;
        }
    }

    function _computeConfidence(address pool) internal view returns (uint256) {
        try ISidioraPool(pool).getReserves() returns (uint256, uint256 realUsdl, uint256) {
            if (realUsdl >= minLiquidityThreshold) return CONFIDENCE_HIGH;
            if (realUsdl >= minLiquidityThreshold / 4) return CONFIDENCE_MEDIUM;
            return CONFIDENCE_LOW;
        } catch {
            return CONFIDENCE_LOW;
        }
    }

    function _registerKnownToken(address token) internal {
        if (token == address(0)) revert ZeroAddress();
        if (!_knownTokenSet[token]) {
            _knownTokenSet[token] = true;
            _knownTokens.push(token);
            emit KnownTokenRegistered(token);
        }
    }
}

