contracts/opticals/BaseOptical.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "./interfaces/IOptical.sol";
import "../interfaces/IPoolRegistry.sol";

/// @title BaseOptical
/// @notice Abstract base contract for building custom opticals.
/// @dev Provides default no-op implementations for all 4 hooks.
///      Inherit this to build custom opticals — override only the hooks you need.
///      Each optical is IMMUTABLE once deployed (audited once, deployed once).
abstract contract BaseOptical is IOptical {
    error NotPool();
    error NotOwner();

    /// @notice The PoolRegistry address for validating pool callers
    address public immutable poolRegistry;

    /// @notice The deployer/owner of this optical (for configuration)
    address public immutable owner;

    constructor(address _poolRegistry, address _owner) {
        poolRegistry = _poolRegistry;
        owner = _owner;
    }

    /// @dev Modifier to restrict calls to registered pools only.
    ///      Validates caller is a pool registered in PoolRegistry.
    modifier onlyPool() {
        if (!_isRegisteredPool(msg.sender)) revert NotPool();
        _;
    }

    /// @dev Modifier to restrict calls to the optical owner.
    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    // ============ DEFAULT NO-OP HOOKS ============

    /// @inheritdoc IOptical
    function beforeSwap(
        address pool, /* pool */
        address, /* sender */
        bool, /* isBuy */
        uint256 /* amountIn */
    ) external virtual override onlyAttachedPool(pool) returns (bool proceed, int256 amountDelta) {
        return (true, 0);
    }

    /// @inheritdoc IOptical
    function afterSwap(
        address pool, /* pool */
        address, /* sender */
        bool, /* isBuy */
        uint256, /* amountIn */
        uint256 /* amountOut */
    ) external virtual override onlyAttachedPool(pool) returns (bytes4) {
        return IOptical.afterSwap.selector;
    }

    /// @inheritdoc IOptical
    function beforeFeeDistribution(
        address pool, /* pool */
        uint256 feeAmount
    ) external virtual override onlyFeeAccumulator(pool) returns (uint256 adjustedFee) {
        return feeAmount;
    }

    /// @inheritdoc IOptical
    function afterFeeDistribution(
        address pool, /* pool */
        uint256 /* feeAmount */
    ) external virtual override onlyFeeAccumulator(pool) returns (bytes4) {
        return IOptical.afterFeeDistribution.selector;
    }

    /// @inheritdoc IOptical
    function getFlags() external view virtual override returns (uint8) {
        return 0;
    }

    // ============ INTERNAL HELPERS ============

    modifier onlyAttachedPool(address pool) {
        if (msg.sender != pool || !_isRegisteredPool(pool)) revert NotPool();
        _;
    }

    modifier onlyFeeAccumulator(address pool) {
        if (!_isRegisteredPool(pool)) revert NotPool();
        (bool ok, bytes memory data) = pool.staticcall(abi.encodeWithSignature("feeAccumulator()"));
        if (!ok || data.length != 32 || abi.decode(data, (address)) != msg.sender) revert NotPool();
        _;
    }

    function _isRegisteredPool(address pool) internal view returns (bool) {
        if (poolRegistry == address(0)) return false;
        IPoolRegistry.PoolMetadata memory meta = IPoolRegistry(poolRegistry).getPoolMetadata(pool);
        return meta.creator != address(0) && meta.optical == address(this);
    }

    function _poolMetadata(address pool) internal view returns (IPoolRegistry.PoolMetadata memory) {
        if (!_isRegisteredPool(pool)) revert NotPool();
        return IPoolRegistry(poolRegistry).getPoolMetadata(pool);
    }

    /// @dev Helper to read pool reserves for opticals that need pricing data.
    function _getPoolReserves(address pool) internal view returns (
        uint256 virtualUsdl,
        uint256 realUsdl,
        uint256 tokenRes
    ) {
        (bool success, bytes memory data) = pool.staticcall(
            abi.encodeWithSignature("getReserves()")
        );
        if (!success || data.length < 96) revert NotPool();
        (virtualUsdl, realUsdl, tokenRes) = abi.decode(data, (uint256, uint256, uint256));
    }
}

contracts/opticals/interfaces/IOptical.s.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

/// @title IOptical
/// @notice Interface for optical hook plugins that inject custom logic into pool lifecycle.
/// @dev Inspired by Uniswap V4's hook system, adapted for Sidiora's launchpad model.
///      Each optical implements a subset of hooks indicated by getFlags().
///      Bit 0: beforeSwap, Bit 1: afterSwap,
///      Bit 2: beforeFeeDistribution, Bit 3: afterFeeDistribution
interface IOptical {
    /// @notice Called before a swap executes in the pool.
    /// @param pool The pool address executing the swap
    /// @param sender The address initiating the swap
    /// @param isBuy True if buying tokens with USDL, false if selling tokens for USDL
    /// @param amountIn The input amount for the swap
    /// @return proceed Whether the swap should continue (false = reject)
    /// @return amountDelta Adjustment to amountIn (positive = increase, negative = decrease)
    function beforeSwap(
        address pool,
        address sender,
        bool isBuy,
        uint256 amountIn
    ) external returns (bool proceed, int256 amountDelta);

    /// @notice Called after a swap completes in the pool.
    /// @param pool The pool address that executed the swap
    /// @param sender The address that initiated the swap
    /// @param isBuy True if it was a buy, false if sell
    /// @param amountIn The input amount used
    /// @param amountOut The output amount received
    /// @return selector The function selector to confirm execution (bytes4)
    function afterSwap(
        address pool,
        address sender,
        bool isBuy,
        uint256 amountIn,
        uint256 amountOut
    ) external returns (bytes4);

    /// @notice Called before fee distribution occurs.
    /// @param pool The pool address
    /// @param feeAmount The fee amount about to be distributed
    /// @return adjustedFee The adjusted fee amount after optical processing
    function beforeFeeDistribution(
        address pool,
        uint256 feeAmount
    ) external returns (uint256 adjustedFee);

    /// @notice Called after fee distribution occurs.
    /// @param pool The pool address
    /// @param feeAmount The fee amount that was distributed
    /// @return selector The function selector to confirm execution (bytes4)
    function afterFeeDistribution(
        address pool,
        uint256 feeAmount
    ) external returns (bytes4);

    /// @notice Returns a bitmap of active hooks for this optical.
    /// @dev Bit 0: beforeSwap, Bit 1: afterSwap,
    ///      Bit 2: beforeFeeDistribution, Bit 3: afterFeeDistribution
    ///      Pool checks this to skip unused callbacks (gas optimization).
    /// @return flags The active hook flags bitmap
    function getFlags() external view returns (uint8 flags);
}

contracts/opticals/LaunchpadOpticalFacto.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/IFeeAccumulator.sol";
import "./presets/LaunchpadOptical.sol";

/// @title LaunchpadOpticalFactory
/// @notice Self-service factory for deploying LaunchpadOptical instances.
///         Any creator can deploy their own vesting + capital-raise optical for their pool.
/// @dev UUPS proxy. Deploys immutable LaunchpadOptical contracts and auto-grants
///      OPTICAL_CLAIM_ROLE on FeeAccumulator so the new optical can claim surplus.
contract LaunchpadOpticalFactory is Initializable, UUPSUpgradeable, AccessControl {
    // ============ ERRORS ============

    error ZeroAddress();
    error ArrayTooLong();

    // ============ EVENTS ============

    event LaunchpadOpticalCreated(
        address indexed optical,
        address indexed creator,
        address teamClaimAddress,
        uint256 cliffDuration,
        uint256 vestingDuration,
        uint256 capitalRaiseBps,
        uint256 capitalRaiseDuration
    );

    // ============ STATE ============

    /// @notice PoolRegistry address (passed to each LaunchpadOptical)
    address public poolRegistry;

    /// @notice FeeAccumulator address (passed to each LaunchpadOptical + role granting)
    address public feeAccumulator;

    /// @notice OpticalRegistry for optional auto-registration
    address public opticalRegistry;

    /// @notice All deployed LaunchpadOptical instances
    address[] private _deployedOpticals;

    /// @notice Creator → their deployed opticals
    mapping(address => address[]) private _creatorOpticals;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _poolRegistry,
        address _feeAccumulator,
        address _opticalRegistry,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        if (_feeAccumulator == address(0)) revert ZeroAddress();

        poolRegistry = _poolRegistry;
        feeAccumulator = _feeAccumulator;
        opticalRegistry = _opticalRegistry;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    /// @notice Deploy a new LaunchpadOptical for a project
    /// @param teamWallets Additional team wallets to vest (creator is auto-vested)
    /// @param cliffDuration Hard lock period in seconds
    /// @param vestingDuration Linear unlock period after cliff in seconds
    /// @param capitalRaiseBps Fee percentage diverted to team (max 1000 = 10%)
    /// @param capitalRaiseDuration How long the capital raise fee is active in seconds
    /// @param teamClaimAddress Where accumulated USDL is claimed to
    /// @return optical The address of the newly deployed LaunchpadOptical
    function createLaunchpadOptical(
        address[] calldata teamWallets,
        uint256 cliffDuration,
        uint256 vestingDuration,
        uint256 capitalRaiseBps,
        uint256 capitalRaiseDuration,
        address teamClaimAddress
    ) external returns (address optical) {
        if (teamClaimAddress == address(0)) revert ZeroAddress();

        // Deploy new LaunchpadOptical (immutable, caller is the creator)
        LaunchpadOptical instance = new LaunchpadOptical(
            poolRegistry,
            msg.sender,         // owner
            msg.sender,         // creator (auto-vested)
            teamWallets,
            cliffDuration,
            vestingDuration,
            capitalRaiseBps,
            capitalRaiseDuration,
            teamClaimAddress,
            feeAccumulator
        );

        optical = address(instance);

        // Grant OPTICAL_CLAIM_ROLE on FeeAccumulator so the optical can claim surplus
        IFeeAccumulator(feeAccumulator).authorizeOptical(optical);

        // Track deployment
        _deployedOpticals.push(optical);
        _creatorOpticals[msg.sender].push(optical);

        emit LaunchpadOpticalCreated(
            optical,
            msg.sender,
            teamClaimAddress,
            cliffDuration,
            vestingDuration,
            capitalRaiseBps,
            capitalRaiseDuration
        );
    }

    // ============ VIEWS ============

    /// @notice Get all LaunchpadOpticals deployed by a specific creator
    function getOpticalsByCreator(address creator) external view returns (address[] memory) {
        return _creatorOpticals[creator];
    }

    /// @notice Get total number of deployed LaunchpadOpticals
    function getDeployedCount() external view returns (uint256) {
        return _deployedOpticals.length;
    }

    /// @notice Get paginated list of all deployed opticals
    function getAllOpticals(uint256 offset, uint256 limit) external view returns (address[] memory) {
        uint256 total = _deployedOpticals.length;
        if (offset >= total) return new address[](0);

        uint256 end = offset + (limit > total - offset ? total - offset : limit);

        uint256 len = end - offset;
        address[] memory result = new address[](len);
        for (uint256 i = 0; i < len; i++) {
            result[i] = _deployedOpticals[offset + i];
        }
        return result;
    }

    // ============ INTERNAL ============

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/opticals/OpticalRegistry.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/IEventEmitter.sol";

/// @title OpticalRegistry
/// @notice Trust-signaling registry for optical plugins.
/// @dev UUPS proxy. Opticals do NOT require registration to function —
///      but unregistered opticals show as "unverified" to users/frontends.
///      Admin registers/deregisters opticals with metadata.
contract OpticalRegistry is Initializable, UUPSUpgradeable, AccessControl {
    error ZeroAddress();
    error AlreadyRegistered();
    error NotRegistered();

    struct OpticalMetadata {
        string name;
        string description;
        uint8 riskLevel;     // 1-5 scale
        string auditor;      // auditor name or "unaudited"
        uint256 registeredAt;
    }

    event OpticalRegistered(address indexed optical, string name, uint8 riskLevel, uint256 timestamp);
    event OpticalDeregistered(address indexed optical, uint256 timestamp);
    event OpticalMetadataUpdated(address indexed optical, uint256 timestamp);

    mapping(address => bool) private _approved;
    mapping(address => OpticalMetadata) private _metadata;
    address[] private _allOpticals;

    address public eventEmitter;
    mapping(address => bool) private _everSeen;
    mapping(address => bytes32) public approvedCodeHash;
    error InvalidOptical();
    bool public indexInitialized;
    uint256 public indexMigrationCursor;
    uint256 public indexMigrationWritten;

    struct IdentityReview {
        bool initialized;
        uint8 flags;
        uint256 reviewedAt;
        bytes32 evidenceDigest;
    }
    // Appended storage: populated proxies require explicit review renewal.
    mapping(address => IdentityReview) public identityReviews;
    event OpticalIdentityReviewed(address indexed optical, bytes32 codeHash, uint8 flags, bytes32 evidenceDigest, uint256 reviewedAt);
    error ReviewIdentityMismatch();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address _eventEmitter, address _admin) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        eventEmitter = _eventEmitter;
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        indexInitialized = true;
    }

    /// @notice Register an optical as approved with metadata
    /// @param optical The optical contract address
    /// @param name Human-readable name
    /// @param description Description of the optical's behavior
    /// @param riskLevel Risk level 1-5 (1 = lowest)
    /// @param auditor Auditor name or "unaudited"
    function registerOptical(
        address optical,
        string calldata name,
        string calldata description,
        uint8 riskLevel,
        string calldata auditor
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!indexInitialized) revert InvalidOptical();
        if (optical == address(0)) revert ZeroAddress();
        uint8 flags = _validate(optical, riskLevel);
        if (_approved[optical]) revert AlreadyRegistered();

        _approved[optical] = true;
        _metadata[optical] = OpticalMetadata({
            name: name,
            description: description,
            riskLevel: riskLevel,
            auditor: auditor,
            registeredAt: block.timestamp
        });
        if (!_everSeen[optical]) {
            _everSeen[optical] = true;
            _allOpticals.push(optical);
        }
        _recordReview(optical, optical.codehash, flags, bytes32(0));

        emit OpticalRegistered(optical, name, riskLevel, block.timestamp);
    }

    /// @notice Deregister an optical (mark as not approved)
    /// @param optical The optical contract address to deregister
    function deregisterOptical(address optical) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!_approved[optical]) revert NotRegistered();
        _approved[optical] = false;

        emit OpticalDeregistered(optical, block.timestamp);
    }

    /// @notice Update metadata for a registered optical
    function updateMetadata(
        address optical,
        string calldata name,
        string calldata description,
        uint8 riskLevel,
        string calldata auditor
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!_approved[optical]) revert NotRegistered();
        if (riskLevel < 1 || riskLevel > 5) revert InvalidOptical();

        _metadata[optical] = OpticalMetadata({
            name: name,
            description: description,
            riskLevel: riskLevel,
            auditor: auditor,
            registeredAt: _metadata[optical].registeredAt
        });

        emit OpticalMetadataUpdated(optical, block.timestamp);
    }

    /// @notice Check if an optical is registered and approved
    function isRegistered(address optical) external view returns (bool) {
        return _isReviewed(optical);
    }

    /// @notice Compatibility probe used by EventEmitter dynamic optical authorization.
    function isApproved(address optical) external view returns (bool) {
        return _isReviewed(optical);
    }

    /// @notice Get metadata for an optical
    function getOpticalMetadata(address optical) external view returns (OpticalMetadata memory) {
        return _metadata[optical];
    }

    /// @notice Get all registered opticals (paginated)
    function getAllOpticals(uint256 offset, uint256 limit) external view returns (address[] memory) {
        uint256 total = _allOpticals.length;
        if (offset >= total) {
            return new address[](0);
        }

        uint256 end = offset + (limit > total - offset ? total - offset : limit);

        uint256 resultLength = end - offset;
        address[] memory result = new address[](resultLength);
        for (uint256 i = 0; i < resultLength; i++) {
            result[i] = _allOpticals[offset + i];
        }
        return result;
    }

    /// @notice Get total count of ever-registered opticals
    function getOpticalCount() external view returns (uint256) {
        return _allOpticals.length;
    }

    /// @notice Upgrade-only bounded reconciliation of historical duplicate list entries.
    /// @dev Existing approval identity must be explicitly renewed through renewReview after review.
    function migrateIndex(uint256 limit) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (indexInitialized || limit == 0) revert InvalidOptical();
        uint256 cursor = indexMigrationCursor;
        uint256 end = cursor + (limit > _allOpticals.length - cursor ? _allOpticals.length - cursor : limit);
        uint256 written = indexMigrationWritten;
        for (; cursor < end; ++cursor) {
            address optical = _allOpticals[cursor];
            if (!_everSeen[optical]) {
                _everSeen[optical] = true;
                _allOpticals[written++] = optical;
            }
        }
        indexMigrationCursor = cursor;
        indexMigrationWritten = written;
        if (cursor == _allOpticals.length) {
            // Shorten only the logical list; future pushes overwrite abandoned duplicate slots.
            assembly { sstore(_allOpticals.slot, written) }
            indexInitialized = true;
        }
    }

    /// @notice Explicitly renew reviewed runtime identity after independent review.
    /// @dev Digest commits to external review evidence, including proxy implementation
    ///      identity when applicable. Runtime codehash cannot detect arbitrary proxy upgrades.
    function renewReview(address optical, bytes32 expectedCodeHash, uint8 expectedFlags, bytes32 evidenceDigest)
        external onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (!_approved[optical]) revert NotRegistered();
        if (evidenceDigest == bytes32(0)) revert InvalidOptical();
        (bool valid, uint8 flags) = _readFlags(optical);
        if (!valid || optical.codehash != expectedCodeHash || flags != expectedFlags) revert ReviewIdentityMismatch();
        _recordReview(optical, expectedCodeHash, flags, evidenceDigest);
    }

    function _recordReview(address optical, bytes32 codeHash, uint8 flags, bytes32 evidenceDigest) internal {
        approvedCodeHash[optical] = codeHash;
        identityReviews[optical] = IdentityReview(true, flags, block.timestamp, evidenceDigest);
        emit OpticalIdentityReviewed(optical, codeHash, flags, evidenceDigest, block.timestamp);
    }

    function _isReviewed(address optical) internal view returns (bool) {
        IdentityReview storage review = identityReviews[optical];
        if (!_approved[optical] || !review.initialized || approvedCodeHash[optical] != optical.codehash) return false;
        (bool valid, uint8 flags) = _readFlags(optical);
        return valid && flags == review.flags;
    }

    /// @dev Fixed gas and output copy bound hostile probes, including return-data bombs.
    ///      All built-in immutable opticals expose a cheap getFlags getter.
    function _readFlags(address optical) internal view returns (bool valid, uint8 flags) {
        if (optical.code.length == 0) return (false, 0);
        bytes4 selector = bytes4(keccak256("getFlags()"));
        uint256 value;
        bool success;
        uint256 size;
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, selector)
            success := staticcall(30000, optical, ptr, 4, ptr, 32)
            size := returndatasize()
            value := mload(ptr)
        }
        valid = success && size == 32 && value <= 31;
        flags = valid ? uint8(value) : 0;
    }

    function _validate(address optical, uint8 riskLevel) internal view returns (uint8 flags) {
        bool valid;
        (valid, flags) = _readFlags(optical);
        if (!valid || riskLevel < 1 || riskLevel > 5) revert InvalidOptical();
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/opticals/presets/AntiSnipeOpti.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../BaseOptical.sol";
import "../../libraries/BitFlag.sol";

/// @title AntiSnipeOptical
/// @notice Blocks buys exceeding maxBuyBps of effective USDL reserves in the first N blocks after pool creation.
/// @dev Uses beforeSwap hook only. Immutable once deployed.
///      After the protection period, all buys are allowed regardless of size.
///      Sells are never affected by this optical.
contract AntiSnipeOptical is BaseOptical {
    error ProtectionActive();

    /// @notice Maximum buy percentage in basis points (e.g., 100 = 1%)
    uint256 public immutable maxBuyBps;

    /// @notice Number of blocks after pool creation during which protection is active
    uint256 public immutable protectionBlocks;

    /// @notice Mapping of pool address to the block number at which it was created
    mapping(address => uint256) public poolCreationBlock;

    /// @param _poolRegistry PoolRegistry address for pool validation
    /// @param _owner Deployer/owner address
    /// @param _maxBuyBps Maximum buy size in bps of token supply (e.g., 100 = 1%)
    /// @param _protectionBlocks Number of blocks the protection lasts
    constructor(
        address _poolRegistry,
        address _owner,
        uint256 _maxBuyBps,
        uint256 _protectionBlocks
    ) BaseOptical(_poolRegistry, _owner) {
        require(_maxBuyBps > 0 && _maxBuyBps <= 10000, "Invalid cap");
        maxBuyBps = _maxBuyBps;
        protectionBlocks = _protectionBlocks;
    }

    /// @notice Register a pool's creation block (called once when pool is created)
    /// @dev Anyone can call this, but it only records the first time for each pool
    function registerPool(address pool) external {
        if (poolCreationBlock[pool] == 0) {
            poolCreationBlock[pool] = _poolMetadata(pool).createdBlock;
        }
    }

    /// @inheritdoc IOptical
    function getFlags() external pure override returns (uint8) {
        return BitFlag.BEFORE_SWAP;
    }

    /// @inheritdoc IOptical
    function beforeSwap(
        address pool,
        address, /* sender */
        bool isBuy,
        uint256 amountIn
    ) external override onlyAttachedPool(pool) returns (bool proceed, int256 amountDelta) {
        // Sells are never affected
        if (!isBuy) {
            return (true, 0);
        }

        // If pool not registered or protection period expired, allow
        uint256 creationBlock = _poolMetadata(pool).createdBlock;
        if (creationBlock == 0 || block.number > creationBlock + protectionBlocks) {
            return (true, 0);
        }

        // During protection: check buy size against max allowed
        // We read the token reserve from the pool to calculate max buy amount in USDL terms
        (uint256 virtualUsdl, uint256 realUsdl, uint256 tokenRes) = _getPoolReserves(pool);
        if (tokenRes == 0) {
            return (true, 0);
        }

        // Max buy is maxBuyBps of the effective USDL reserve
        // This limits how much USDL can be used in a single buy

        uint256 effectiveUsdl = virtualUsdl + realUsdl;
        uint256 maxBuyAmount = (effectiveUsdl * maxBuyBps) / 10000;

        if (amountIn > maxBuyAmount) {
            return (false, 0);
        }

        return (true, 0);
    }
}

contracts/opticals/presets/BuybackBurnOp.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../BaseOptical.sol";
import "../../libraries/BitFlag.sol";
import "../../libraries/TransferHelper.sol";
import "../../interfaces/IFeeAccumulator.sol";
import "../../interfaces/ISidioraPool.sol";

/// @title BuybackBurnOptical
/// @notice Redirects a configurable portion of fee distributions to buy back tokens and burn them.
/// @dev Uses beforeFeeDistribution hook to redirect a percentage of fees.
///      The redirected USDL is accumulated and can be used to execute buyback+burn via
///      an external trigger. Immutable once deployed.
///
///      Flow: beforeFeeDistribution reduces the fee by buybackBps%, accumulating the
///      redirected portion. The owner can call executeBuybackBurn() to send the accumulated
///      USDL to the pool, execute a real swap, and retire output at the dead address.
contract BuybackBurnOptical is BaseOptical {
    error NothingToExecute();

    /// @notice Dead address for burning tokens
    address public constant DEAD_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    /// @notice Percentage of fees redirected to buyback+burn (in bps, e.g., 2000 = 20%)
    uint256 public immutable buybackBps;

    /// @notice Accumulated USDL per pool for buyback execution
    mapping(address => uint256) public accumulatedUsdl;

    event BuybackAccumulated(address indexed pool, uint256 amount);
    event BuybackExecuted(address indexed pool, uint256 usdlUsed);

    /// @param _poolRegistry PoolRegistry address for pool validation
    /// @param _owner Deployer/owner address
    /// @param _buybackBps Percentage of fees to redirect (in bps, max 5000 = 50%)
    constructor(
        address _poolRegistry,
        address _owner,
        uint256 _buybackBps
    ) BaseOptical(_poolRegistry, _owner) {
        require(_owner != address(0), "Zero owner");
        require(_buybackBps <= 5000, "Max 50%");
        buybackBps = _buybackBps;
    }

    /// @inheritdoc IOptical
    function getFlags() external pure override returns (uint8) {
        return BitFlag.BEFORE_FEE_DISTRIBUTION;
    }

    /// @inheritdoc IOptical
    function beforeFeeDistribution(
        address pool,
        uint256 feeAmount
    ) external override onlyFeeAccumulator(pool) returns (uint256 adjustedFee) {
        if (buybackBps == 0) {
            return feeAmount;
        }

        uint256 buybackAmount = (feeAmount * buybackBps) / 10000;
        if (buybackAmount > 0) {
            accumulatedUsdl[pool] += buybackAmount;
            emit BuybackAccumulated(pool, buybackAmount);
        }

        return feeAmount - buybackAmount;
    }

    /// @notice Get the accumulated USDL available for buyback for a pool
    function getAccumulatedUsdl(address pool) external view returns (uint256) {
        return accumulatedUsdl[pool];
    }

    /// @notice Owner executes funded surplus buyback with an explicit minimum and deadline.
    /// @dev Trusted execution policy: spot reserves cannot provide a manipulation-resistant minimum.
    function executeBuybackBurn(address pool, uint256 minTokensOut, uint256 deadline)
        external onlyOwner returns (uint256 tokensBurned)
    {
        _poolMetadata(pool);
        require(minTokensOut > 0, "Slippage required");
        uint256 amount = accumulatedUsdl[pool];
        if (amount == 0) revert NothingToExecute();
        accumulatedUsdl[pool] = 0;
        (bool ok, bytes memory data) = pool.staticcall(abi.encodeWithSignature("feeAccumulator()"));
        require(ok && data.length == 32, "Invalid accumulator");
        address accumulator = abi.decode(data, (address));
        (ok, data) = accumulator.staticcall(abi.encodeWithSignature("usdlAddress()"));
        require(ok && data.length == 32, "Invalid USDL");
        address usdl = abi.decode(data, (address));
        IFeeAccumulator(accumulator).claimOpticalSurplus(pool, amount, address(this));
        TransferHelper.safeTransfer(usdl, pool, amount);
        tokensBurned = ISidioraPool(pool).swap(amount, minTokensOut, true, DEAD_ADDRESS, deadline);
        emit BuybackExecuted(pool, amount);
    }
}

contracts/opticals/presets/CooldownOptic.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../BaseOptical.sol";
import "../../libraries/BitFlag.sol";

/// @title CooldownOptical
/// @notice Enforces minimum time between trades per wallet (anti-bot).
/// @dev Uses beforeSwap hook. Tracks last trade timestamp per pool per wallet.
///      Configurable cooldown period. Independent per wallet.
///      Immutable once deployed.
contract CooldownOptical is BaseOptical {
    error CooldownActive();

    /// @notice Minimum seconds between trades for any given wallet
    uint256 public immutable cooldownSeconds;

    /// @notice Last trade timestamp per pool per wallet: pool => wallet => timestamp
    mapping(address => mapping(address => uint256)) public lastTradeTime;

    /// @param _poolRegistry PoolRegistry address for pool validation
    /// @param _owner Deployer/owner address
    /// @param _cooldownSeconds Minimum seconds between trades per wallet
    constructor(
        address _poolRegistry,
        address _owner,
        uint256 _cooldownSeconds
    ) BaseOptical(_poolRegistry, _owner) {
        cooldownSeconds = _cooldownSeconds;
    }

    /// @inheritdoc IOptical
    function getFlags() external pure override returns (uint8) {
        return BitFlag.BEFORE_SWAP;
    }

    /// @inheritdoc IOptical
    function beforeSwap(
        address pool,
        address sender,
        bool, /* isBuy */
        uint256 /* amountIn */
    ) external override onlyAttachedPool(pool) returns (bool proceed, int256 amountDelta) {
        uint256 lastTrade = lastTradeTime[pool][sender];

        if (lastTrade != 0 && block.timestamp < lastTrade + cooldownSeconds) {
            return (false, 0);
        }

        // Record this trade time
        lastTradeTime[pool][sender] = block.timestamp;

        return (true, 0);
    }
}

contracts/opticals/presets/LaunchpadOpti.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../BaseOptical.sol";
import "../../libraries/BitFlag.sol";
import "../../interfaces/IFeeAccumulator.sol";

/// @title LaunchpadOptical
/// @notice Preset optical for serious projects: cliff + linear vesting for team wallets,
///         plus a time-limited capital raise fee that diverts a portion of swap fees to the team as USDL.
/// @dev Immutable once deployed. One instance per pool (constructor params are pool-specific).
///
///      HOOKS USED:
///        - beforeTokenTransfer:    Enforce cliff lock + linear vesting on all team transfers
///        - beforeSwap/afterSwap:   Authenticated lifecycle hooks; no duplicate transfer accounting
///        - beforeFeeDistribution:  Divert capitalRaiseBps of pool fees to optical surplus for team
///
///      CAPITAL RAISE FLOW:
///        1. beforeFeeDistribution reduces the pool fee by capitalRaiseBps%
///        2. FeeAccumulator records the difference as opticalSurplus
///        3. Team calls claimCapital() → LaunchpadOptical calls FeeAccumulator.claimOpticalSurplus()
///        4. USDL is transferred to teamClaimAddress
contract LaunchpadOptical is BaseOptical {
    // ============ ERRORS ============

    error CliffActive();
    error VestingExceeded();
    error CapitalRaiseTooHigh();
    error DurationTooLong();
    error NoTeamWallets();
    error TooManyTeamWallets();
    error NothingToClaim();
    error NotTeam();

    // ============ EVENTS ============

    event PoolStartTimeRecorded(address indexed pool, uint256 startTime);
    event SellBlockedCliff(address indexed pool, address indexed sender, uint256 amountIn);
    event SellBlockedVesting(address indexed pool, address indexed sender, uint256 amountIn, uint256 maxSellable);
    event CapitalRaiseAccumulated(address indexed pool, uint256 amount, uint256 totalRaisedAmount);
    event CapitalRaiseClaimed(address indexed pool, uint256 amount, address indexed recipient);

    // ============ CONSTANTS ============

    uint256 public constant MAX_CAPITAL_RAISE_BPS = 1000; // 10%
    uint256 public constant MAX_CLIFF_DURATION = 365 days;
    uint256 public constant MAX_VESTING_DURATION = 1095 days; // 3 years
    uint256 public constant MAX_RAISE_DURATION = 365 days;
    uint256 public constant MAX_TEAM_WALLETS = 20;

    // ============ IMMUTABLES ============

    /// @notice Pool creator wallet (auto-vested)
    address public immutable creator;

    /// @notice Address where accumulated USDL capital is claimed to
    address public immutable teamClaimAddress;

    /// @notice FeeAccumulator address for claiming optical surplus
    address public immutable feeAccumulator;

    /// @notice Hard lock period in seconds before any vesting begins
    uint256 public immutable cliffDuration;

    /// @notice Linear unlock period in seconds after the cliff
    uint256 public immutable vestingDuration;

    /// @notice Fee percentage diverted to team (in bps, max 1000 = 10%)
    uint256 public immutable capitalRaiseBps;

    /// @notice How long the capital raise fee is active (in seconds)
    uint256 public immutable capitalRaiseDuration;

    /// @notice Number of team wallets (excluding creator)
    uint256 public immutable teamWalletCount;

    // ============ STORAGE ============

    /// @notice Whether an address is subject to vesting restrictions
    mapping(address => bool) public isVested;

    /// @notice Authoritative registry creation timestamp, cached on authenticated interaction
    mapping(address => uint256) public poolStartTime;

    /// @notice Cumulative tokens released by each vested wallet per pool (all transfers)
    /// @dev pool → wallet → amount sold
    mapping(address => mapping(address => uint256)) public tokensSold;

    /// @notice USDL accumulated per pool for team capital raise (accounting only)
    mapping(address => uint256) public accumulatedUsdl;

    /// @notice Lifetime total USDL raised per pool
    mapping(address => uint256) public totalRaised;

    // ============ CONSTRUCTOR ============

    /// @param _poolRegistry PoolRegistry address for pool validation
    /// @param _owner Deployer/owner address
    /// @param _creator Pool creator wallet (auto-vested)
    /// @param _teamWallets Additional team wallets to vest
    /// @param _cliffDuration Hard lock period in seconds
    /// @param _vestingDuration Linear unlock period after cliff in seconds
    /// @param _capitalRaiseBps Fee percentage diverted to team (max 1000 = 10%)
    /// @param _capitalRaiseDuration How long the capital raise fee is active in seconds
    /// @param _teamClaimAddress Where accumulated USDL is claimed to
    /// @param _feeAccumulator FeeAccumulator contract address
    constructor(
        address _poolRegistry,
        address _owner,
        address _creator,
        address[] memory _teamWallets,
        uint256 _cliffDuration,
        uint256 _vestingDuration,
        uint256 _capitalRaiseBps,
        uint256 _capitalRaiseDuration,
        address _teamClaimAddress,
        address _feeAccumulator
    ) BaseOptical(_poolRegistry, _owner) {
        if (_creator == address(0)) revert NotPool();
        if (_teamClaimAddress == address(0)) revert NotPool();
        if (_feeAccumulator == address(0)) revert NotPool();
        if (_capitalRaiseBps > MAX_CAPITAL_RAISE_BPS) revert CapitalRaiseTooHigh();
        if (_cliffDuration > MAX_CLIFF_DURATION) revert DurationTooLong();
        if (_vestingDuration > MAX_VESTING_DURATION) revert DurationTooLong();
        if (_capitalRaiseDuration > MAX_RAISE_DURATION) revert DurationTooLong();
        if (_teamWallets.length > MAX_TEAM_WALLETS) revert TooManyTeamWallets();

        creator = _creator;
        teamClaimAddress = _teamClaimAddress;
        feeAccumulator = _feeAccumulator;
        cliffDuration = _cliffDuration;
        vestingDuration = _vestingDuration;
        capitalRaiseBps = _capitalRaiseBps;
        capitalRaiseDuration = _capitalRaiseDuration;
        teamWalletCount = _teamWallets.length;

        // Mark creator as vested
        isVested[_creator] = true;

        // Mark all team wallets as vested
        for (uint256 i = 0; i < _teamWallets.length; i++) {
            if (_teamWallets[i] != address(0)) {
                isVested[_teamWallets[i]] = true;
            }
        }
    }

    // ============ HOOK FLAGS ============

    /// @inheritdoc IOptical
    function getFlags() external pure override returns (uint8) {
        // Swap callbacks + fee diversion + transfer-wide vesting.
        return BitFlag.BEFORE_SWAP | BitFlag.AFTER_SWAP | BitFlag.BEFORE_FEE_DISTRIBUTION | BitFlag.BEFORE_TOKEN_TRANSFER;
    }

    // ============ BEFORE SWAP — VESTING ENFORCEMENT ============

    /// @inheritdoc IOptical
    function beforeSwap(
        address pool,
        address sender,
        bool isBuy,
        uint256 amountIn
    ) external override onlyAttachedPool(pool) returns (bool proceed, int256 amountDelta) {
        // Transfer policy validates and accounts releases before token balances change.
        // A sell's transfer has already consumed its allowance; never count it twice.
        _recordStart(pool);
        sender; isBuy; amountIn;
        return (true, 0);
    }

    function afterSwap(address pool, address, bool, uint256, uint256)
        external override onlyAttachedPool(pool) returns (bytes4)
    {
        return IOptical.afterSwap.selector;
    }

    /// @notice Token-level restriction covers sells, transfers, and delegated transfers.
    function beforeTokenTransfer(address pool, address from, address to, uint256 amount) external {
        IPoolRegistry.PoolMetadata memory meta = _poolMetadata(pool);
        if (msg.sender != meta.token) revert NotPool();
        uint256 start = _recordStart(pool);
        if (from == address(0) || from == to || !isVested[from] || amount == 0) return;
        uint256 elapsed = block.timestamp - start;
        if (elapsed < cliffDuration) revert CliffActive();
        uint256 sold = tokensSold[pool][from];
        if (elapsed < cliffDuration + vestingDuration) {
            uint256 allocation = _getTokenBalance(pool, from) + sold;
            uint256 vested = allocation * (elapsed - cliffDuration) / vestingDuration;
            if (sold + amount > vested) revert VestingExceeded();
        }
        tokensSold[pool][from] = sold + amount;
    }

    function _recordStart(address pool) internal returns (uint256 start) {
        IPoolRegistry.PoolMetadata memory meta = _poolMetadata(pool);
        if (meta.creator != creator) revert NotTeam();
        start = meta.createdAt;
        if (poolStartTime[pool] == 0) {
            poolStartTime[pool] = start;
            emit PoolStartTimeRecorded(pool, start);
        }
    }

    // ============ BEFORE FEE DISTRIBUTION — CAPITAL RAISE ============

    /// @inheritdoc IOptical
    function beforeFeeDistribution(
        address pool,
        uint256 feeAmount
    ) external override onlyFeeAccumulator(pool) returns (uint256 adjustedFee) {
        if (capitalRaiseBps == 0) {
            return feeAmount;
        }

        uint256 startTime = _recordStart(pool);
        if (startTime == 0) {
            return feeAmount;
        }

        uint256 elapsed = block.timestamp - startTime;
        if (elapsed >= capitalRaiseDuration) {
            return feeAmount;
        }

        // Divert capitalRaiseBps of the fee to team
        uint256 raiseAmount = (feeAmount * capitalRaiseBps) / 10000;
        if (raiseAmount == 0) {
            return feeAmount;
        }

        accumulatedUsdl[pool] += raiseAmount;
        totalRaised[pool] += raiseAmount;

        emit CapitalRaiseAccumulated(pool, raiseAmount, totalRaised[pool]);

        return feeAmount - raiseAmount;
    }

    // ============ CAPITAL CLAIM ============

    /// @notice Claim accumulated USDL capital for a pool
    /// @param pool The pool address to claim capital from
    function claimCapital(address pool) external {
        if (msg.sender != teamClaimAddress) revert NotTeam();
        uint256 amount = accumulatedUsdl[pool];
        if (amount == 0) revert NothingToClaim();

        accumulatedUsdl[pool] = 0;
        IFeeAccumulator(feeAccumulator).claimOpticalSurplus(pool, amount, teamClaimAddress);

        emit CapitalRaiseClaimed(pool, amount, teamClaimAddress);
    }

    // ============ VIEW FUNCTIONS ============

    /// @notice Get vesting info for a wallet in a specific pool
    function getVestingInfo(address pool, address wallet) external view returns (
        bool vested,
        uint256 cliffEnd,
        uint256 vestEnd,
        uint256 vestedAmount,
        uint256 sold,
        uint256 maxSellableNow
    ) {
        vested = isVested[wallet];
        uint256 startTime = _poolMetadata(pool).createdAt;

        if (startTime == 0 || !vested) {
            return (vested, 0, 0, 0, 0, 0);
        }

        cliffEnd = startTime + cliffDuration;
        vestEnd = startTime + cliffDuration + vestingDuration;
        sold = tokensSold[pool][wallet];

        uint256 elapsed = block.timestamp - startTime;

        if (elapsed < cliffDuration) {
            // Still in cliff — nothing vested
            return (vested, cliffEnd, vestEnd, 0, sold, 0);
        }

        uint256 currentBalance = _getTokenBalance(pool, wallet);
        uint256 originalAllocation = currentBalance + sold;

        if (elapsed >= cliffDuration + vestingDuration) {
            // Fully vested
            vestedAmount = originalAllocation;
            maxSellableNow = currentBalance;
        } else {
            // Linear vesting
            uint256 vestedFraction = ((elapsed - cliffDuration) * 1e18) / vestingDuration;
            vestedAmount = (originalAllocation * vestedFraction) / 1e18;
            if (vestedAmount > sold) {
                maxSellableNow = vestedAmount - sold;
            }
        }
    }

    /// @notice Get capital raise info for a pool
    function getCapitalRaiseInfo(address pool) external view returns (
        uint256 accumulated,
        uint256 totalRaisedAmount,
        uint256 raiseEndTime,
        bool isActive
    ) {
        accumulated = accumulatedUsdl[pool];
        totalRaisedAmount = totalRaised[pool];
        uint256 startTime = _poolMetadata(pool).createdAt;

        if (startTime > 0) {
            raiseEndTime = startTime + capitalRaiseDuration;
            isActive = block.timestamp < raiseEndTime && capitalRaiseBps > 0;
        }
    }

    /// @notice Check if an address is a team wallet (vested)
    function isTeamWallet(address wallet) external view returns (bool) {
        return isVested[wallet];
    }

    // ============ INTERNAL ============

    /// @dev Read token balance of a wallet via the pool's token address
    function _getTokenBalance(address pool, address wallet) internal view returns (uint256) {
        // Read tokenAddress from the pool
        (bool success, bytes memory data) = pool.staticcall(
            abi.encodeWithSignature("tokenAddress()")
        );
        if (!success || data.length < 32) revert NotPool();
        address token = abi.decode(data, (address));

        // Read balance
        (bool success2, bytes memory data2) = token.staticcall(
            abi.encodeWithSignature("balanceOf(address)", wallet)
        );
        if (!success2 || data2.length < 32) revert NotPool();
        return abi.decode(data2, (uint256));
    }
}

