// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../BaseOptical.sol";
import "../../libraries/BitFlag.sol";

/// @title MaxWalletOptical
/// @notice Enforces maximum token holding percentage per wallet after buy swaps.
/// @dev Uses the token transfer callback for pool outputs. Bytecode and cap immutable; owner may change exemptions.
///      Pool address is exempt (it holds the liquidity).
///      Only checks on buys — sells naturally reduce holdings.
contract MaxWalletOptical is BaseOptical {
    error MaxWalletExceeded();
    event ExemptionUpdated(address indexed account, bool isExempt);

    /// @notice Maximum wallet holding in basis points of total supply (e.g., 200 = 2%)
    uint256 public immutable maxWalletBps;

    /// @notice Addresses exempt from max wallet check
    mapping(address => bool) public exempt;

    /// @param _poolRegistry PoolRegistry address for pool validation
    /// @param _owner Deployer/owner address
    /// @param _maxWalletBps Maximum holding in bps of total supply
    constructor(
        address _poolRegistry,
        address _owner,
        uint256 _maxWalletBps
    ) BaseOptical(_poolRegistry, _owner) {
        require(_maxWalletBps > 0 && _maxWalletBps <= 10000, "Invalid cap");
        maxWalletBps = _maxWalletBps;
    }

    /// @notice Set an address as exempt from max wallet check
    /// @dev Only owner can set exemptions (e.g., pool address, treasury)
    function setExempt(address account, bool isExempt) external onlyOwner {
        exempt[account] = isExempt;
        emit ExemptionUpdated(account, isExempt);
    }

    /// @inheritdoc IOptical
    function getFlags() external pure override returns (uint8) {
        return BitFlag.BEFORE_TOKEN_TRANSFER;
    }

    /// @notice Buy-time cap: validate actual pool output recipient before the token balance changes.
    function beforeTokenTransfer(address pool, address from, address to, uint256 amount) external view {
        IPoolRegistry.PoolMetadata memory meta = _poolMetadata(pool);
        if (msg.sender != meta.token) revert NotPool();
        if (from != pool || to == pool || exempt[to]) return;
        (bool ok, bytes memory data) = meta.token.staticcall(abi.encodeWithSignature("balanceOf(address)", to));
        if (!ok || data.length != 32) revert NotPool();
        uint256 balance = abi.decode(data, (uint256));
        (ok, data) = meta.token.staticcall(abi.encodeWithSignature("totalSupply()"));
        if (!ok || data.length != 32) revert NotPool();
        uint256 cap = abi.decode(data, (uint256)) * maxWalletBps / 10000;
        if (balance + amount > cap) revert MaxWalletExceeded();
    }
}

contracts/opticals/presets/TaxOptical.so.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../BaseOptical.sol";
import "../../libraries/BitFlag.sol";

/// @title TaxOptical
/// @notice Applies additional configurable buy/sell tax via beforeSwap amountDelta.
/// @dev Uses beforeSwap hook. Tax is taken by reducing the effective amountIn
///      (negative amountDelta). The taxed portion remains in the pool, effectively
///      benefiting liquidity. Configurable separate buy/sell rates, capped at 10%.
///      Immutable once deployed — rates are set at construction.
contract TaxOptical is BaseOptical {
    error TaxTooHigh();

    /// @notice Maximum allowed tax in basis points (1000 = 10%)
    uint256 public constant MAX_TAX_BPS = 1000;

    /// @notice Buy tax in basis points (e.g., 100 = 1%)
    uint256 public immutable buyTaxBps;

    /// @notice Sell tax in basis points (e.g., 100 = 1%)
    uint256 public immutable sellTaxBps;

    /// @param _poolRegistry PoolRegistry address for pool validation
    /// @param _owner Deployer/owner address
    /// @param _buyTaxBps Buy tax in basis points (max 1000 = 10%)
    /// @param _sellTaxBps Sell tax in basis points (max 1000 = 10%)
    constructor(
        address _poolRegistry,
        address _owner,
        uint256 _buyTaxBps,
        uint256 _sellTaxBps
    ) BaseOptical(_poolRegistry, _owner) {
        if (_buyTaxBps > MAX_TAX_BPS) revert TaxTooHigh();
        if (_sellTaxBps > MAX_TAX_BPS) revert TaxTooHigh();
        buyTaxBps = _buyTaxBps;
        sellTaxBps = _sellTaxBps;
    }

    /// @inheritdoc IOptical
    function getFlags() external pure override returns (uint8) {
        return BitFlag.BEFORE_SWAP;
    }

    /// @inheritdoc IOptical
    function beforeSwap(
        address pool, /* pool */
        address, /* sender */
        bool isBuy,
        uint256 amountIn
    ) external view override onlyAttachedPool(pool) returns (bool proceed, int256 amountDelta) {
        uint256 taxBps = isBuy ? buyTaxBps : sellTaxBps;

        if (taxBps == 0) {
            return (true, 0);
        }

        // Calculate tax amount and return as negative delta
        uint256 taxAmount = (amountIn * taxBps) / 10000;
        return (true, -int256(taxAmount));
    }
}

contracts/periphery/FeesRouter.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../base/ReentrancyGuard.sol";
import "../interfaces/IFeesRouter.sol";
import "../interfaces/IFeeAccumulator.sol";
import "../interfaces/ISidioraNFT.sol";
import "../interfaces/ISidioraPool.sol";
import "../interfaces/IPoolRegistry.sol";
import "../interfaces/IEventEmitter.sol";

/// @title FeesRouter
/// @notice NFT-holder interface for fee management.
/// @dev UUPS proxy. Validates NFT ownership, reads strategy, delegates to FeeAccumulator.
contract FeesRouter is IFeesRouter, Initializable, UUPSUpgradeable, AccessControl, ReentrancyGuard {
    event MirrorFailed(bytes4 indexed selector);
    address public nftContract;
    address public feeAccumulator;
    address public poolRegistry;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _nftContract,
        address _feeAccumulator,
        address _poolRegistry,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        if (_nftContract == address(0)) revert ZeroAddress();
        if (_feeAccumulator == address(0)) revert ZeroAddress();

        nftContract = _nftContract;
        feeAccumulator = _feeAccumulator;
        poolRegistry = _poolRegistry;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _initReentrancyGuard();
    }

    /// @inheritdoc IFeesRouter
    function setFeeStrategy(uint256 nftId, uint8 newStrategy) external override {
        _requireNftOwner(nftId);
        if (newStrategy == 2 && !IFeeAccumulator(feeAccumulator).supportsAirdrop(ISidioraNFT(nftContract).getPoolAddress(nftId))) revert UnsupportedSnapshotToken();
        uint8 oldStrategy = ISidioraNFT(nftContract).getFeeStrategy(nftId);
        ISidioraNFT(nftContract).setFeeStrategy(nftId, newStrategy);
        emit FeeStrategyChanged(nftId, oldStrategy, newStrategy);

    }

    /// @inheritdoc IFeesRouter
    function claimFees(uint256 nftId) external override nonReentrant returns (uint256 amount) {
        _requireNftOwner(nftId);
        _requireStrategy(nftId, 0); // CLAIM = 0

        address pool = ISidioraNFT(nftContract).getPoolAddress(nftId);
        amount = IFeeAccumulator(feeAccumulator).claim(pool, msg.sender);

        emit FeesClaimed(nftId, msg.sender, amount);
        _mirrorDistribution(nftId, pool, 0, amount, msg.sender);
    }

    /// @inheritdoc IFeesRouter
    function executeBurn(uint256 nftId) external override nonReentrant returns (uint256 amount) {
        _requireNftOwner(nftId);
        _requireStrategy(nftId, 1); // BURN = 1

        address pool = ISidioraNFT(nftContract).getPoolAddress(nftId);
        amount = IFeeAccumulator(feeAccumulator).burn(pool);

        emit FeesBurned(nftId, amount);
        _mirrorDistribution(nftId, pool, 1, amount, 0x000000000000000000000000000000000000dEaD);
    }

    /// @inheritdoc IFeesRouter
    function executeAirdrop(uint256 nftId) external override nonReentrant returns (uint256 amount) {
        _requireNftOwner(nftId);
        _requireStrategy(nftId, 2); // AIRDROP = 2

        address pool = ISidioraNFT(nftContract).getPoolAddress(nftId);
        amount = IFeeAccumulator(feeAccumulator).triggerAirdrop(pool);

        emit AirdropExecuted(nftId, amount);
        _mirrorDistribution(nftId, pool, 2, amount, address(0));
    }

    /// @inheritdoc IFeesRouter
    function claimAirdrop(uint256 nftId) external override nonReentrant returns (uint256 amount) {
        // Any token holder can claim — no NFT ownership check
        address pool = ISidioraNFT(nftContract).getPoolAddress(nftId);
        amount = IFeeAccumulator(feeAccumulator).claimAirdrop(pool, msg.sender);

        emit AirdropClaimed(nftId, msg.sender, amount);
    }

    function claimAirdropEpoch(uint256 nftId, uint256 epoch) external override nonReentrant returns (uint256 amount) {
        address pool = ISidioraNFT(nftContract).getPoolAddress(nftId);
        amount = IFeeAccumulator(feeAccumulator).claimAirdropEpoch(pool, msg.sender, epoch);
        emit AirdropClaimed(nftId, msg.sender, amount);
    }

    /// @inheritdoc IFeesRouter
    function executeLpRewards(uint256 nftId) external override nonReentrant returns (uint256 amount) {
        _requireNftOwner(nftId);
        _requireStrategy(nftId, 3); // LP_REWARDS = 3

        address pool = ISidioraNFT(nftContract).getPoolAddress(nftId);
        amount = IFeeAccumulator(feeAccumulator).sendLpRewards(pool);

        // Trigger syncReserves on pool so it picks up the new USDL
        ISidioraPool(pool).syncReserves();

        emit LpRewardsExecuted(nftId, amount);
        _mirrorDistribution(nftId, pool, 3, amount, pool);
    }

    function _mirrorDistribution(uint256 nftId, address pool, uint8 strategy, uint256 amount, address recipient) internal {
        _mirror(abi.encodeWithSelector(IEventEmitter.emitFeeDistributed.selector, bytes32(uint256(uint160(pool))), nftId, strategy, amount, recipient));
    }

    function _mirror(bytes memory payload) internal {
        (bool ok, bytes memory data) = feeAccumulator.staticcall(abi.encodeWithSignature("eventEmitter()"));
        if (!ok || data.length != 32) return;
        address hub = abi.decode(data, (address));
        if (hub == address(0)) return;
        (ok,) = hub.call(payload);
        if (!ok) {
            bytes4 selector;
            assembly { selector := mload(add(payload, 32)) }
            emit MirrorFailed(selector);
        }
    }

    // --- Internal ---

    function _requireNftOwner(uint256 nftId) internal view {
        (bool success, bytes memory data) = nftContract.staticcall(
            abi.encodeWithSignature("ownerOf(uint256)", nftId)
        );
        if (!success || data.length < 32) revert NotNftOwner();
        address owner = abi.decode(data, (address));
        if (owner != msg.sender) revert NotNftOwner();
    }

    function _requireStrategy(uint256 nftId, uint8 expectedStrategy) internal view {
        uint8 currentStrategy = ISidioraNFT(nftContract).getFeeStrategy(nftId);
        if (currentStrategy != expectedStrategy) revert WrongStrategy();
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/periphery/Quoter.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../interfaces/IQuoter.sol";
import "../interfaces/ISidioraPool.sol";
import "../interfaces/IProtocolConfig.sol";
import "../interfaces/IPoolRegistry.sol";
import "../libraries/ReserveLib.sol";
import "../libraries/FeeLib.sol";
import "../libraries/SidioraMath.sol";

/// @title Quoter
/// @notice Read-only quote and data access. No state changes. Gas-free via staticcall.
/// @dev UUPS proxy. All functions are view — no state mutations.
contract Quoter is IQuoter, Initializable, UUPSUpgradeable, AccessControl {
    error ZeroAddress();
    error UnexecutableQuote();
    error OpticalQuoteUnsupported();

    address public poolRegistry;
    address public protocolConfig;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _poolRegistry,
        address _protocolConfig,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        if (_poolRegistry == address(0)) revert ZeroAddress();

        poolRegistry = _poolRegistry;
        protocolConfig = _protocolConfig;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
    }

    /// @inheritdoc IQuoter
    function quoteExactInput(
        address pool,
        uint256 amountIn,
        bool isBuy
    ) external view override returns (QuoteResult memory result) {
        _validatePool(pool);
        (uint256 virtualUsdl, uint256 realUsdl, uint256 tokenRes) = ISidioraPool(pool).getReserves();
        uint256 effectiveUsdl = virtualUsdl + realUsdl;

        // Calculate fee
        uint256 feeBps = _calculateFee(pool);
        result.feeAmount = SidioraMath.mulDiv(amountIn, feeBps, 10000);
        uint256 amountInAfterFee = amountIn - result.feeAmount;

        // Calculate output
        if (isBuy) {
            result.amountOut = ReserveLib.getAmountOut(effectiveUsdl, tokenRes, amountInAfterFee);
        } else {
            result.amountOut = ReserveLib.getAmountOut(tokenRes, effectiveUsdl, amountInAfterFee);
            if (result.amountOut > realUsdl) revert UnexecutableQuote();
        }

        if (result.amountOut == 0) revert UnexecutableQuote();

        // Calculate price impact in bps
        // Price impact = |newPrice - oldPrice| / oldPrice * 10000
        if (tokenRes > 0 && effectiveUsdl > 0 && ReserveLib.getPrice(effectiveUsdl, tokenRes) > 0) {
            uint256 priceBefore = ReserveLib.getPrice(effectiveUsdl, tokenRes);
            uint256 newEffectiveUsdl;
            uint256 newTokenRes;
            if (isBuy) {
                newEffectiveUsdl = effectiveUsdl + amountInAfterFee;
                newTokenRes = tokenRes - result.amountOut;
            } else {
                newEffectiveUsdl = effectiveUsdl - result.amountOut;
                newTokenRes = tokenRes + amountIn;
            }
            if (newTokenRes > 0) {
                uint256 priceAfter = ReserveLib.getPrice(newEffectiveUsdl, newTokenRes);
                if (priceAfter > priceBefore) {
                    result.priceImpactBps = SidioraMath.mulDiv(priceAfter - priceBefore, 10000, priceBefore);
                } else {
                    result.priceImpactBps = SidioraMath.mulDiv(priceBefore - priceAfter, 10000, priceBefore);
                }
            }
        }
    }

    /// @inheritdoc IQuoter
    function getPoolPrice(address pool) external view override returns (uint256) {
        return ISidioraPool(pool).getPrice();
    }

    /// @inheritdoc IQuoter
    function getPoolStats(address pool) external view override returns (PoolStats memory stats) {
        (stats.virtualUsdl, stats.realUsdl, stats.tokenReserve) = ISidioraPool(pool).getReserves();
        stats.cumulativeVolume = ISidioraPool(pool).cumulativeVolume();
        stats.currentFeeBps = _calculateFee(pool);
        stats.poolAge = block.timestamp - ISidioraPool(pool).creationTimestamp();
        stats.price = ISidioraPool(pool).getPrice();

        // Market cap = price * totalSupply / 1e18
        uint256 effectiveUsdl = stats.virtualUsdl + stats.realUsdl;
        if (stats.tokenReserve > 0) {
            // Get total supply from token
            address tokenAddr = ISidioraPool(pool).tokenAddress();
            uint256 totalSupply = _getTokenTotalSupply(tokenAddr);
            stats.marketCap = ReserveLib.getMarketCap(effectiveUsdl, stats.tokenReserve, totalSupply);
        }
    }

    /// @inheritdoc IQuoter
    function getMarketCap(address pool) external view override returns (uint256) {
        (uint256 virtualUsdl, uint256 realUsdl, uint256 tokenRes) = ISidioraPool(pool).getReserves();
        uint256 effectiveUsdl = virtualUsdl + realUsdl;
        address tokenAddr = ISidioraPool(pool).tokenAddress();
        uint256 totalSupply = _getTokenTotalSupply(tokenAddr);
        return ReserveLib.getMarketCap(effectiveUsdl, tokenRes, totalSupply);
    }

    /// @inheritdoc IQuoter
    function getAllPools(uint256 offset, uint256 limit) external view override returns (address[] memory) {
        return IPoolRegistry(poolRegistry).getAllPools(offset, limit);
    }

    /// @inheritdoc IQuoter
    function getPoolsByCreator(address creator) external view override returns (address[] memory) {
        return IPoolRegistry(poolRegistry).getPoolsByCreator(creator);
    }

    /// @inheritdoc IQuoter
    function quoteMultihop(
        address tokenIn,
        address tokenOut,
        uint256 amountIn
    ) external view override returns (MultihopQuoteResult memory result) {
        if (tokenIn == address(0) || tokenOut == address(0)) revert ZeroAddress();
        if (tokenIn == tokenOut) revert ZeroAddress(); // reuse error for simplicity

        // Resolve pools
        result.poolA = IPoolRegistry(poolRegistry).getPoolByToken(tokenIn);
        result.poolB = IPoolRegistry(poolRegistry).getPoolByToken(tokenOut);
        if (result.poolA == address(0) || result.poolB == address(0)) revert ZeroAddress();

        _validatePool(result.poolA);
        _validatePool(result.poolB);

        // ── LEG 1: Sell tokenIn → USDL on poolA ──
        (
            uint256 virtualUsdlA,
            uint256 realUsdlA,
            uint256 tokenResA
        ) = ISidioraPool(result.poolA).getReserves();
        uint256 effectiveUsdlA = virtualUsdlA + realUsdlA;

        uint256 feeBpsA = _calculateFee(result.poolA);
        result.sellFeeAmount = SidioraMath.mulDiv(amountIn, feeBpsA, 10000);
        uint256 amountInAfterFeeA = amountIn - result.sellFeeAmount;

        // Sell: tokenReserve is reserveIn, effectiveUsdl is reserveOut
        result.intermediateUsdl = ReserveLib.getAmountOut(tokenResA, effectiveUsdlA, amountInAfterFeeA);

        if (result.intermediateUsdl == 0 || result.intermediateUsdl > realUsdlA) revert UnexecutableQuote();

        // Sell price impact
        if (tokenResA > 0 && effectiveUsdlA > 0 && ReserveLib.getPrice(effectiveUsdlA, tokenResA) > 0) {
            uint256 priceBeforeA = ReserveLib.getPrice(effectiveUsdlA, tokenResA);
            uint256 newEffUsdlA = effectiveUsdlA - result.intermediateUsdl;
            uint256 newTokenResA = tokenResA + amountIn;
            if (newTokenResA > 0 && newEffUsdlA > 0) {
                uint256 priceAfterA = ReserveLib.getPrice(newEffUsdlA, newTokenResA);
                result.sellPriceImpactBps = priceBeforeA > priceAfterA
                    ? SidioraMath.mulDiv(priceBeforeA - priceAfterA, 10000, priceBeforeA)
                    : SidioraMath.mulDiv(priceAfterA - priceBeforeA, 10000, priceBeforeA);
            }
        }

        // ── LEG 2: Buy tokenOut with USDL on poolB ──
        (
            uint256 virtualUsdlB,
            uint256 realUsdlB,
            uint256 tokenResB
        ) = ISidioraPool(result.poolB).getReserves();
        uint256 effectiveUsdlB = virtualUsdlB + realUsdlB;

        uint256 feeBpsB = _calculateFee(result.poolB);
        result.buyFeeAmount = SidioraMath.mulDiv(result.intermediateUsdl, feeBpsB, 10000);
        uint256 amountInAfterFeeB = result.intermediateUsdl - result.buyFeeAmount;

        // Buy: effectiveUsdl is reserveIn, tokenReserve is reserveOut
        result.amountOut = ReserveLib.getAmountOut(effectiveUsdlB, tokenResB, amountInAfterFeeB);

        if (result.amountOut == 0) revert UnexecutableQuote();

        // Buy price impact
        if (tokenResB > 0 && effectiveUsdlB > 0 && ReserveLib.getPrice(effectiveUsdlB, tokenResB) > 0) {
            uint256 priceBeforeB = ReserveLib.getPrice(effectiveUsdlB, tokenResB);
            uint256 newEffUsdlB = effectiveUsdlB + amountInAfterFeeB;
            uint256 newTokenResB = tokenResB - result.amountOut;
            if (newTokenResB > 0) {
                uint256 priceAfterB = ReserveLib.getPrice(newEffUsdlB, newTokenResB);
                result.buyPriceImpactBps = priceAfterB > priceBeforeB
                    ? SidioraMath.mulDiv(priceAfterB - priceBeforeB, 10000, priceBeforeB)
                    : SidioraMath.mulDiv(priceBeforeB - priceAfterB, 10000, priceBeforeB);
            }
        }

        // Combined price impact (additive approximation)
        result.combinedPriceImpactBps = result.sellPriceImpactBps + result.buyPriceImpactBps;
    }

    // --- Internal ---

    function _calculateFee(address pool) internal view returns (uint256) {
        return ISidioraPool(pool).currentFeeBps();
    }

    /// @dev Hooks can reject or adjust trades based on trader-specific state. A generic
    ///      view quote cannot promise execution; fail explicitly rather than overquote.
    function _validatePool(address pool) internal view {
        if (!IPoolRegistry(poolRegistry).isRegisteredPool(pool)) revert UnexecutableQuote();
        if (ISidioraPool(pool).opticalAddress() != address(0)) revert OpticalQuoteUnsupported();
        (bool ok, bytes memory data) = pool.staticcall(abi.encodeWithSignature("paused()"));
        if (!ok || data.length != 32 || abi.decode(data, (bool))) revert UnexecutableQuote();
    }

    function _getTokenTotalSupply(address token) internal view returns (uint256) {
        (bool success, bytes memory data) = token.staticcall(
            abi.encodeWithSignature("totalSupply()")
        );
        if (!success || data.length != 32 || token.code.length == 0) revert UnexecutableQuote();
        return abi.decode(data, (uint256));
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/periphery/Router.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";
import "../base/ReentrancyGuard.sol";
import "../base/Multicall.sol";
import "../interfaces/IRouter.sol";
import "../interfaces/ISidioraPool.sol";
import "../interfaces/ISidioraFactory.sol";
import "../interfaces/IPoolRegistry.sol";
import "../interfaces/IProtocolConfig.sol";
import "../libraries/TransferHelper.sol";
import "../interfaces/ITreasury.sol";
import "../interfaces/IEventEmitter.sol";

/// @title Router
/// @notice User-facing entry point for ALL protocol interactions.
/// @dev UUPS proxy. Handles validation, token transfers, and delegates to core contracts.
///      Inherits Multicall for batching (e.g., create + buy in one tx).
///      Supports EIP-2612 permit for gasless approvals and multihop Token→USDL→Token swaps.
contract Router is IRouter, Initializable, UUPSUpgradeable, AccessControl, ReentrancyGuard, Multicall {
    address public factory;
    address public poolRegistry;
    address public protocolConfig;
    address public usdlAddress;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _factory,
        address _poolRegistry,
        address _protocolConfig,
        address _usdlAddress,
        address _admin
    ) external initializer {
        if (_admin == address(0)) revert ZeroAddress();
        if (_factory == address(0)) revert ZeroAddress();
        if (_poolRegistry == address(0)) revert ZeroAddress();
        if (_usdlAddress.code.length == 0 || _protocolConfig.code.length == 0 || _factory.code.length == 0 || _poolRegistry.code.length == 0) revert ZeroAddress();

        factory = _factory;
        poolRegistry = _poolRegistry;
        protocolConfig = _protocolConfig;
        usdlAddress = _usdlAddress;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _initReentrancyGuard();
    }

    // ============ CORE ============

    /// @inheritdoc IRouter
    function createMarket(
        string calldata name,
        string calldata symbol,
        uint8 feeStrategy,
        address optical
    ) external override nonReentrant returns (address tokenAddr, address poolAddr, uint256 nftId) {
        return _createMarket(name, symbol, feeStrategy, optical);
    }

    /// @inheritdoc IRouter
    function buy(
        address pool,
        uint256 usdlAmountIn,
        uint256 minTokensOut,
        uint256 deadline
    ) external override nonReentrant returns (uint256 amountOut) {
        return _buy(pool, usdlAmountIn, minTokensOut, deadline);
    }

    /// @inheritdoc IRouter
    function sell(
        address pool,
        uint256 tokenAmountIn,
        uint256 minUsdlOut,
        uint256 deadline
    ) external override nonReentrant returns (uint256 amountOut) {
        return _sell(pool, tokenAmountIn, minUsdlOut, deadline);
    }

    // ============ MULTIHOP ============

    /// @inheritdoc IRouter
    function swapTokenForToken(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline
    ) external override nonReentrant returns (uint256 amountOut, uint256 intermediateUsdl) {
        return _swapTokenForToken(tokenIn, tokenOut, amountIn, minAmountOut, deadline);
    }

    // ============ PERMIT VARIANTS ============

    /// @inheritdoc IRouter
    function buyWithPermit(
        address pool,
        uint256 usdlAmountIn,
        uint256 minTokensOut,
        uint256 deadline,
        PermitParams calldata permit
    ) external override nonReentrant returns (uint256 amountOut) {
        _executePermit(usdlAddress, msg.sender, address(this), permit);
        return _buy(pool, usdlAmountIn, minTokensOut, deadline);
    }

    /// @inheritdoc IRouter
    function sellWithPermit(
        address pool,
        uint256 tokenAmountIn,
        uint256 minUsdlOut,
        uint256 deadline,
        PermitParams calldata permit
    ) external override nonReentrant returns (uint256 amountOut) {
        if (!_isRegisteredPool(pool)) revert PoolNotFound();
        address tokenAddr = ISidioraPool(pool).tokenAddress();
        _executePermit(tokenAddr, msg.sender, address(this), permit);
        return _sell(pool, tokenAmountIn, minUsdlOut, deadline);
    }

    /// @inheritdoc IRouter
    function swapTokenForTokenWithPermit(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline,
        PermitParams calldata permit
    ) external override nonReentrant returns (uint256 amountOut, uint256 intermediateUsdl) {
        _executePermit(tokenIn, msg.sender, address(this), permit);
        return _swapTokenForToken(tokenIn, tokenOut, amountIn, minAmountOut, deadline);
    }

    /// @inheritdoc IRouter
    function createMarketWithPermit(
        string calldata name,
        string calldata symbol,
        uint8 feeStrategy,
        address optical,
        PermitParams calldata permit
    ) external override nonReentrant returns (address tokenAddr, address poolAddr, uint256 nftId) {
        _executePermit(usdlAddress, msg.sender, address(this), permit);
        return _createMarket(name, symbol, feeStrategy, optical);
    }

    // ============ INTERNAL: CORE LOGIC ============

    function _createMarket(
        string calldata name,
        string calldata symbol,
        uint8 feeStrategy,
        address optical
    ) internal returns (address tokenAddr, address poolAddr, uint256 nftId) {
        // Transfer creation fee from user directly to treasury
        uint256 creationFee = IProtocolConfig(protocolConfig).creationFee();
        if (creationFee > 0) {
            address treasuryAddr = ISidioraFactory(factory).treasury();
            TransferHelper.safeTransferFrom(usdlAddress, msg.sender, treasuryAddr, creationFee);
            ITreasury(treasuryAddr).recordDeposit(usdlAddress, creationFee);
        }

        // Delegate to factory with explicit creator
        (tokenAddr, poolAddr, nftId) = ISidioraFactory(factory).createMarketFor(
            msg.sender, name, symbol, feeStrategy, optical
        );

        emit MarketCreated(tokenAddr, poolAddr, msg.sender, nftId);
    }

    function _buy(
        address pool,
        uint256 usdlAmountIn,
        uint256 minTokensOut,
        uint256 deadline
    ) internal returns (uint256 amountOut) {
        if (block.timestamp > deadline) revert DeadlineExpired();
        if (usdlAmountIn == 0) revert ZeroAmount();
        if (pool == address(0)) revert ZeroAddress();
        if (!_isRegisteredPool(pool)) revert PoolNotFound();

        TransferHelper.safeTransferFrom(usdlAddress, msg.sender, pool, usdlAmountIn);

        amountOut = ISidioraPool(pool).swapFor(
            usdlAmountIn,
            minTokensOut,
            true,
            msg.sender,
            msg.sender,
            deadline
        );

        emit Buy(pool, msg.sender, usdlAmountIn, amountOut);
        _mirrorTrade(0, pool, usdlAddress, ISidioraPool(pool).tokenAddress(), usdlAmountIn, amountOut, 0);
    }

    function _sell(
        address pool,
        uint256 tokenAmountIn,
        uint256 minUsdlOut,
        uint256 deadline
    ) internal returns (uint256 amountOut) {
        if (block.timestamp > deadline) revert DeadlineExpired();
        if (tokenAmountIn == 0) revert ZeroAmount();
        if (pool == address(0)) revert ZeroAddress();
        if (!_isRegisteredPool(pool)) revert PoolNotFound();

        address tokenAddr = ISidioraPool(pool).tokenAddress();
        TransferHelper.safeTransferFrom(tokenAddr, msg.sender, pool, tokenAmountIn);

        amountOut = ISidioraPool(pool).swapFor(
            tokenAmountIn,
            minUsdlOut,
            false,
            msg.sender,
            msg.sender,
            deadline
        );

        emit Sell(pool, msg.sender, tokenAmountIn, amountOut);
        _mirrorTrade(1, pool, tokenAddr, usdlAddress, tokenAmountIn, amountOut, 0);
    }

    /// @dev Executes Token A → USDL → Token B atomically.
    ///      Leg 1: Sell tokenIn on poolA, Router receives USDL.
    ///      Leg 2: Buy tokenOut on poolB with intermediate USDL, user receives tokenOut.
    function _swapTokenForToken(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline
    ) internal returns (uint256 amountOut, uint256 intermediateUsdl) {
        if (block.timestamp > deadline) revert DeadlineExpired();
        if (amountIn == 0) revert ZeroAmount();
        if (tokenIn == tokenOut) revert SameToken();
        if (tokenIn == address(0) || tokenOut == address(0)) revert ZeroAddress();

        // Resolve pools via PoolRegistry
        address poolA = IPoolRegistry(poolRegistry).getPoolByToken(tokenIn);
        address poolB = IPoolRegistry(poolRegistry).getPoolByToken(tokenOut);
        if (poolA == address(0) || poolB == address(0)) revert PoolNotFound();

        // ── LEG 1: Sell tokenIn → USDL (Router is the recipient) ──
        TransferHelper.safeTransferFrom(tokenIn, msg.sender, poolA, amountIn);

        intermediateUsdl = ISidioraPool(poolA).swapFor(
            amountIn,
            0, // No intermediate slippage — end-to-end check on leg 2
            false, // isSell
            msg.sender, // Actual trader
            address(this), // Router receives USDL
            deadline
        );

        // ── LEG 2: Buy tokenOut with USDL (user is the recipient) ──
        TransferHelper.safeTransfer(usdlAddress, poolB, intermediateUsdl);

        amountOut = ISidioraPool(poolB).swapFor(
            intermediateUsdl,
            minAmountOut, // End-to-end slippage protection
            true, // isBuy
            msg.sender, // Actual trader
            msg.sender, // User receives tokenOut
            deadline
        );

        emit MultihopSwap(msg.sender, tokenIn, tokenOut, amountIn, intermediateUsdl, amountOut);
        _mirrorTrade(2, poolA, tokenIn, tokenOut, amountIn, amountOut, intermediateUsdl);
    }

    // ============ INTERNAL: HELPERS ============

    function _mirrorTrade(uint8 kind, address pool, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut, uint256 intermediate) internal {
        address emitter = ISidioraFactory(factory).eventEmitter();
        if (emitter != address(0)) IEventEmitter(emitter).emitRouterTrade(kind, pool, msg.sender, tokenIn, tokenOut, amountIn, amountOut, intermediate);
    }

    function _isRegisteredPool(address pool) internal view returns (bool) {
        return IPoolRegistry(poolRegistry).isRegisteredPool(pool);
    }

    /// @dev Calls EIP-2612 permit on a token. Fails silently if permit reverts
    ///      (e.g., nonce already used, token doesn't support permit) to avoid
    ///      griefing via front-run permit.
    function _executePermit(
        address token,
        address owner_,
        address spender,
        PermitParams calldata permit
    ) internal {
        (bool success, ) = token.call(
            abi.encodeWithSignature(
                "permit(address,address,uint256,uint256,uint8,bytes32,bytes32)",
                owner_,
                spender,
                permit.value,
                permit.deadline,
                permit.v,
                permit.r,
                permit.s
            )
        );
        // Intentionally not reverting on failure — permit may have been
        // front-run or already executed, and the subsequent transferFrom
        // will revert if allowance is insufficient.
        (success); // Silence unused variable warning
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

contracts/protocol/EmergencyPauseControl.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import {AccessControl} from "../base/AccessControl.sol";
import {ReentrancyGuard} from "../base/ReentrancyGuard.sol";

/// @notice Incident responders can halt allowlisted endpoints. Recovery and
/// target/guardian management remain with the Timelock administrator.
/// @dev No arbitrary calldata, upgrades, custody, or unpause entry point.
contract EmergencyPauseController is AccessControl, ReentrancyGuard {
    bytes32 public constant INCIDENT_GUARDIAN_ROLE = keccak256("INCIDENT_GUARDIAN_ROLE");
    uint256 public constant MAX_TARGETS = 32;
    uint256 public constant TARGET_CALL_GAS = 150_000;
    uint256 public constant STATUS_CALL_GAS = 30_000;
    bytes4 private constant STATUS_SELECTOR = bytes4(keccak256("emergencyPaused()"));
    bytes4 private constant PAUSE_SELECTOR = bytes4(keccak256("pause()"));
    mapping(address => bool) public allowedTargets;

    enum PauseStatus { Paused, AlreadyPaused, NotAllowed, InvalidStatus, CallFailed, PostconditionFailed }
    error InvalidTarget();
    error InvalidBatchLength();
    error InsufficientIncidentGas();
    event TargetUpdated(address indexed target, bool allowed);
    event IncidentTargetResult(bytes32 indexed incidentId, address indexed target, PauseStatus status);
    event IncidentProcessed(bytes32 indexed incidentId, address indexed responder, uint256 targetCount);

    constructor(address admin, address guardian, address[] memory initialTargets) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(INCIDENT_GUARDIAN_ROLE, guardian);
        if (initialTargets.length > MAX_TARGETS) revert InvalidBatchLength();
        for (uint256 i; i < initialTargets.length; ++i) _setTarget(initialTargets[i], true);
    }

    function setTarget(address target, bool allowed) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _setTarget(target, allowed);
    }

    function _setTarget(address target, bool allowed) private {
        if (target == address(0) || (allowed && target.code.length == 0)) revert InvalidTarget();
        allowedTargets[target] = allowed;
        emit TargetUpdated(target, allowed);
    }

    function pauseTargets(address[] calldata targets, bytes32 incidentId)
        external onlyRole(INCIDENT_GUARDIAN_ROLE) nonReentrant
    {
        uint256 length = targets.length;
        if (length == 0 || length > MAX_TARGETS) revert InvalidBatchLength();
        // Reserve the full bounded worst-case budget up front. A caller-provided
        // undersized gas limit must not silently leave late targets untreated.
        if (gasleft() < length * 250_000 + 50_000) revert InsufficientIncidentGas();
        for (uint256 i; i < length; ++i) {
            address target = targets[i];
            PauseStatus result;
            if (!allowedTargets[target]) result = PauseStatus.NotAllowed;
            else {
                (bool valid, bool paused) = _status(target);
                if (!valid) result = PauseStatus.InvalidStatus;
                else if (paused) result = PauseStatus.AlreadyPaused;
                else if (!_callPause(target)) result = PauseStatus.CallFailed;
                else {
                    (valid, paused) = _status(target);
                    result = valid && paused ? PauseStatus.Paused : PauseStatus.PostconditionFailed;
                }
            }
            emit IncidentTargetResult(incidentId, target, result);
        }
        emit IncidentProcessed(incidentId, msg.sender, length);
    }

    function _status(address target) private view returns (bool valid, bool paused) {
        bytes4 selector = STATUS_SELECTOR;
        uint256 value;
        uint256 size;
        uint256 budget = STATUS_CALL_GAS;
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, selector)
            valid := staticcall(budget, target, ptr, 4, ptr, 32)
            size := returndatasize()
            value := mload(ptr)
        }
        valid = valid && size == 32 && value <= 1;
        paused = value == 1;
    }

    function _callPause(address target) private returns (bool success) {
        bytes4 selector = PAUSE_SELECTOR;
        uint256 budget = TARGET_CALL_GAS;
        // Output length zero prevents a target's return/revert payload from
        // allocating unbounded memory in the incident controller.
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, selector)
            success := call(budget, target, 0, ptr, 4, 0, 0)
        }
    }
}

contracts/protocol/GovernanceModule.sol.content:
// SPDX-License-Identifier: LicenseRef-Paxlabs-HyperPax-OS-Protocol
pragma solidity ^0.8.24;

import "../base/Initializable.sol";
import "../base/UUPSUpgradeable.sol";
import "../base/AccessControl.sol";

/// @title GovernanceModule
/// @notice Decentralized decision-making for protocol upgrades and parameter changes
/// @dev Dual mode: Admin bypass (initial) + full SID governance (after transition).
///      Proposals that pass are queued to the Timelock for delayed execution.
contract GovernanceModule is Initializable, UUPSUpgradeable, AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    enum ProposalState { Pending, Active, Defeated, Succeeded, Queued, Executed, Cancelled, Expired }

    struct Proposal {
        address proposer;
        address[] targets;
        uint256[] values;
        bytes[] calldatas;
        string description;
        uint256 startBlock;
        uint256 endBlock;
        uint256 forVotes;
        uint256 againstVotes;
        bool executed;
        bool cancelled;
    }

    address public votingToken; // SID token
    address public timelock;

    uint256 public proposalThreshold; // min SID balance to propose
    uint256 public votingPeriod; // blocks
    uint256 public quorumVotes; // min votes for quorum

    uint256 public proposalCount;
    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    mapping(uint256 => mapping(address => uint256)) public voteSnapshot; // snapshot of voter balance

    bool public adminModeActive; // true = admin can bypass governance
    mapping(uint256 => bytes32) public proposalOperation;
    mapping(uint256 => uint256) public proposalEta;

    error BelowProposalThreshold();
    error AlreadyVoted();
    error VotingClosed();
    error QuorumNotMet();
    error ProposalNotPassed();
    error ProposalAlreadyExecuted();
    error ProposalIsCancelled();
    error InvalidProposal();
    error Unauthorized();
    error AdminModeNotActive();
    error ArrayLengthMismatch();

    event ProposalCreated(uint256 indexed proposalId, address indexed proposer, string description);
    event VoteCast(uint256 indexed proposalId, address indexed voter, bool support, uint256 weight);
    event ProposalExecuted(uint256 indexed proposalId);
    event ProposalQueued(uint256 indexed proposalId, bytes32 indexed operationId, uint256 eta);
    event ProposalCancelled(uint256 indexed proposalId);
    event AdminModeDeactivated();

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _votingToken,
        address _timelock,
        address _admin,
        uint256 _proposalThreshold,
        uint256 _votingPeriod,
        uint256 _quorumVotes
    ) external initializer {
        if (_admin == address(0) || _votingToken.code.length == 0 || _timelock.code.length == 0) revert InvalidProposal();
        if (_proposalThreshold == 0 || _quorumVotes == 0 || _votingPeriod == 0 || _votingPeriod > 2_000_000) revert InvalidProposal();
        // Fail deployment early unless the token exposes historical checkpoint voting.
        IVotingCheckpoints(_votingToken).getPastVotes(address(this), block.number - 1);
        ITimelockQueue(_timelock).getMinDelay();
        votingToken = _votingToken;
        timelock = _timelock;
        proposalThreshold = _proposalThreshold;
        votingPeriod = _votingPeriod;
        quorumVotes = _quorumVotes;
        adminModeActive = true;

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);
    }

    /// @notice Create a proposal (requires SID balance >= proposalThreshold)
    function propose(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256 proposalId) {
        if (targets.length == 0) revert InvalidProposal();
        if (targets.length != values.length || targets.length != calldatas.length) revert ArrayLengthMismatch();

        uint256 balance = IVotingCheckpoints(votingToken).getPastVotes(msg.sender, block.number - 1);
        if (balance < proposalThreshold) revert BelowProposalThreshold();

        proposalId = ++proposalCount;
        Proposal storage p = proposals[proposalId];
        p.proposer = msg.sender;
        p.targets = targets;
        p.values = values;
        p.calldatas = calldatas;
        p.description = description;
        p.startBlock = block.number + 1;
        p.endBlock = block.number + 1 + votingPeriod;

        emit ProposalCreated(proposalId, msg.sender, description);
    }

    /// @notice Vote on a proposal
    function castVote(uint256 proposalId, bool support) external {
        _requireProposal(proposalId);
        Proposal storage p = proposals[proposalId];
        if (block.number < p.startBlock || block.number > p.endBlock) revert VotingClosed();
        if (p.cancelled) revert ProposalIsCancelled();
        if (hasVoted[proposalId][msg.sender]) revert AlreadyVoted();

        uint256 weight = IVotingCheckpoints(votingToken).getPastVotes(msg.sender, p.startBlock - 1);
        hasVoted[proposalId][msg.sender] = true;
        voteSnapshot[proposalId][msg.sender] = weight;

        if (support) {
            p.forVotes += weight;
        } else {
            p.againstVotes += weight;
        }

        emit VoteCast(proposalId, msg.sender, support, weight);
    }

    /// @notice Queue a passed proposal as a single atomic Timelock operation.
    /// @dev The legacy ETA argument is ignored; the Timelock computes the delay.
    function execute(uint256 proposalId, uint256) external {
        _requireProposal(proposalId);
        Proposal storage p = proposals[proposalId];
        if (p.executed || proposalOperation[proposalId] != bytes32(0)) revert ProposalAlreadyExecuted();
        if (p.cancelled) revert ProposalIsCancelled();
        if (block.number <= p.endBlock) revert VotingClosed();
        if (p.forVotes < quorumVotes) revert QuorumNotMet();
        if (p.forVotes <= p.againstVotes) revert ProposalNotPassed();
        (bytes32 id, uint256 eta) = ITimelockQueue(timelock).queueBatch(p.targets, p.values, p.calldatas, bytes32(proposalId));
        proposalOperation[proposalId] = id;
        proposalEta[proposalId] = eta;
        emit ProposalQueued(proposalId, id, eta);
    }

    function executeQueued(uint256 proposalId) external {
        _requireProposal(proposalId);
        Proposal storage p = proposals[proposalId];
        ITimelockQueue(timelock).executeBatch(p.targets, p.values, p.calldatas, bytes32(proposalId));
        p.executed = true;
        emit ProposalExecuted(proposalId);
    }

    /// @notice Cancel a proposal (only proposer or admin)
    function cancel(uint256 proposalId) external {
        _requireProposal(proposalId);
        Proposal storage p = proposals[proposalId];
        if (msg.sender != p.proposer && !(adminModeActive && hasRole(ADMIN_ROLE, msg.sender))) revert Unauthorized();
        if (p.executed || (proposalOperation[proposalId] != bytes32(0) && ITimelockQueue(timelock).batchStatus(proposalOperation[proposalId]) == 2)) revert ProposalAlreadyExecuted();
        if (proposalOperation[proposalId] != bytes32(0) && ITimelockQueue(timelock).batchStatus(proposalOperation[proposalId]) == 1) ITimelockQueue(timelock).cancelBatch(proposalOperation[proposalId]);
        p.cancelled = true;
        emit ProposalCancelled(proposalId);
    }

    /// @notice Admin bypasses governance and queues directly to Timelock
    /// @dev Only works while adminModeActive is true
    function adminExecute(
        address target,
        uint256 value,
        bytes calldata data,
        uint256 eta
    ) external onlyRole(ADMIN_ROLE) {
        if (!adminModeActive) revert AdminModeNotActive();
        ITimelockQueue(timelock).queueTransaction(target, value, data, eta);
    }

    /// @notice Deactivate bypass and admin cancellation in this implementation.
    /// @dev Transfer upgrade/default-admin roles to Timelock to complete governance handoff.
    function deactivateAdminMode() external onlyRole(ADMIN_ROLE) {
        adminModeActive = false;
        emit AdminModeDeactivated();
    }

    /// @notice Get the state of a proposal
    function getProposalState(uint256 proposalId) external view returns (ProposalState) {
        _requireProposal(proposalId);
        Proposal storage p = proposals[proposalId];
        bytes32 id = proposalOperation[proposalId];
        if (id != bytes32(0)) {
            uint8 status = ITimelockQueue(timelock).batchStatus(id);
            if (status == 2) return ProposalState.Executed;
            if (status == 3) return ProposalState.Cancelled;
            if (block.timestamp > proposalEta[proposalId] + ITimelockQueue(timelock).GRACE_PERIOD()) return ProposalState.Expired;
            return ProposalState.Queued;
        }
        if (p.cancelled) return ProposalState.Cancelled;
        if (p.executed) return ProposalState.Executed;
        if (block.number < p.startBlock) return ProposalState.Pending;
        if (block.number <= p.endBlock) return ProposalState.Active;
        if (p.forVotes < quorumVotes || p.forVotes <= p.againstVotes) return ProposalState.Defeated;
        return ProposalState.Succeeded;
    }

    function getProposalActions(uint256 proposalId) external view returns (address[] memory, uint256[] memory, bytes[] memory) {
        _requireProposal(proposalId);
        Proposal storage p = proposals[proposalId];
        return (p.targets, p.values, p.calldatas);
    }

    function _requireProposal(uint256 id) internal view {
        if (id == 0 || id > proposalCount) revert InvalidProposal();
    }

    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}
}

interface IVotingCheckpoints {
    function getPastVotes(address account, uint256 blockNumber) external view returns (uint256);
}
interface ITimelockQueue {
    function queueBatch(address[] calldata, uint256[] calldata, bytes[] calldata, bytes32) external returns(bytes32,uint256);
    function executeBatch(address[] calldata, uint256[] calldata, bytes[] calldata, bytes32) external;
    function cancelBatch(bytes32) external;
    function batchStatus(bytes32) external view returns(uint8);
    function getMinDelay() external view returns(uint256);
    function GRACE_PERIOD() external view returns(uint256);
    function queueTransaction(address target, uint256 value, bytes calldata data, uint256 eta) external returns (bytes32);
}

